create or replace function public.placer_ordre(p_cote text, p_type text, p_quantite numeric, p_prix numeric DEFAULT NULL::numeric, p_cle text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform _exiger_aal2();
  return (
  select _placer_ordre(auth.uid(), p_cote, p_type, p_quantite, p_prix, p_cle, null)
  );
end $function$;

-- Le code secret à 4 chiffres ne s'ouvre plus aux clients. Ses fonctions
-- restent pour l'instant (les quatre sorties l'appellent encore) : 0036 les
-- retire avec lui, en remplaçant chaque sortie par la vérification.
-- (Rejouée après 0036, qui les a retirées : il n'y a plus rien à fermer.)
do $$
declare f text;
begin
  foreach f in array array['completer_profil(text, text)', 'verifier_code_secret(text)', 'changer_code_secret(text, text)'] loop
    if to_regprocedure('public.' || f) is not null then
      execute format('revoke execute on function public.%s from authenticated', f);
    end if;
  end loop;
end $$;

-- ─────────────────────── 4 · les tables lisibles ───────────────────────────
-- Une politique RESTRICTIVE s'ajoute (ET) aux politiques de chaque table
-- qu'un client lit : en session faible, aucune ligne. La liste est écrite ici
-- à la main : une table neuve lisible sans cette politique fait échouer 11.58.
-- « (select …) » : la garde est évaluée une fois par requête, pas par ligne.
-- Le temps réel (postgres_changes) applique les mêmes politiques.
do $$ declare t text; begin
  foreach t in array array['administrateurs', 'adresses_crypto', 'comptes', 'depot_declarations', 'depot_paiements', 'depots', 'ecritures',
                           'executions', 'notifications', 'numeros', 'operateurs', 'ordres', 'parametres', 'retraits_crypto', 'soldes',
                           'sorties', 'transferts_crypto'] loop
    execute format('drop policy if exists session_forte on %I', t);
    execute format('create policy session_forte on %I as restrictive for select to authenticated using ((select public.session_forte()))', t);
  end loop;
end $$;

-- ───────────────────────────── 5 · le stockage ─────────────────────────────
-- Les pièces de vérification (0004) : déposer et relire demandent aussi la
-- session forte. Les preuves de sortie (0014) et les relevés des floats
-- (0016) passent par admin_a_droit, qui l'exige déjà.
do $$
begin
  if to_regclass('storage.objects') is null then return; end if;
  execute $p$drop policy if exists verifications_deposer on storage.objects$p$;
  execute $p$drop policy if exists verifications_relire on storage.objects$p$;
  execute $p$create policy verifications_deposer on storage.objects for insert to authenticated
            with check (bucket_id = 'verifications' and (storage.foldername(name))[1] = auth.uid()::text and public.session_forte())$p$;
  execute $p$create policy verifications_relire on storage.objects for select to authenticated
            using (bucket_id = 'verifications' and public.session_forte()
                   and ((storage.foldername(name))[1] = auth.uid()::text or public.admin_a_droit('paliers')))$p$;
end $$;

-- ─────────────────────────── 6 · les codes de secours ──────────────────────
-- Dix codes de dix caractères (alphabet de Crockford : ni I, ni L, ni O, ni
-- U), 50 bits chacun, tirés ici et gardés en empreintes sha256 salées par
-- l'identifiant : des codes de cette entropie n'ont pas besoin de bcrypt. Le
-- texte en clair n'existe qu'une fois, dans la réponse de
-- generer_codes_de_secours, et n'est jamais journalisé.
insert into parametres (cle, valeur) values
  ('codes_de_secours', '{"nombre": 10, "essais": 5, "verrou_minutes": 15, "fraicheur_totp_secondes": 300}')
on conflict (cle) do nothing;

-- un lot par utilisateur Auth (client OU administrateur) : clé = auth.users.id, sans clé étrangère (comme comptes)
create table if not exists lots_de_secours (
  utilisateur_id uuid primary key,
  cree_le        timestamptz not null default now(),
  confirme_le    timestamptz,
  essais_rates   int not null default 0,
  verrou_jusqua  timestamptz
);
create table if not exists codes_de_secours (
  id             bigint generated always as identity primary key,
  utilisateur_id uuid not null,
  empreinte      text not null check (empreinte ~ '^[0-9a-f]{64}$'),
  cree_le        timestamptz not null default now(),
  utilise_le     timestamptz
);
create index if not exists codes_de_secours_libres on codes_de_secours (utilisateur_id) where utilise_le is null;
alter table lots_de_secours enable row level security;
alter table codes_de_secours enable row level security;

-- Le journal de sécurité : ce qui touche aux facteurs d'une personne. Jamais un code.
create table if not exists journal_securite (
  id             bigint generated always as identity primary key,
  utilisateur_id uuid not null,
  evenement      text not null check (evenement in ('codes_generes', 'codes_confirmes', 'code_de_secours_utilise', 'code_de_secours_refuse',
                                                    'deux_facteurs_retires', 'reinitialisation_demandee', 'reinitialisation_echouee')),
  par_admin      uuid,
  detail         jsonb,
  cree_le        timestamptz not null default now()
);
create index if not exists journal_securite_de on journal_securite (utilisateur_id, cree_le desc);
create table if not exists reinitialisations_2fa (
  id             uuid primary key default gen_random_uuid(),
  utilisateur_id uuid not null,
  admin_id       uuid not null,
  motif          text not null check (length(motif) >= 10),
  demandee_le    timestamptz not null default now(),
  faite_le       timestamptz,
  facteurs       int,
  echec          text
);
create index if not exists reinitialisations_2fa_de on reinitialisations_2fa (utilisateur_id, demandee_le desc);
alter table journal_securite enable row level security;
alter table reinitialisations_2fa enable row level security;
revoke all on lots_de_secours, codes_de_secours, journal_securite, reinitialisations_2fa from public, anon, authenticated;
grant all on lots_de_secours, codes_de_secours, journal_securite, reinitialisations_2fa to service_role;

create or replace function _journal_securite(p_utilisateur uuid, p_evenement text, p_admin uuid, p_detail jsonb) returns void
language sql set search_path = public as $$
  insert into journal_securite (utilisateur_id, evenement, par_admin, detail) values (p_utilisateur, p_evenement, p_admin, p_detail)
$$;

-- 256 % 32 = 0 : un octet modulo 32 ne favorise aucune lettre.
create or replace function _code_de_secours_neuf() returns text
language sql volatile set search_path = public, extensions, pg_temp as $$
  select string_agg(substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ', get_byte(x.b, i) % 32 + 1, 1), '' order by i)
    from (select extensions.gen_random_bytes(10) b) x, generate_series(0, 9) i
$$;

-- Ce que la personne recopie : minuscules, espaces et tirets acceptés ; O se
-- lit 0, I et L se lisent 1 (Crockford). Autre chose que dix signes : null.
create or replace function _code_de_secours_normalise(p text) returns text
language sql immutable set search_path = public as $$
  select case when v ~ '^[0-9ABCDEFGHJKMNPQRSTVWXYZ]{10}$' then v end
    from (select translate(regexp_replace(upper(coalesce(p, '')), '[^0-9A-Z]', '', 'g'), 'OIL', '011') v) x
$$;

create or replace function _empreinte_de_secours(p_utilisateur uuid, p_code text) returns text
language sql immutable set search_path = public, extensions, pg_temp as $$
  select encode(extensions.digest(p_utilisateur::text || ':' || p_code, 'sha256'), 'hex')
$$;

-- Un lot neuf. Le premier se tire librement (à l'inscription, avant d'être
-- noté) ; une fois confirmé, le remplacer demande un code TOTP FRAIS : une
-- session volée ne remplace pas les codes de secours de la victime.
create or replace function generer_codes_de_secours() returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  v_uid       uuid := auth.uid();
  v_p         jsonb := parametre('codes_de_secours');
  v_n         int := coalesce((v_p ->> 'nombre')::int, 10);
  v_fraicheur int := coalesce((v_p ->> 'fraicheur_totp_secondes')::int, 300);
  v_lot       lots_de_secours;
  v_codes     text[] := '{}';
  v_code      text;
begin
  perform _exiger_aal2();
  if v_uid is null then raise exception 'non connecté'; end if;
  insert into lots_de_secours (utilisateur_id) values (v_uid) on conflict do nothing;
  select * into v_lot from lots_de_secours where utilisateur_id = v_uid for update;
  if v_lot.confirme_le is not null
     and coalesce(_moment_du_facteur('totp'), '-infinity'::timestamptz) < now() - make_interval(secs => v_fraicheur) then
    raise exception 'confirmez avec votre application d''authentification' using detail = 'entrez un code tout neuf, puis recommencez';
  end if;
  delete from codes_de_secours where utilisateur_id = v_uid;
  while coalesce(array_length(v_codes, 1), 0) < v_n loop
    v_code := _code_de_secours_neuf();
    continue when v_code = any (v_codes);       -- deux fois le même dans un lot : une chance sur 2^47, on retire
    v_codes := v_codes || v_code;
    insert into codes_de_secours (utilisateur_id, empreinte) values (v_uid, _empreinte_de_secours(v_uid, v_code));
  end loop;
  update lots_de_secours set cree_le = now(), confirme_le = null, essais_rates = 0, verrou_jusqua = null where utilisateur_id = v_uid;
  perform _journal_securite(v_uid, 'codes_generes', null, jsonb_build_object('nombre', v_n));
  return jsonb_build_object('codes', (select jsonb_agg(left(c, 5) || '-' || right(c, 5) order by o) from unnest(v_codes) with ordinality u(c, o)),
                            'cree_le', now());
end $$;

-- « Je les ai notés » : sans cette case, ni compte ni administration ne s'ouvrent.
create or replace function confirmer_codes_de_secours() returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_n int;
begin
  perform _exiger_aal2();
  if v_uid is null then raise exception 'non connecté'; end if;
  perform 1 from lots_de_secours where utilisateur_id = v_uid for update;
  if found then
    select count(*) into v_n from codes_de_secours where utilisateur_id = v_uid and utilise_le is null;
  end if;
  if coalesce(v_n, 0) = 0 then raise exception 'aucun code de secours' using detail = 'générez d''abord vos codes'; end if;
  update lots_de_secours set confirme_le = now() where utilisateur_id = v_uid;
  perform _journal_securite(v_uid, 'codes_confirmes', null, jsonb_build_object('restants', v_n));
  return jsonb_build_object('restants', v_n);
end $$;

create or replace function mes_codes_de_secours() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_lot lots_de_secours;
begin
  perform _exiger_aal2();
  if v_uid is null then raise exception 'non connecté'; end if;
  select * into v_lot from lots_de_secours where utilisateur_id = v_uid;
  return jsonb_build_object('confirmes', v_lot.confirme_le is not null,
                            'restants', (select count(*) from codes_de_secours where utilisateur_id = v_uid and utilise_le is null),
                            'cree_le', v_lot.cree_le);
end $$;

-- Pour la fonction deux-facteurs SEULEMENT (clé de service). Elle ne lève
-- jamais : un échec reste compté (le compteur est écrit, puis on répond).
create or replace function _consommer_code_de_secours(p_utilisateur uuid, p_code text) returns jsonb
language plpgsql set search_path = public, extensions, pg_temp as $$
declare
  v_p       jsonb := parametre('codes_de_secours');
  v_essais  int := coalesce((v_p ->> 'essais')::int, 5);
  v_minutes int := coalesce((v_p ->> 'verrou_minutes')::int, 15);
  v_lot     lots_de_secours;
  v_code    text := _code_de_secours_normalise(p_code);
  v_ligne   codes_de_secours;
  v_restants int;
begin
  select * into v_lot from lots_de_secours where utilisateur_id = p_utilisateur for update;
  if not found then return jsonb_build_object('ok', false, 'erreur', 'aucun code de secours'); end if;
  if v_lot.verrou_jusqua is not null and v_lot.verrou_jusqua > now() then
    return jsonb_build_object('ok', false, 'erreur', 'trop d''essais', 'essais_restants', 0, 'verrou_jusqua', v_lot.verrou_jusqua);
  end if;
  if v_code is not null then
    select * into v_ligne from codes_de_secours
     where utilisateur_id = p_utilisateur and utilise_le is null and empreinte = _empreinte_de_secours(p_utilisateur, v_code)
     limit 1 for update;
  end if;
  if v_ligne.id is null then
    if v_lot.essais_rates + 1 >= v_essais then
      update lots_de_secours set essais_rates = 0, verrou_jusqua = now() + make_interval(mins => v_minutes) where utilisateur_id = p_utilisateur;
      perform _journal_securite(p_utilisateur, 'code_de_secours_refuse', null, jsonb_build_object('verrou', true));
      return jsonb_build_object('ok', false, 'erreur', 'trop d''essais', 'essais_restants', 0,
                                'verrou_jusqua', now() + make_interval(mins => v_minutes));
    end if;
    update lots_de_secours set essais_rates = essais_rates + 1 where utilisateur_id = p_utilisateur;
    perform _journal_securite(p_utilisateur, 'code_de_secours_refuse', null, jsonb_build_object('essais_restants', v_essais - v_lot.essais_rates - 1));
    return jsonb_build_object('ok', false, 'erreur', 'code de secours incorrect', 'essais_restants', v_essais - v_lot.essais_rates - 1);
  end if;
  update codes_de_secours set utilise_le = now() where id = v_ligne.id;
  update lots_de_secours set essais_rates = 0 where utilisateur_id = p_utilisateur;
  select count(*) into v_restants from codes_de_secours where utilisateur_id = p_utilisateur and utilise_le is null;
  perform _journal_securite(p_utilisateur, 'code_de_secours_utilise', null, jsonb_build_object('restants', v_restants));
  return jsonb_build_object('ok', true, 'code_id', v_ligne.id, 'restants', v_restants);
end $$;

-- Le retrait du facteur a échoué chez GoTrue : le code brûlé est rendu, sinon
-- la personne resterait sans facteur ET sans ce code.
create or replace function _code_de_secours_rendu(p_code_id bigint) returns void
language sql set search_path = public as $$
  update codes_de_secours set utilise_le = null where id = p_code_id
$$;

-- ───────────────── 7 · la double authentification retirée ──────────────────
-- Par un code de secours (la personne), ou par l'administration (un super
-- admin, un motif, trois fois au plus par jour et par personne). Le facteur
-- se retire chez GoTrue (la fonction deux-facteurs) ; ici, la décision et la
-- trace.
create or replace function admin_autoriser_reinitialisation_2fa(p_utilisateur uuid, p_motif text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_motif text := trim(coalesce(p_motif, '')); v_email text; v_id uuid;
begin
  perform _exiger_droit('administrateurs');
  if p_utilisateur = auth.uid() then
    raise exception 'vous ne réinitialisez pas votre propre double authentification' using detail = 'servez-vous d''un de vos codes de secours';
  end if;
  select email into v_email from auth.users where id = p_utilisateur;
  if not found then raise exception 'utilisateur inconnu'; end if;
  if length(v_motif) < 10 then raise exception 'motif trop court' using detail = 'dites comment vous avez vérifié l''identité'; end if;
  -- deux super admins en même temps ne passent pas tous deux la limite
  perform pg_advisory_xact_lock(hashtextextended('reinitialisation_2fa:' || p_utilisateur::text, 0));
  if (select count(*) from reinitialisations_2fa where utilisateur_id = p_utilisateur and demandee_le > now() - interval '24 hours') >= 3 then
    raise exception 'trop de réinitialisations' using detail = 'trois par personne et par jour au plus';
  end if;
  insert into reinitialisations_2fa (utilisateur_id, admin_id, motif) values (p_utilisateur, auth.uid(), v_motif) returning id into v_id;
  perform _journal_securite(p_utilisateur, 'reinitialisation_demandee', auth.uid(), jsonb_build_object('reinitialisation', v_id));
  perform _journaliser('deux_facteurs_reinitialisation', p_utilisateur::text, jsonb_build_object('motif', v_motif, 'reinitialisation', v_id));
  return jsonb_build_object('id', v_id, 'utilisateur_id', p_utilisateur, 'email', v_email);
end $$;

-- Après le retrait chez GoTrue (clé de service) : les codes de secours partent
-- avec le facteur — la prochaine connexion repasse par l'enrôlement puis par
-- des codes neufs. La personne est prévenue dans l'application et par e-mail.
create or replace function _deux_facteurs_retires(p_utilisateur uuid, p_cause text, p_reinitialisation uuid, p_facteurs int) returns jsonb
language plpgsql set search_path = public as $$
declare v_compte uuid; v_email text; v_courriel bigint;
begin
  if p_cause is null or p_cause not in ('code_de_secours', 'administration') then raise exception 'cause inconnue'; end if;
  delete from codes_de_secours where utilisateur_id = p_utilisateur;
  delete from lots_de_secours where utilisateur_id = p_utilisateur;
  if p_reinitialisation is not null then
    update reinitialisations_2fa set faite_le = now(), facteurs = p_facteurs
     where id = p_reinitialisation and utilisateur_id = p_utilisateur;
  end if;
  perform _journal_securite(p_utilisateur, 'deux_facteurs_retires',
                            (select admin_id from reinitialisations_2fa where id = p_reinitialisation),
                            jsonb_build_object('cause', p_cause, 'facteurs', p_facteurs));
  select id into v_compte from comptes where id = p_utilisateur;
  if v_compte is not null then
    perform _notifier(v_compte, 'Double authentification retirée',
                      'Votre application d''authentification a été retirée de votre compte. Si ce n''est pas vous, contactez l''équipe tout de suite.',
                      '/compte/securite');
  end if;
  -- l'e-mail passe par la boîte d'envoi de 0036 ; un administrateur n'a pas de ligne « comptes » : son adresse va en destinataire
  if to_regprocedure('public._envoyer_courriel(uuid,text,jsonb,text,timestamptz,text)') is not null then
    if v_compte is null then select email into v_email from auth.users where id = p_utilisateur; end if;
    if v_compte is not null or v_email is not null then
      execute 'select public._envoyer_courriel($1, $2, $3, $4, null, $5)' into v_courriel
        using v_compte, 'deux_facteurs_retires', jsonb_build_object('cause', p_cause, 'quand', now()),
              'deux_facteurs_retires:' || p_utilisateur::text || ':' || (now() at time zone 'Africa/Douala')::date::text, v_email;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'courriel', v_courriel);
end $$;

create or replace function _reinitialisation_2fa_echouee(p_id uuid, p_erreur text) returns void
language plpgsql set search_path = public as $$
declare v_u uuid;
begin
  update reinitialisations_2fa set echec = left(coalesce(p_erreur, 'échec'), 300) where id = p_id returning utilisateur_id into v_u;
  if v_u is not null then
    perform _journal_securite(v_u, 'reinitialisation_echouee', null, jsonb_build_object('reinitialisation', p_id));
  end if;
end $$;

-- La fiche « Sécurité » d'une personne, pour l'équipe. Jamais une empreinte ;
-- le motif d'une réinitialisation, pour le super admin seulement.
create or replace function admin_securite_utilisateur(p_utilisateur uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_super boolean;
begin
  perform _exiger_droit('clients');
  v_super := admin_a_droit('administrateurs');
  return jsonb_build_object(
    'deux_facteurs', exists (select 1 from auth.mfa_factors where user_id = p_utilisateur and factor_type = 'totp' and status = 'verified'),
    'codes_restants', (select count(*) from codes_de_secours where utilisateur_id = p_utilisateur and utilise_le is null),
    'codes_confirmes_le', (select confirme_le from lots_de_secours where utilisateur_id = p_utilisateur),
    'evenements', (select coalesce(jsonb_agg(jsonb_build_object('evenement', evenement, 'par_admin', par_admin, 'detail', detail, 'cree_le', cree_le)
                                             order by cree_le desc, id desc), '[]'::jsonb)
                     from (select * from journal_securite where utilisateur_id = p_utilisateur order by cree_le desc, id desc limit 20) j),
    'reinitialisations', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'admin_id', admin_id, 'demandee_le', demandee_le, 'faite_le', faite_le,
                                                                       'facteurs', facteurs, 'echec', echec)
                                                    || case when v_super then jsonb_build_object('motif', motif) else '{}'::jsonb end
                                                    order by demandee_le desc), '[]'::jsonb)
                            from reinitialisations_2fa where utilisateur_id = p_utilisateur));
end $$;

-- ───────────────────────── 8 · ouvrir son compte ───────────────────────────
-- Le téléphone : obligatoire, non vérifié, unique parmi les comptes OUVERTS —
-- le numéro d'un compte fermé se réutilise (décision du propriétaire).
alter table comptes drop constraint if exists comptes_telephone_key;
create unique index if not exists comptes_telephone_ouvert on comptes (telephone) where ferme_le is null;

create or replace function ouvrir_mon_compte(p_prenom text, p_nom text, p_naissance date, p_telephone text, p_ville text, p_pays text, p_conditions text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email  text := _email_prouve();
  v_prenom text := _nom_propre(p_prenom);
  v_nom    text := _nom_propre(p_nom);
  v_ville  text := _nom_propre(p_ville);
  v_pays   text := upper(trim(coalesce(p_pays, '')));
  v_tel    text := regexp_replace(coalesce(p_telephone, ''), '[^0-9+]', '', 'g');
  v_age    int;
  v_c      comptes;
  v_contrainte text;
begin
  perform _exiger_aal2();
  if auth.uid() is null then raise exception 'non connecté'; end if;
  if v_email is null then raise exception 'adresse e-mail non vérifiée' using detail = 'entrez le code reçu par e-mail'; end if;
  if not _mot_de_passe_pose(auth.uid()) then raise exception 'mot de passe à choisir' using detail = 'il protège chaque sortie d''argent'; end if;
  if not exists (select 1 from lots_de_secours where utilisateur_id = auth.uid() and confirme_le is not null) then
    raise exception 'codes de secours à noter' using detail = 'ils vous rendent l''accès si vous perdez votre téléphone';
  end if;
  if exists (select 1 from comptes where id = auth.uid()) then raise exception 'compte déjà ouvert'; end if;

  if v_prenom is null then raise exception 'prénom invalide' using detail = 'des lettres, de 2 à 60'; end if;
  if v_nom is null then raise exception 'nom invalide' using detail = 'des lettres, de 2 à 60'; end if;

  if p_naissance is null then raise exception 'date de naissance manquante'; end if;
  v_age := extract(year from age((now() at time zone 'Africa/Douala')::date, p_naissance))::int;
  if p_naissance > (now() at time zone 'Africa/Douala')::date or v_age > 120 then raise exception 'date de naissance invalide'; end if;
  if v_age < 18 then raise exception 'il faut avoir 18 ans' using detail = 'Glisil est un service financier'; end if;

  if v_tel !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'numéro de téléphone invalide' using detail = 'au format international, avec l''indicatif'; end if;
  if v_tel like '+237%' and v_tel !~ '^\+237[62][0-9]{8}$' then
    raise exception 'numéro de téléphone invalide' using detail = 'au Cameroun : neuf chiffres, commençant par 6 ou 2';
  end if;
  if exists (select 1 from comptes where telephone = v_tel and ferme_le is null) then
    raise exception 'ce numéro est déjà utilisé' using detail = 'il appartient à un autre compte';
  end if;

  if v_ville is null then raise exception 'ville invalide' using detail = 'des lettres, de 2 à 60'; end if;
  if v_pays !~ '^[A-Z]{2}$' then raise exception 'pays invalide'; end if;

  if p_conditions is distinct from (parametre('conditions') ->> 'version') then
    raise exception 'conditions non acceptées' using detail = 'lisez et acceptez les conditions en vigueur';
  end if;

  insert into comptes (id, telephone, email, prenom, nom_de_famille, nom, date_naissance, ville, pays, conditions_version, conditions_acceptees_le)
  values (auth.uid(), v_tel, v_email, v_prenom, v_nom, v_prenom || ' ' || v_nom, p_naissance, v_ville, v_pays, p_conditions, now())
  returning * into v_c;
  return _compte_json(v_c);
exception when unique_violation then
  -- deux inscriptions au même instant : la vérification plus haut ne voit pas l'autre, l'index, si
  get stacked diagnostics v_contrainte = constraint_name;
  if v_contrainte = 'comptes_telephone_ouvert' then raise exception 'ce numéro est déjà utilisé' using detail = 'il appartient à un autre compte';
  elsif v_contrainte = 'comptes_email_unique' then raise exception 'cette adresse est déjà utilisée';
  elsif v_contrainte = 'comptes_pkey' then raise exception 'compte déjà ouvert';
  else raise; end if;
end $function$;

-- L'administration : la session forte, un mot de passe posé, des codes notés.
create or replace function entrer_administration()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_email text := _email_prouve(); v_inv administrateurs_invites;
begin
  perform _exiger_aal2();
  if auth.uid() is null or v_email is null then return null; end if;
  if not _mot_de_passe_pose(auth.uid()) then raise exception 'mot de passe à choisir' using detail = 'il protège l''administration'; end if;
  if not exists (select 1 from lots_de_secours where utilisateur_id = auth.uid() and confirme_le is not null) then
    raise exception 'codes de secours à noter' using detail = 'ils vous rendent l''accès si vous perdez votre téléphone';
  end if;
  if not exists (select 1 from administrateurs where id = auth.uid()) then
    delete from administrateurs_invites where email = v_email returning * into v_inv;
    if found then
      insert into administrateurs (id, email, nom, role) values (auth.uid(), v_email, v_inv.nom, v_inv.role)
      on conflict do nothing;
      insert into journal_admin (admin_id, action, cible, detail)
      values (auth.uid(), 'invitation_acceptee', v_email, jsonb_build_object('role', v_inv.role, 'invite_par', v_inv.invite_par));
    end if;
  end if;
  return mon_profil_admin();
end $function$;

-- ─────────────── 9 · la seule lecture permise en session faible ────────────
-- L'écran d'entrée en a besoin AVANT le TOTP : où en est la personne. Elle
-- lit auth.uid() et rien d'autre de ce qui est à elle ; à dessein, pas de garde.
create or replace function mon_etat_d_entree() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_conf timestamptz;
begin
  if v_uid is null then raise exception 'non connecté'; end if;
  select email_confirmed_at into v_conf from auth.users where id = v_uid;
  return jsonb_build_object('email_confirme', v_conf is not null, 'mot_de_passe', _mot_de_passe_pose(v_uid),
    'session_forte', session_forte(),
    'codes_de_secours', exists (select 1 from lots_de_secours where utilisateur_id = v_uid and confirme_le is not null),
    'compte', exists (select 1 from comptes where id = v_uid));
end $$;

-- ───────────── 10 · un compte ne naît plus d'un téléphone prouvé ───────────
-- Plus de connexion par SMS : un compte naît dans ouvrir_mon_compte, et nulle part ailleurs.
do $$
begin
  if to_regclass('auth.users') is not null then
    execute 'drop trigger if exists comptes_naissance on auth.users';
  end if;
end $$;
drop function if exists handle_nouvel_utilisateur();

-- ─────────────── 11 · la troisième couche : le crochet de PostgREST ────────
-- Avant CHAQUE requête d'un client connecté, la session forte est
-- redemandée : une fonction qu'une migration future oublierait de garder est
-- refusée quand même. Deux chemins seulement passent en session faible.
create or replace function avant_chaque_requete() returns void
language plpgsql stable security definer set search_path = public as $$
declare v jsonb := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
begin
  if coalesce(v ->> 'role', 'anon') <> 'authenticated' then return; end if;   -- anon : les droits suffisent ; service_role : confiance
  if current_setting('request.path', true) in ('/rpc/mon_etat_d_entree', '/rpc/preuve_de_reserve') then return; end if;
  perform _exiger_aal2();
end $$;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticator') then
    execute 'alter role authenticator set pgrst.db_pre_request = ''public.avant_chaque_requete''';
    perform pg_notify('pgrst', 'reload config');
  end if;
end $$;

-- ──────────────────────────── 12 · les conditions ──────────────────────────
-- Les textes parlent maintenant du mot de passe et de la double
-- authentification, plus du code secret : chaque compte les réaccepte.
update parametres set valeur = jsonb_build_object('version', '2026-10-29') where cle = 'conditions';

-- ──────────────────────────────── 13 · les droits ──────────────────────────
revoke all on function session_forte(), _exiger_aal2(), _moment_du_facteur(text), _mot_de_passe_pose(uuid),
  _journal_securite(uuid, text, uuid, jsonb), _code_de_secours_neuf(), _code_de_secours_normalise(text), _empreinte_de_secours(uuid, text),
  generer_codes_de_secours(), confirmer_codes_de_secours(), mes_codes_de_secours(), _consommer_code_de_secours(uuid, text),
  _code_de_secours_rendu(bigint), admin_autoriser_reinitialisation_2fa(uuid, text), _deux_facteurs_retires(uuid, text, uuid, int),
  _reinitialisation_2fa_echouee(uuid, text), admin_securite_utilisateur(uuid), mon_etat_d_entree(), avant_chaque_requete()
  from public, anon, authenticated;
grant execute on function session_forte(), _exiger_aal2(), _moment_du_facteur(text), _mot_de_passe_pose(uuid),
  _journal_securite(uuid, text, uuid, jsonb), _code_de_secours_neuf(), _code_de_secours_normalise(text), _empreinte_de_secours(uuid, text),
  generer_codes_de_secours(), confirmer_codes_de_secours(), mes_codes_de_secours(), _consommer_code_de_secours(uuid, text),
  _code_de_secours_rendu(bigint), admin_autoriser_reinitialisation_2fa(uuid, text), _deux_facteurs_retires(uuid, text, uuid, int),
  _reinitialisation_2fa_echouee(uuid, text), admin_securite_utilisateur(uuid), mon_etat_d_entree(), avant_chaque_requete()
  to service_role;
-- les politiques (tables, stockage) s'évaluent avec les droits de l'appelant : il lui faut la garde
grant execute on function session_forte() to authenticated;
grant execute on function mon_etat_d_entree(), generer_codes_de_secours(), confirmer_codes_de_secours(), mes_codes_de_secours(),
  admin_autoriser_reinitialisation_2fa(uuid, text), admin_securite_utilisateur(uuid) to authenticated;
grant execute on function avant_chaque_requete() to anon, authenticated;
$sql$;
    raise notice '0035_connexion_mot_de_passe_2fa.sql : appliquée';
  end if;
end $consolide$;

-- ─── 0036_verification_avant_sortie.sql (md5 e31a10e6f8fd7970d3ae23666a9db7f1) ───
-- déjà en place si : rejouable telle quelle
do $consolide$
begin
  if false then
    raise notice '0036_verification_avant_sortie.sql : déjà en place, rien à faire';
  else
    execute $sql$
-- ╔════════════════════════════════════════════════════════════════════════╗
-- ║  Glisil · 0036 · la vérification avant chaque sortie d'argent          ║
-- ║                                                                        ║
-- ║  Le code secret à 4 chiffres s'en va. Chaque sortie (retrait MoMo,     ║
-- ║  retrait crypto, fermeture du compte, retrait d'un numéro) demande     ║
-- ║  une « vérification » : un défi à usage unique, lié À CETTE opération  ║
-- ║  (l'empreinte de son montant et de sa destination) et à CETTE session, ║
-- ║  valable dix minutes, cinq essais. Elle se règle par trois facteurs,   ║
-- ║  dans cet ordre :                                                      ║
-- ║   1. un code TOTP FRAIS (moins de cinq minutes, prouvé après la        ║
-- ║      demande) — d'abord, pour qu'une session volée sans téléphone ne   ║
-- ║      serve ni à deviner le mot de passe ni à bloquer le compte ;       ║
-- ║   2. le MOT DE PASSE, contrôlé ici contre l'empreinte de GoTrue ;      ║
-- ║   3. le CODE reçu par e-mail, qui dit en clair le montant et la        ║
-- ║      destination : un autre montant demande un autre code.             ║
-- ║  Un échec ne lève jamais : il est compté, et le compte reste écrit.    ║
-- ║  Dix échecs dans l'heure bloquent les sorties une heure.               ║
-- ║                                                                        ║
-- ║  L'e-mail est décidé ici et part par une boîte d'envoi (pg_net réveille║
-- ║  la fonction « courriel », pg_cron rattrape chaque minute) ; la même   ║
-- ║  boîte sert aux autres chantiers (sortie payée, 2FA retirée…).         ║
-- ╚════════════════════════════════════════════════════════════════════════╝

-- ───────────────────── 0 · ce qui doit exister chez Supabase ───────────────
-- Le mot de passe se contrôle contre auth.users.encrypted_password : si la
-- base ne peut pas le lire, on refuse de s'installer plutôt que d'ouvrir des
-- sorties qu'on ne saurait pas vérifier.
do $$ begin
  perform encrypted_password from auth.users limit 0;
exception when insufficient_privilege or undefined_column then
  raise exception 'vérification avant sortie : auth.users.encrypted_password illisible' using detail = 'le mot de passe ne peut pas être contrôlé côté serveur';
end $$;

-- ─────────────────────────────── 1 · le réglage ────────────────────────────
-- Il ne se change que par migration (pas d'entrée dans _verifier_parametre).
-- Le verrou du compte dure « fenetre_minutes » : la fenêtre est glissante.
insert into parametres (cle, valeur) values ('verification',
  '{"validite_minutes": 10, "essais_par_verification": 5, "echecs_max": 10, "fenetre_minutes": 60, "totp_fraicheur_secondes": 300, "renvoi_secondes": 60, "par_quart_heure": 5, "par_jour": 30}')
on conflict (cle) do nothing;

-- ─────────────────────────────── 2 · les tables ────────────────────────────
-- Aucune politique, aucun droit pour anon ni authenticated : seul le moteur les lit.
create table if not exists verifications (
  id                   uuid primary key default gen_random_uuid(),
  compte_id            uuid not null references comptes(id),
  operation            text not null check (operation in ('sortie_momo', 'retrait_crypto', 'fermer_compte', 'retirer_numero')),
  parametres           jsonb not null,            -- ce qui est LIÉ (canonique, fait par _parametres_de)
  parametres_empreinte text not null,             -- sha256(operation | parametres)
  affichage            jsonb not null,            -- ce que l'e-mail montre (frais, montant reçu, noms) — pas lié
  code_empreinte       text not null,             -- bcrypt du code e-mail, jamais le code
  session_id           uuid,                      -- la session qui l'a demandée
  cree_le              timestamptz not null default now(),
  expire_le            timestamptz not null,
  essais               int not null default 0,
  consommee_le         timestamptz,
  remplacee_le         timestamptz,               -- un code plus récent a été demandé pour le même genre d'opération
  operation_ref        text,                      -- XAFe-WD-…, XAFe-CR-…, l'id du numéro, « fermeture »
  courriel_id          bigint
);
create index if not exists verifications_du_compte on verifications (compte_id, cree_le desc);
create table if not exists verification_echecs (
  id              bigint generated always as identity primary key,
  compte_id       uuid not null references comptes(id),
  verification_id uuid references verifications(id),
  facteur         text not null check (facteur in ('mot_de_passe', 'code_email')),
  cree_le         timestamptz not null default now()
);
create index if not exists verification_echecs_du_compte on verification_echecs (compte_id, cree_le desc);

-- LA BOÎTE D'ENVOI, commune à tous les e-mails de Glisil. Pas de contrainte
-- sur le gabarit : un autre chantier en ajoute sans retoucher la table.
create table if not exists courriels_a_envoyer (
  id             bigint generated always as identity primary key,
  compte_id      uuid references comptes(id),    -- le destinataire est l'adresse d'Auth de ce compte, lue AU MOMENT d'envoyer
  destinataire   text,                           -- seulement hors des clients (un administrateur, le propriétaire)
  gabarit        text not null,
  donnees        jsonb not null,                 -- pour « verification » : l'affichage + {code, expire_le, cree_le, operation}
  cle            text unique,                    -- l'idempotence métier (« sortie_payee:XAFe-WD-000123 »)
  etat           text not null default 'en_attente' check (etat in ('en_attente', 'en_cours', 'envoye', 'echoue', 'abandonne')),
  essais         int not null default 0,
  pris_le        timestamptz,
  envoye_le      timestamptz,
  fournisseur_id text,
  erreur         text,
  expire_le      timestamptz,                    -- passé ce moment, ne jamais envoyer (les codes)
  cree_le        timestamptz not null default now(),
  check (compte_id is not null or destinataire is not null)
);
create index if not exists courriels_a_faire on courriels_a_envoyer (cree_le) where etat in ('en_attente', 'en_cours');
alter table sorties add column if not exists verification_id uuid unique references verifications(id);
alter table retraits_crypto add column if not exists verification_id uuid unique references verifications(id);
alter table verifications enable row level security;
alter table verification_echecs enable row level security;
alter table courriels_a_envoyer enable row level security;
revoke all on verifications, verification_echecs, courriels_a_envoyer from public, anon, authenticated;
grant all on verifications, verification_echecs, courriels_a_envoyer to service_role;

-- le journal de sécurité (0035) apprend un événement : une empreinte que la base ne sait pas lire
alter table journal_securite drop constraint if exists journal_securite_evenement_check;
alter table journal_securite add constraint journal_securite_evenement_check check (evenement in (
  'codes_generes', 'codes_confirmes', 'code_de_secours_utilise', 'code_de_secours_refuse', 'deux_facteurs_retires',
  'reinitialisation_demandee', 'reinitialisation_echouee', 'verification_mdp_indisponible'));

-- ─────────────────────────────── 3 · les outils ────────────────────────────
create or replace function _aal() returns text language sql stable set search_path = public as $$
  select coalesce(auth.jwt() ->> 'aal', '')
$$;

-- Un TOTP prouvé APRÈS la demande (5 s de jeu d'horloge) et il y a moins de
-- « totp_fraicheur_secondes ». Seul le TOTP compte : une session portée en
-- aal2 par un code de secours de GoTrue (« mfa/recovery_code ») ne sort pas
-- d'argent tant que l'application n'est pas réenrôlée.
create or replace function _totp_frais(p_depuis timestamptz) returns boolean language sql stable set search_path = public as $$
  select _aal() = 'aal2' and exists (
    select 1 from jsonb_array_elements(case when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then auth.jwt() -> 'amr' else '[]'::jsonb end) e
     where jsonb_typeof(e) = 'object' and e ->> 'method' in ('totp', 'mfa/totp')
       and (e ->> 'timestamp') ~ '^[0-9]+(\.[0-9]+)?$'
       and (e ->> 'timestamp')::numeric >= extract(epoch from greatest(p_depuis - interval '5 seconds',
                                                  now() - make_interval(secs => (parametre('verification') ->> 'totp_fraicheur_secondes')::int)))
       and (e ->> 'timestamp')::numeric <= extract(epoch from now()) + 5)
$$;

-- Le mot de passe contre l'empreinte de GoTrue (bcrypt « $2a$ », coût 10).
-- « a_choisir » : un compte Google sans mot de passe ; « indisponible » : une
-- empreinte d'un autre format (import argon2…), jamais comptée.
create or replace function _mot_de_passe_juste(p_compte uuid, p_mdp text) returns text
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_hash text;
begin
  select encrypted_password into v_hash from auth.users where id = p_compte;
  if coalesce(v_hash, '') = '' then return 'a_choisir'; end if;
  if left(v_hash, 4) <> '$2a$' then
    perform _journal_securite(p_compte, 'verification_mdp_indisponible', null, jsonb_build_object('format', left(v_hash, 3)));
    return 'indisponible';
  end if;
  if coalesce(p_mdp, '') = '' or octet_length(p_mdp) > 72 or extensions.crypt(p_mdp, v_hash) <> v_hash then return 'faux'; end if;
  return 'juste';
end $$;

-- Verrouillé jusqu'à… (null : libre). La fenêtre glisse : le verrou tombe de
-- lui-même, et rien ne se compte pendant qu'il tient (rien n'est évalué).
create or replace function _verrou_verification(p_compte uuid) returns timestamptz language sql stable set search_path = public as $$
  select cree_le + make_interval(mins => (parametre('verification') ->> 'fenetre_minutes')::int)
    from verification_echecs
   where compte_id = p_compte and cree_le > now() - make_interval(mins => (parametre('verification') ->> 'fenetre_minutes')::int)
   order by cree_le desc
  offset ((parametre('verification') ->> 'echecs_max')::int - 1) limit 1
$$;

create or replace function _email_masque(p text) returns text language sql immutable set search_path = public as $$
  select case when position('@' in coalesce(p, '')) > 1 then left(p, 1) || '•••@' || split_part(p, '@', 2) end
$$;

create or replace function _code_a_six_chiffres() returns text language sql volatile set search_path = public, extensions, pg_temp as $$
  select lpad(((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000)::text, 6, '0')
$$;

-- LA seule entrée dans la boîte d'envoi (les autres chantiers aussi). Une clé
-- déjà connue rend la ligne existante : rejouer un geste n'envoie pas deux fois.
create or replace function _envoyer_courriel(p_compte uuid, p_gabarit text, p_donnees jsonb, p_cle text default null,
                                             p_expire_le timestamptz default null, p_destinataire text default null) returns bigint
language plpgsql set search_path = public as $$
declare v_id bigint;
begin
  insert into courriels_a_envoyer (compte_id, destinataire, gabarit, donnees, cle, expire_le)
  values (p_compte, p_destinataire, p_gabarit, coalesce(p_donnees, '{}'::jsonb), p_cle, p_expire_le)
  on conflict (cle) do nothing
  returning id into v_id;
  if v_id is null then select id into v_id from courriels_a_envoyer where cle = p_cle; end if;
  return v_id;
end $$;

-- ───────────── 4 · ce qui est lié, et les mêmes refus que l'opération ──────
-- UN constructeur par opération, appelé par la demande ET par la
-- consommation : ils ne peuvent pas diverger. Il lève les refus de
-- l'opération elle-même — aucun code n'est envoyé pour une sortie qui serait
-- refusée.
create or replace function _exiger_fermeture_possible(p_compte uuid) returns void
language plpgsql set search_path = public as $$
declare v_reste text;
begin
  select string_agg(format('%s %s', to_char(disponible + bloque, 'FM999G999G999G990D00'), actif), ', ')
    into v_reste from soldes where compte_id = p_compte and disponible + bloque > 0;
  if v_reste is not null then
    raise exception 'il reste de l''argent sur le compte' using detail = format('sortez d''abord : %s', v_reste);
  end if;
  if exists (select 1 from ordres where compte_id = p_compte and etat in ('ouvert', 'partiel'))
     or exists (select 1 from depots where compte_id = p_compte and etat = 'en_attente')
     or exists (select 1 from depot_declarations where compte_id = p_compte and etat = 'attendu')
     or exists (select 1 from sorties where compte_id = p_compte and etat in ('en_attente', 'en_cours'))
     or exists (select 1 from retraits_crypto where compte_id = p_compte and etat in ('en_attente', 'en_cours')) then
    raise exception 'une opération est en cours' using detail = 'attendez qu''elle se termine, ou annulez-la';
  end if;
  -- un paiement reçu sur un de ses dossiers, retenu (palier, ID partagé) : il est à lui
  if exists (select 1 from entrees_retenues r join depots d on d.id = r.depot_id
              where d.compte_id = p_compte and r.etat = 'retenue') then
    raise exception 'un remboursement vous est dû' using detail = 'l''équipe doit d''abord vous rembourser';
  end if;
end $$;

create or replace function _parametres_de(p_compte uuid, p_operation text, p_p jsonb) returns jsonb
language plpgsql set search_path = public as $$
declare
  v_n       numeros;
  v_op      operateurs;
  v_demo    boolean;
  v_montant numeric;
  v_nom     text;
  v_taux    numeric;
  v_frais   numeric := 0;
  v_n_tr    int; v_part numeric; v_reste numeric; v_chunk numeric; v_f numeric; i int;
  v_palier  jsonb;
  v_res     reseaux;
  v_actif   text;
  v_adresse text;
  v_dispo   numeric;
begin
  if p_operation = 'sortie_momo' then
    v_montant := (p_p ->> 'montant')::numeric;
    select * into v_n from numeros where id = (p_p ->> 'numero_id')::uuid and compte_id = p_compte and retire_le is null;
    -- les gardes de la sortie (0030, 0034), dans le même ordre
    v_demo := numero_de_demo(v_n.numero);
    if coalesce(v_demo, false) and _depots_reels_ouverts(p_compte) then
      raise exception 'un numéro de démo ne reçoit que l''argent de test'
        using detail = 'vos XAFe sont de l''argent réel : retirez-les vers un vrai numéro';
    end if;
    if not coalesce(v_demo, false) and not _depots_reels_ouverts(p_compte) then
      raise exception 'l''argent de test ne sort pas en vrai'
        using detail = 'vos XAFe de la bêta se retirent vers un numéro de démo (600…)';
    end if;
    if not coalesce((parametre('sortie') ->> 'ouvertes')::boolean, true) and not coalesce(v_demo, false) then
      raise exception 'sorties pas encore ouvertes' using detail = 'vos XAFe restent sur votre compte';
    end if;
    if v_montant is null or v_montant <= 0 or v_montant <> trunc(v_montant) then raise exception 'montant invalide'; end if;
    if _sortie_manuelle() then
      v_nom := nullif(regexp_replace(trim(coalesce(p_p ->> 'nom', '')), '\s+', ' ', 'g'), '');
      if v_nom is null or length(v_nom) < 2 or length(v_nom) > 80 then
        raise exception 'nom du bénéficiaire invalide' using detail = 'le nom exact du compte Mobile Money qui reçoit';
      end if;
    end if;
    if v_n.id is null then raise exception 'numéro inconnu sur ce compte'; end if;
    if v_n.verifie_le is null then raise exception 'numéro pas encore vérifié'; end if;
    if v_n.actif_des > now() then
      raise exception 'numéro pas encore actif' using detail = format('actif à partir du %s', v_n.actif_des);
    end if;
    select * into v_op from operateurs where id = v_n.operateur;
    v_palier := parametre('paliers') -> (select palier::text from comptes where id = p_compte);
    if v_palier is not null and v_palier <> 'null'::jsonb and _sorties_du_jour(p_compte) + v_montant > (v_palier ->> 'sortie_jour')::numeric then
      raise exception 'plafond du palier atteint' using detail = format('%s XAF par jour', v_palier ->> 'sortie_jour');
    end if;
    -- les frais, comptés comme l'opération les comptera (découpage par transfert compris, en mode TOTEM)
    v_taux := coalesce((parametre('frais') ->> 'sortie')::numeric, 0);
    v_n_tr := case when _sortie_manuelle() or v_op.plafond_par_transfert is null then 1
                   else greatest(1, ceil(v_montant / v_op.plafond_par_transfert))::int end;
    v_part := trunc(v_montant / v_n_tr); v_reste := v_montant - v_part * v_n_tr;
    for i in 1 .. v_n_tr loop
      v_chunk := v_part + (case when i = v_n_tr then v_reste else 0 end);
      v_f := ceil(v_chunk * v_taux);
      if v_chunk - v_f <= 0 then raise exception 'montant trop petit' using detail = 'après les frais, rien ne partirait'; end if;
      v_frais := v_frais + v_f;
    end loop;
    select disponible into v_dispo from soldes where compte_id = p_compte and actif = 'XAFe';
    if coalesce(v_dispo, 0) < v_montant then
      raise exception 'solde insuffisant' using detail = format('XAFe : %s disponible', coalesce(v_dispo, 0));
    end if;
    return jsonb_build_object(
      'parametres', jsonb_build_object('montant', trim_scale(v_montant), 'numero_id', v_n.id, 'operateur', v_n.operateur, 'numero', v_n.numero, 'nom', v_nom),
      'affichage', jsonb_build_object('montant', trim_scale(v_montant), 'frais', trim_scale(v_frais), 'recu', trim_scale(v_montant - v_frais),
                                      'operateur', v_n.operateur, 'operateur_nom', coalesce(v_op.nom, v_n.operateur), 'numero', v_n.numero, 'nom', v_nom));

  elsif p_operation = 'retrait_crypto' then
    v_actif := p_p ->> 'actif';
    v_adresse := trim(coalesce(p_p ->> 'adresse', ''));
    v_montant := (p_p ->> 'montant')::numeric;
    if not coalesce((parametre('crypto') ->> 'retraits_ouverts')::boolean, false) then
      raise exception 'retraits crypto pas encore ouverts' using detail = 'l''envoi sur la chaîne arrive bientôt ; vos fonds restent disponibles';
    end if;
    if v_actif is null or v_actif not in ('XAFe', 'USDT') then raise exception 'actif inconnu'; end if;
    v_res := _reseau_ouvert(p_p ->> 'reseau');
    if not _adresse_valide(v_res.famille, v_adresse) then
      raise exception 'adresse invalide' using detail = format('ce n''est pas une adresse %s (%s)', v_res.norme, v_res.nom);
    end if;
    if v_montant is null or v_montant <= 0 or v_montant <> round(v_montant, case v_actif when 'USDT' then 2 else 0 end) then
      raise exception 'montant invalide';
    end if;
    v_frais := coalesce((parametre('crypto') -> 'frais' ->> v_actif)::numeric, 0);
    select disponible into v_dispo from soldes where compte_id = p_compte and actif = v_actif;
    if coalesce(v_dispo, 0) < v_montant + v_frais then
      raise exception 'solde insuffisant' using detail = format('%s : %s disponible', v_actif, coalesce(v_dispo, 0));
    end if;
    return jsonb_build_object(
      'parametres', jsonb_build_object('actif', v_actif, 'reseau', v_res.id, 'adresse', v_adresse, 'montant', trim_scale(v_montant)),
      -- les frais ne sont PAS liés : l'opération prend ceux en vigueur quand elle s'exécute (comme avant)
      'affichage', jsonb_build_object('actif', v_actif, 'montant', trim_scale(v_montant), 'frais', trim_scale(v_frais), 'reseau', v_res.id,
                                      'reseau_nom', v_res.nom, 'norme', v_res.norme, 'adresse', v_adresse, 'explorateur', v_res.explorateur));

  elsif p_operation = 'fermer_compte' then
    perform _exiger_fermeture_possible(p_compte);
    return jsonb_build_object('parametres', '{}'::jsonb, 'affichage', '{}'::jsonb);

  elsif p_operation = 'retirer_numero' then
    select * into v_n from numeros where id = (p_p ->> 'numero_id')::uuid and compte_id = p_compte and retire_le is null;
    if v_n.id is null then raise exception 'numéro inconnu sur ce compte'; end if;
    if v_n.verifie_le is not null
       and (select count(*) from numeros where compte_id = p_compte and retire_le is null and verifie_le is not null) <= 1 then
      raise exception 'le dernier numéro ne se retire pas';
    end if;
    select * into v_op from operateurs where id = v_n.operateur;
    return jsonb_build_object(
      'parametres', jsonb_build_object('numero_id', v_n.id, 'operateur', v_n.operateur, 'numero', v_n.numero),
      'affichage', jsonb_build_object('operateur', v_n.operateur, 'operateur_nom', coalesce(v_op.nom, v_n.operateur), 'numero', v_n.numero));
  end if;
  raise exception 'opération inconnue';
end $$;

-- Le texte d'un jsonb est canonique (clés triées), et trim_scale fait 100 = 100.00.
create or replace function _empreinte(p_operation text, p_parametres jsonb) returns text
language sql immutable set search_path = public, extensions, pg_temp as $$
  select encode(extensions.digest(p_operation || '|' || p_parametres::text, 'sha256'), 'hex')
$$;

-- ───────────────────── 5 · demander une vérification ───────────────────────
-- Le code part par e-mail ; il n'est JAMAIS rendu ici.
create or replace function preparer_verification(p_operation text, p_parametres jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  v_compte  uuid := auth.uid();
  v_p       jsonb := parametre('verification');
  v_verrou  timestamptz;
  v         jsonb;
  v_code    text;
  v_v       verifications;
  v_courriel bigint;
begin
  perform _exiger_compte_actif(auth.uid());
  -- une demande à la fois par compte : les limites ci-dessous ne se courent pas
  perform 1 from comptes where id = v_compte for no key update;
  v_verrou := _verrou_verification(v_compte);
  if v_verrou is not null then
    raise exception 'vérifications verrouillées' using detail = v_verrou::text;
  end if;
  v := _parametres_de(v_compte, p_operation, coalesce(p_parametres, '{}'::jsonb));
  -- le même écran rouvert (retour arrière, rechargement) dans la minute : le code
  -- déjà parti vaut encore — on le rend, sans nouvel e-mail
  select * into v_v from verifications
   where compte_id = v_compte and operation = p_operation and parametres_empreinte = _empreinte(p_operation, v -> 'parametres')
     and session_id is not distinct from nullif(auth.jwt() ->> 'session_id', '')::uuid
     and consommee_le is null and remplacee_le is null and expire_le > now()
     and cree_le > now() - make_interval(secs => (v_p ->> 'renvoi_secondes')::int)
     and not exists (select 1 from courriels_a_envoyer c where c.id = verifications.courriel_id and c.etat in ('echoue', 'abandonne'))
   order by cree_le desc limit 1;
  if found then
    return jsonb_build_object('id', v_v.id, 'operation', p_operation, 'expire_le', v_v.expire_le,
                              'renvoi_des', v_v.cree_le + make_interval(secs => (v_p ->> 'renvoi_secondes')::int),
                              'email_masque', _email_masque((select email from auth.users where id = v_compte)),
                              'affichage', v_v.affichage, 'meme_code', true);
  end if;
  -- une minute entre deux envois ; ne retient pas un autre code : celui qui a
  -- servi (il a fallu les trois preuves), celui qui est clos, ni celui dont
  -- l'e-mail n'a pas pu partir. Le plafond du quart d'heure, lui, compte tout.
  if exists (select 1 from verifications where compte_id = v_compte and consommee_le is null and remplacee_le is null
              and cree_le > now() - make_interval(secs => (v_p ->> 'renvoi_secondes')::int)
              and not exists (select 1 from courriels_a_envoyer c where c.id = verifications.courriel_id and c.etat in ('echoue', 'abandonne'))) then
    raise exception 'trop de codes demandés : attendez une minute';
  end if;
  if (select count(*) from verifications where compte_id = v_compte and cree_le > now() - interval '15 minutes') >= (v_p ->> 'par_quart_heure')::int
     or (select count(*) from verifications where compte_id = v_compte and cree_le > now() - interval '24 hours') >= (v_p ->> 'par_jour')::int then
    raise exception 'trop de vérifications demandées' using detail = format('%s par quart d''heure, %s par jour', v_p ->> 'par_quart_heure', v_p ->> 'par_jour');
  end if;
  -- le code d'avant, pour le même genre d'opération, ne vaut plus rien
  update verifications set remplacee_le = now()
   where compte_id = v_compte and operation = p_operation and consommee_le is null and remplacee_le is null and expire_le > now();
  v_code := _code_a_six_chiffres();
  insert into verifications (compte_id, operation, parametres, parametres_empreinte, affichage, code_empreinte, session_id, expire_le)
  values (v_compte, p_operation, v -> 'parametres', _empreinte(p_operation, v -> 'parametres'), v -> 'affichage',
          extensions.crypt(v_code, extensions.gen_salt('bf', 8)), nullif(auth.jwt() ->> 'session_id', '')::uuid,
          now() + make_interval(mins => (v_p ->> 'validite_minutes')::int))
  returning * into v_v;
  v_courriel := _envoyer_courriel(v_compte, 'verification',
    v_v.affichage || jsonb_build_object('operation', p_operation, 'code', v_code, 'cree_le', v_v.cree_le, 'expire_le', v_v.expire_le,
                                        'verification_id', v_v.id),
    'verification:' || v_v.id, v_v.expire_le);
  update verifications set courriel_id = v_courriel where id = v_v.id;
  return jsonb_build_object('id', v_v.id, 'operation', p_operation, 'expire_le', v_v.expire_le,
                            'renvoi_des', now() + make_interval(secs => (v_p ->> 'renvoi_secondes')::int),
                            'email_masque', _email_masque((select email from auth.users where id = v_compte)),
                            'affichage', v_v.affichage);
end $$;

-- L'écran demande où en est sa vérification : « e-mail parti », « n'a pas pu partir ».
create or replace function ma_verification(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _exiger_aal2();
  return (select jsonb_build_object('expire_le', v.expire_le,
                                    'essais_restants', greatest(0, (parametre('verification') ->> 'essais_par_verification')::int - v.essais),
                                    'consommee', v.consommee_le is not null, 'remplacee', v.remplacee_le is not null,
                                    'courriel', (select etat from courriels_a_envoyer where id = v.courriel_id))
            from verifications v where v.id = p_id and v.compte_id = auth.uid());
end $$;

-- ─────────────────────── 6 · consommer la vérification ─────────────────────
-- Ne lève JAMAIS sur un facteur faux : l'appelant rend le jsonb tel quel, et
-- l'échec reste écrit. Une réussite est annulée avec l'opération si celle-ci
-- lève ensuite : la vérification reste alors utilisable.
create or replace function _echec_verification(p_v verifications, p_facteur text) returns int
language plpgsql set search_path = public as $$
declare v_avant timestamptz := _verrou_verification(p_v.compte_id); v_apres timestamptz;
begin
  update verifications set essais = essais + 1 where id = p_v.id;
  insert into verification_echecs (compte_id, verification_id, facteur) values (p_v.compte_id, p_v.id, p_facteur);
  v_apres := _verrou_verification(p_v.compte_id);
  if v_avant is null and v_apres is not null then
    perform _envoyer_courriel(p_v.compte_id, 'verification_verrouillee', jsonb_build_object('verrou_jusqua', v_apres),
                              'verrou:' || p_v.compte_id || ':' || date_trunc('hour', now()));
  end if;
  return greatest(0, (parametre('verification') ->> 'essais_par_verification')::int - p_v.essais - 1);
end $$;

create or replace function _consommer_verification(p_compte uuid, p_operation text, p_parametres jsonb, p_verification uuid,
                                                   p_mot_de_passe text, p_code_email text) returns jsonb
language plpgsql set search_path = public, extensions, pg_temp as $$
declare v verifications; v_verrou timestamptz; m text; n int;
begin
  select * into v from verifications where id = p_verification for update;
  if v.id is null or v.compte_id <> p_compte
     or (v.session_id is not null and v.session_id is distinct from nullif(auth.jwt() ->> 'session_id', '')::uuid) then
    return jsonb_build_object('ok', false, 'erreur', 'vérification inconnue');
  end if;
  v_verrou := _verrou_verification(p_compte);
  if v_verrou is not null then return jsonb_build_object('ok', false, 'erreur', 'vérifications verrouillées', 'verrou_jusqua', v_verrou); end if;
  if v.consommee_le is not null then return jsonb_build_object('ok', false, 'erreur', 'vérification déjà utilisée'); end if;
  if v.remplacee_le is not null then return jsonb_build_object('ok', false, 'erreur', 'vérification remplacée par un code plus récent'); end if;
  if v.expire_le <= now() then return jsonb_build_object('ok', false, 'erreur', 'vérification expirée'); end if;
  if v.essais >= (parametre('verification') ->> 'essais_par_verification')::int then
    return jsonb_build_object('ok', false, 'erreur', 'vérification épuisée');
  end if;
  -- un autre montant, une autre destination : jamais ce code (et ce n'est pas un essai)
  if v.operation <> p_operation or v.parametres_empreinte <> _empreinte(p_operation, p_parametres) then
    return jsonb_build_object('ok', false, 'erreur', 'la vérification ne correspond pas à cette opération');
  end if;
  -- le TOTP d'abord, non compté : sans le téléphone, ni oracle du mot de passe ni verrou à poser
  if not _totp_frais(v.cree_le) then
    return jsonb_build_object('ok', false, 'erreur', 'code de l''application d''authentification à saisir', 'facteur', 'totp');
  end if;
  m := _mot_de_passe_juste(p_compte, p_mot_de_passe);
  if m = 'a_choisir' then return jsonb_build_object('ok', false, 'erreur', 'mot de passe à choisir', 'facteur', 'mot_de_passe'); end if;
  if m = 'indisponible' then return jsonb_build_object('ok', false, 'erreur', 'vérification du mot de passe indisponible'); end if;
  if m = 'faux' then
    n := _echec_verification(v, 'mot_de_passe');
    return jsonb_build_object('ok', false, 'erreur', 'mot de passe incorrect', 'facteur', 'mot_de_passe', 'essais_restants', n);
  end if;
  if coalesce(p_code_email, '') !~ '^[0-9]{6}$' or extensions.crypt(p_code_email, v.code_empreinte) <> v.code_empreinte then
    n := _echec_verification(v, 'code_email');
    return jsonb_build_object('ok', false, 'erreur', 'code e-mail incorrect', 'facteur', 'code_email', 'essais_restants', n);
  end if;
  update verifications set consommee_le = now() where id = v.id;
  update courriels_a_envoyer set donnees = donnees - 'code' where id = v.courriel_id;
  return jsonb_build_object('ok', true, 'verification_id', v.id);
end $$;

-- ───────────────────────────── 7 · les quatre sorties ──────────────────────
-- Les anciennes signatures (au code secret) partent ; leurs corps, sans le
-- code, deviennent des fonctions internes (non ouvertes aux clients) que les
-- sorties vérifiées appellent — et que le harnais appelle directement.
drop function if exists demander_sortie(numeric, uuid, text, text, text);
drop function if exists demander_retrait_crypto(text, text, text, numeric, text, text);
drop function if exists fermer_mon_compte(text, text);
drop function if exists retirer_numero(uuid, text);

create or replace function _demander_sortie(p_montant numeric, p_numero_id uuid, p_cle text, p_nom text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_demo boolean;
begin
  perform _exiger_aal2();
  select numero_de_demo(n.numero) into v_demo
    from numeros n where n.id = p_numero_id and n.compte_id = auth.uid() and n.retire_le is null;
  if coalesce(v_demo, false) and _depots_reels_ouverts(auth.uid()) then
    raise exception 'un numéro de démo ne reçoit que l''argent de test'
      using detail = 'vos XAFe sont de l''argent réel : retirez-les vers un vrai numéro';
  end if;
  if not coalesce(v_demo, false) and not _depots_reels_ouverts(auth.uid()) then
    raise exception 'l''argent de test ne sort pas en vrai'
      using detail = 'vos XAFe de la bêta se retirent vers un numéro de démo (600…)';
  end if;
  if not coalesce((parametre('sortie') ->> 'ouvertes')::boolean, true) and not coalesce(v_demo, false) then
    raise exception 'sorties pas encore ouvertes' using detail = 'vos XAFe restent sur votre compte';
  end if;
  if _sortie_manuelle() then return _demander_sortie_manuelle(p_montant, p_numero_id, p_cle, p_nom); end if;
  return demander_sortie(p_montant, p_numero_id, p_cle);
end $$;

-- Une réponse perdue, puis la même demande refaite : la sortie déjà faite est
-- rendue (la clé, avant la vérification). Le code demandé pour ce second essai
-- n'a rien prouvé et ne servira plus : il se clôt, sinon il retiendrait la
-- prochaine demande une minute (« attendez une minute »).
create or replace function _clore_verification_rejouee(p_compte uuid, p_operation text, p_id uuid) returns void
language sql security definer set search_path = public as $$
  update verifications set remplacee_le = now()
   where id = p_id and compte_id = p_compte and operation = p_operation and consommee_le is null and remplacee_le is null;
$$;

create or replace function demander_sortie(p_montant numeric, p_numero_id uuid, p_cle text, p_verification uuid,
                                           p_mot_de_passe text, p_code_email text, p_nom text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_compte uuid := auth.uid(); v_s sorties; v jsonb; c jsonb; r jsonb;
begin
  perform _exiger_compte_actif(auth.uid());
  -- AVANT la vérification : une réponse perdue puis rejouée rend la sortie faite, pas « vérification déjà utilisée »
  if p_cle is not null then
    select * into v_s from sorties where compte_id = v_compte and cle = p_cle;
    if found then perform _clore_verification_rejouee(v_compte, 'sortie_momo', p_verification); return _sortie_json(v_s) || '{"deja": true}'; end if;
  end if;
  v := _parametres_de(v_compte, 'sortie_momo', jsonb_build_object('montant', p_montant, 'numero_id', p_numero_id, 'nom', p_nom));
  c := _consommer_verification(v_compte, 'sortie_momo', v -> 'parametres', p_verification, p_mot_de_passe, p_code_email);
  if not (c ->> 'ok')::boolean then return c; end if;
  r := _demander_sortie(p_montant, p_numero_id, p_cle, p_nom);
  update sorties set verification_id = p_verification where reference = r ->> 'reference' and compte_id = v_compte;
  update verifications set operation_ref = r ->> 'reference' where id = p_verification;
  return r;
end $$;

create or replace function _demander_retrait_crypto(p_actif text, p_reseau text, p_adresse text, p_montant numeric, p_cle text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_compte uuid := auth.uid();
  v_r      retraits_crypto;
  v_res    reseaux;
  v_frais  numeric;
  v_palier jsonb;
  v_cours  numeric;
  v_xaf    numeric;
begin
  perform _exiger_compte_actif(v_compte);
  if p_cle is not null then
    select * into v_r from retraits_crypto where compte_id = v_compte and cle = p_cle;
    if found then return _retrait_json(v_r) || '{"deja": true}'; end if;
  end if;
  if not coalesce((parametre('crypto') ->> 'retraits_ouverts')::boolean, false) then
    raise exception 'retraits crypto pas encore ouverts' using detail = 'l''envoi sur la chaîne arrive bientôt ; vos fonds restent disponibles';
  end if;
  if p_actif not in ('XAFe', 'USDT') then raise exception 'actif inconnu'; end if;
  v_res := _reseau_ouvert(p_reseau);
  if not _adresse_valide(v_res.famille, p_adresse) then
    raise exception 'adresse invalide' using detail = format('ce n''est pas une adresse %s (%s)', v_res.norme, v_res.nom);
  end if;
  if p_montant is null or p_montant <= 0 or p_montant <> round(p_montant, case p_actif when 'USDT' then 2 else 0 end) then
    raise exception 'montant invalide';
  end if;
  v_frais := (parametre('crypto') -> 'frais' ->> p_actif)::numeric;

  perform 1 from comptes where id = v_compte for no key update;
  v_palier := parametre('paliers') -> (select palier::text from comptes where id = v_compte);
  if v_palier is not null and v_palier <> 'null'::jsonb then
    if p_actif = 'USDT' then
      v_cours := (select prix from executions order by cree_le desc, id desc limit 1);
      if v_cours is null then raise exception 'pas de cours de référence' using detail = 'le plafond du palier se compte en XAF'; end if;
      v_xaf := (p_montant + v_frais) * v_cours;
    else
      v_xaf := p_montant + v_frais;
    end if;
    if _sorties_du_jour(v_compte) + v_xaf > (v_palier ->> 'sortie_jour')::numeric then
      raise exception 'plafond du palier atteint' using detail = format('%s XAF par jour, retraits crypto compris', v_palier ->> 'sortie_jour');
    end if;
  end if;
  insert into retraits_crypto (reference, compte_id, actif, reseau, adresse, montant, frais, cle)
  values ('XAFe-CR-' || lpad(nextval('retraits_crypto_numero')::text, 6, '0'), v_compte, p_actif, p_reseau, p_adresse, p_montant, v_frais, p_cle)
  returning * into v_r;
  perform _mouvement(v_compte, p_actif, -(p_montant + v_frais), p_montant + v_frais, 'retrait_crypto_bloque', 'retraits_crypto', v_r.reference);
  return _retrait_json(v_r);
end $$;

create or replace function demander_retrait_crypto(p_actif text, p_reseau text, p_adresse text, p_montant numeric, p_cle text,
                                                   p_verification uuid, p_mot_de_passe text, p_code_email text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_compte uuid := auth.uid(); v_r retraits_crypto; v jsonb; c jsonb; r jsonb;
begin
  perform _exiger_compte_actif(auth.uid());
  if p_cle is not null then
    select * into v_r from retraits_crypto where compte_id = v_compte and cle = p_cle;
    if found then perform _clore_verification_rejouee(v_compte, 'retrait_crypto', p_verification); return _retrait_json(v_r) || '{"deja": true}'; end if;
  end if;
  v := _parametres_de(v_compte, 'retrait_crypto', jsonb_build_object('actif', p_actif, 'reseau', p_reseau, 'adresse', p_adresse, 'montant', p_montant));
  c := _consommer_verification(v_compte, 'retrait_crypto', v -> 'parametres', p_verification, p_mot_de_passe, p_code_email);
  if not (c ->> 'ok')::boolean then return c; end if;
  -- l'adresse ENREGISTRÉE est celle qui a été liée (sans espaces autour)
  r := _demander_retrait_crypto(p_actif, p_reseau, v -> 'parametres' ->> 'adresse', p_montant, p_cle);
  update retraits_crypto set verification_id = p_verification where reference = r ->> 'reference' and compte_id = v_compte;
  update verifications set operation_ref = r ->> 'reference' where id = p_verification;
  return r;
end $$;

create or replace function _fermer_compte(p_compte uuid, p_motif text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_c comptes;
begin
  if p_compte is null then raise exception 'non connecté'; end if;
  select * into v_c from comptes where id = p_compte and not maison for no key update;
  if not found then raise exception 'compte inconnu'; end if;
  if v_c.ferme_le is not null then raise exception 'compte déjà fermé'; end if;
  perform _exiger_fermeture_possible(v_c.id);
  update comptes set ferme_le = now(), desactive_le = coalesce(desactive_le, now()),
                     fermeture_motif = nullif(left(trim(coalesce(p_motif, '')), 500), '')
   where id = v_c.id returning * into v_c;
  return jsonb_build_object('ok', true, 'compte', _compte_json(v_c));
end $$;

create or replace function fermer_mon_compte(p_verification uuid, p_mot_de_passe text, p_code_email text, p_motif text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_compte uuid := auth.uid(); v_c comptes; c jsonb; r jsonb;
begin
  perform _exiger_aal2();
  if v_compte is null then raise exception 'non connecté'; end if;
  select * into v_c from comptes where id = v_compte and not maison for no key update;
  if not found then raise exception 'compte inconnu'; end if;
  if v_c.ferme_le is not null then raise exception 'compte déjà fermé'; end if;
  perform _exiger_fermeture_possible(v_compte);
  c := _consommer_verification(v_compte, 'fermer_compte', (_parametres_de(v_compte, 'fermer_compte', '{}'::jsonb)) -> 'parametres',
                               p_verification, p_mot_de_passe, p_code_email);
  if not (c ->> 'ok')::boolean then return c; end if;
  r := _fermer_compte(v_compte, p_motif);
  update verifications set operation_ref = 'fermeture' where id = p_verification;
  return r;
end $$;

create or replace function _retirer_numero(p_compte uuid, p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_n numeros;
begin
  select * into v_n from numeros where id = p_id and compte_id = p_compte and retire_le is null for update;
  if not found then raise exception 'numéro inconnu sur ce compte'; end if;
  if v_n.verifie_le is not null
     and (select count(*) from numeros where compte_id = p_compte and retire_le is null and verifie_le is not null) <= 1 then
    raise exception 'le dernier numéro ne se retire pas';
  end if;
  update numeros set retire_le = now() where id = p_id;
  delete from numeros_codes where numero_id = p_id;
  return jsonb_build_object('ok', true);
end $$;

create or replace function retirer_numero(p_id uuid, p_verification uuid, p_mot_de_passe text, p_code_email text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_compte uuid := auth.uid(); v jsonb; c jsonb; r jsonb;
begin
  perform _exiger_aal2();
  if v_compte is null then raise exception 'non connecté'; end if;
  -- le numéro verrouillé AVANT de lier : deux retraits ensemble ne retirent pas le dernier numéro
  perform 1 from numeros where compte_id = v_compte and retire_le is null for update;
  v := _parametres_de(v_compte, 'retirer_numero', jsonb_build_object('numero_id', p_id));
  c := _consommer_verification(v_compte, 'retirer_numero', v -> 'parametres', p_verification, p_mot_de_passe, p_code_email);
  if not (c ->> 'ok')::boolean then return c; end if;
  r := _retirer_numero(v_compte, p_id);
  update verifications set operation_ref = p_id::text where id = p_verification;
  return r;
end $$;

-- ───────────────────── le code secret à 4 chiffres s'en va ─────────────────
drop function if exists verifier_code_secret(text);
drop function if exists changer_code_secret(text, text);
drop function if exists completer_profil(text, text);
drop function if exists _controler_code(uuid, text);

create or replace function _compte_json(c comptes) returns jsonb
language sql stable set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', c.id, 'telephone', c.telephone, 'nom', c.nom, 'entreprise', c.entreprise, 'palier', c.palier,
                            'email', c.email, 'prenom', c.prenom, 'nom_de_famille', c.nom_de_famille,
                            'date_naissance', c.date_naissance, 'ville', c.ville, 'pays', c.pays,
                            'verification_en_cours', c.verification_en_cours,
                            'conditions_version', c.conditions_version, 'conditions_acceptees_le', c.conditions_acceptees_le,
                            'conditions_a_jour', c.maison or c.conditions_version is not distinct from (parametre('conditions') ->> 'version'),
                            'ferme_le', c.ferme_le, 'desactive', c.desactive_le is not null,
                            -- ce qui est déjà entré aujourd'hui : l'écran montre ce qui RESTE du plafond, pas le plafond
                            'entre_du_jour', (select coalesce(sum(montant), 0) from depot_declarations
                                               where compte_id = c.id and etat = 'credite' and credite_le >= debut_du_jour()))
$$;
drop table if exists codes_secrets;
delete from parametres where cle = 'code_secret';

-- ───────────────────── 8 · le facteur des e-mails (clé de service) ─────────
-- La fonction « courriel » ne lit la boîte que par ces trois fonctions.
create or replace function courriels_a_traiter(p_n int default 20) returns setof bigint
language sql stable set search_path = public as $$
  select id from courriels_a_envoyer
   where (etat = 'en_attente' or (etat = 'en_cours' and pris_le < now() - interval '2 minutes'))
     and essais < 5 and (expire_le is null or expire_le > now())
   order by id limit least(greatest(coalesce(p_n, 20), 1), 50)
$$;

-- Prendre une ligne : l'adresse vient d'Auth AU MOMENT d'envoyer, jamais d'une requête.
create or replace function courriel_prendre(p_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c courriels_a_envoyer; v_email text; v_v verifications;
begin
  select * into c from courriels_a_envoyer where id = p_id for update skip locked;
  if c.id is null then return null; end if;
  if c.etat not in ('en_attente', 'en_cours') or c.essais >= 5 or (c.etat = 'en_cours' and c.pris_le >= now() - interval '2 minutes') then
    return null;
  end if;
  if c.expire_le is not null and c.expire_le <= now() then
    update courriels_a_envoyer set etat = 'abandonne', donnees = donnees - 'code' where id = c.id;
    return null;
  end if;
  if c.gabarit = 'verification' then
    select * into v_v from verifications where id = (c.donnees ->> 'verification_id')::uuid;
    if v_v.id is null or v_v.consommee_le is not null or v_v.remplacee_le is not null or v_v.expire_le <= now() then
      update courriels_a_envoyer set etat = 'abandonne', donnees = donnees - 'code' where id = c.id;
      return null;
    end if;
  end if;
  v_email := coalesce(c.destinataire, (select email from auth.users where id = c.compte_id), (select email from comptes where id = c.compte_id));
  if coalesce(v_email, '') = '' then
    update courriels_a_envoyer set etat = 'echoue', erreur = 'pas d''adresse', donnees = donnees - 'code' where id = c.id;
    return null;
  end if;
  update courriels_a_envoyer set etat = 'en_cours', pris_le = now(), essais = essais + 1 where id = c.id;
  return jsonb_build_object('id', c.id, 'gabarit', c.gabarit, 'donnees', c.donnees, 'email', v_email,
                            'idempotence', 'glisil-courriel-' || c.id);
end $$;

create or replace function courriel_resultat(p_id bigint, p_ok boolean, p_fournisseur_id text default null,
                                             p_erreur text default null, p_definitif boolean default false) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_ok then
    update courriels_a_envoyer set etat = 'envoye', envoye_le = now(), fournisseur_id = left(p_fournisseur_id, 200), erreur = null,
                                   donnees = donnees - 'code'
     where id = p_id and etat = 'en_cours';
  else
    update courriels_a_envoyer
       set etat = case when p_definitif or essais >= 5 then 'echoue' else 'en_attente' end,
           erreur = left(coalesce(p_erreur, 'échec'), 300),
           donnees = case when p_definitif or essais >= 5 then donnees - 'code' else donnees end
     where id = p_id and etat = 'en_cours';
  end if;
end $$;

-- Réveiller la fonction (copie de reveiller_veilleur, 0006) : rien si le coffre, pg_net ou un secret manque.
create or replace function _reveiller_courriel(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare v_url text; v_jeton text;
begin
  if to_regclass('vault.decrypted_secrets') is null or to_regnamespace('net') is null then return; end if;
  execute $q$select (select decrypted_secret from vault.decrypted_secrets where name = 'courriel_url'),
                    (select decrypted_secret from vault.decrypted_secrets where name = 'courriel_jeton')$q$ into v_url, v_jeton;
  if v_url is null or v_jeton is null then return; end if;
  execute $q$select net.http_post(url := $1, headers := $2, body := $3, timeout_milliseconds := 5000)$q$
    using v_url, jsonb_build_object('content-type', 'application/json', 'x-courriel-jeton', v_jeton),
          case when p_id is null then '{}'::jsonb else jsonb_build_object('id', p_id) end;
end $$;

-- pg_net met la requête en file au COMMIT : une transaction annulée n'envoie rien.
create or replace function _courriel_insere() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform _reveiller_courriel(new.id);
  return new;
end $$;
drop trigger if exists courriels_reveil on courriels_a_envoyer;
create trigger courriels_reveil after insert on courriels_a_envoyer for each row execute function _courriel_insere();

-- Chaque minute : les codes expirés s'effacent, et ce qui attend est réveillé.
create or replace function _vider_courriels() returns void
language plpgsql security definer set search_path = public as $$
begin
  update courriels_a_envoyer
     set donnees = donnees - 'code', etat = case when etat in ('en_attente', 'en_cours') then 'abandonne' else etat end
   where donnees ? 'code' and expire_le < now();
  if exists (select 1 from courriels_a_traiter(1)) then perform _reveiller_courriel(null); end if;
end $$;

do $$
begin
  if to_regnamespace('cron') is null or to_regnamespace('net') is null then
    raise notice 'pg_cron ou pg_net absent : les e-mails ne partiront qu''au réveil par la fonction (activez les deux extensions)';
    return;
  end if;
  execute $q$select cron.unschedule(jobid) from cron.job where jobname = 'glisil-courriels'$q$;
  execute $q$select cron.schedule('glisil-courriels', '* * * * *', 'select public._vider_courriels()')$q$;
end $$;

-- ─────────────────────────────── 9 · le support ────────────────────────────
create or replace function admin_verifications(p_compte uuid, p_n int default 20) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _exiger_droit('clients');
  return jsonb_build_object(
    'verrou_jusqua', _verrou_verification(p_compte),
    'verifications', (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'operation', v.operation, 'affichage', v.affichage, 'cree_le', v.cree_le,
                                                                   'essais', v.essais, 'consommee_le', v.consommee_le, 'remplacee_le', v.remplacee_le,
                                                                   'expiree', v.consommee_le is null and v.expire_le <= now(),
                                                                   'operation_ref', v.operation_ref,
                                                                   'courriel', (select etat from courriels_a_envoyer where id = v.courriel_id))
                                                order by v.cree_le desc), '[]'::jsonb)
                        from (select * from verifications where compte_id = p_compte order by cree_le desc
                               limit least(greatest(coalesce(p_n, 20), 1), 100)) v));
end $$;

create or replace function admin_lever_verrou_verification(p_compte uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  perform _exiger_droit('clients');
  if length(trim(coalesce(p_note, ''))) < 5 then raise exception 'note trop courte' using detail = 'dites pourquoi le blocage est levé'; end if;
  perform 1 from comptes where id = p_compte for no key update;
  if not found then raise exception 'compte inconnu'; end if;
  delete from verification_echecs
   where compte_id = p_compte and cree_le > now() - make_interval(mins => (parametre('verification') ->> 'fenetre_minutes')::int);
  get diagnostics n = row_count;
  perform _journaliser('lever_verrou_verification', p_compte::text, jsonb_build_object('note', trim(p_note), 'echecs', n));
  return jsonb_build_object('ok', true, 'echecs_effaces', n);
end $$;

-- ─────────────────────────────── 10 · les droits ───────────────────────────
revoke all on function _clore_verification_rejouee(uuid, text, uuid), _aal(), _totp_frais(timestamptz), _mot_de_passe_juste(uuid, text), _verrou_verification(uuid), _email_masque(text),
  _code_a_six_chiffres(), _envoyer_courriel(uuid, text, jsonb, text, timestamptz, text), _exiger_fermeture_possible(uuid),
  _parametres_de(uuid, text, jsonb), _empreinte(text, jsonb), preparer_verification(text, jsonb), ma_verification(uuid),
  _echec_verification(verifications, text), _consommer_verification(uuid, text, jsonb, uuid, text, text),
  _demander_sortie(numeric, uuid, text, text), demander_sortie(numeric, uuid, text, uuid, text, text, text),
  _demander_retrait_crypto(text, text, text, numeric, text), demander_retrait_crypto(text, text, text, numeric, text, uuid, text, text),
  _fermer_compte(uuid, text), fermer_mon_compte(uuid, text, text, text), _retirer_numero(uuid, uuid), retirer_numero(uuid, uuid, text, text),
  _compte_json(comptes), courriels_a_traiter(int), courriel_prendre(bigint), courriel_resultat(bigint, boolean, text, text, boolean),
  _reveiller_courriel(bigint), _courriel_insere(), _vider_courriels(), admin_verifications(uuid, int), admin_lever_verrou_verification(uuid, text)
  from public, anon, authenticated;
grant execute on function preparer_verification(text, jsonb), ma_verification(uuid),
  demander_sortie(numeric, uuid, text, uuid, text, text, text), demander_retrait_crypto(text, text, text, numeric, text, uuid, text, text),
  fermer_mon_compte(uuid, text, text, text), retirer_numero(uuid, uuid, text, text),
  admin_verifications(uuid, int), admin_lever_verrou_verification(uuid, text) to authenticated;
grant execute on function courriels_a_traiter(int), courriel_prendre(bigint), courriel_resultat(bigint, boolean, text, text, boolean),
  _envoyer_courriel(uuid, text, jsonb, text, timestamptz, text), _vider_courriels() to service_role;
$sql$;
    raise notice '0036_verification_avant_sortie.sql : appliquée';
  end if;
end $consolide$;

-- ─── 0037_langue_des_courriels.sql (md5 842705a6cfa5c09e5a05caf5fddaea59) ───
-- déjà en place si : rejouable telle quelle
do $consolide$
begin
  if false then
    raise notice '0037_langue_des_courriels.sql : déjà en place, rien à faire';
  else
    execute $sql$
-- ╔════════════════════════════════════════════════════════════════════════╗
-- ║  Glisil · 0037 · la langue des e-mails                                 ║
-- ║                                                                        ║
-- ║  Les e-mails partaient tous en français. Glisil parle ANGLAIS par      ║
-- ║  défaut ; un client français choisit le français. Le choix vit dans    ║
-- ║  le compte (comptes.langue) et il est recopié dans les métadonnées     ║
-- ║  d'Auth : les gabarits de Supabase (mot de passe oublié,               ║
-- ║  réauthentification) ne lisent QUE celles-là                           ║
-- ║  ({{ if eq .Data.langue "fr" }} … {{ else }} … {{ end }}).             ║
-- ║                                                                        ║
-- ║  1. comptes.langue : « en » ou « fr », « en » par défaut.              ║
-- ║  2. choisir_ma_langue : le client change d'avis, en session forte.     ║
-- ║  3. ouvrir_mon_compte : la langue choisie à l'inscription (passée par  ║
-- ║     signUp dans les métadonnées) devient celle du compte.              ║
-- ║  4. courriel_prendre dit à la fonction « courriel » dans quelle        ║
-- ║     langue écrire ; mon_compte la montre à l'écran.                    ║
-- ╚════════════════════════════════════════════════════════════════════════╝

-- ───────────────────── 0 · ce qui doit exister chez Supabase ───────────────
-- GoTrue range dans raw_user_meta_data ce que signUp passe en options.data :
-- la colonne existe toujours chez Supabase. Le harnais imite auth.users sans
-- elle ; on l'y ajoute, et SEULEMENT là où elle manque (chez Supabase, aucun
-- ALTER ne part : la table appartient à GoTrue).
do $$ begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'auth' and table_name = 'users' and column_name = 'raw_user_meta_data') then
    alter table auth.users add column raw_user_meta_data jsonb;
  end if;
end $$;
-- Le choix se recopie dans les métadonnées : si la base ne peut pas y écrire,
-- on refuse de s'installer plutôt que d'envoyer en silence un e-mail de mot de
-- passe dans la mauvaise langue (même règle que 0036 pour le mot de passe).
do $$ begin
  -- deux appels : avec « select, update » en une fois, un seul des deux suffirait à répondre oui
  if not (has_column_privilege('auth.users', 'raw_user_meta_data', 'select')
          and has_column_privilege('auth.users', 'raw_user_meta_data', 'update')) then
    raise exception 'langue des e-mails : auth.users.raw_user_meta_data illisible ou non modifiable'
      using detail = 'les gabarits d''Auth ne pourraient pas suivre la langue du compte';
  end if;
end $$;

-- ─────────────────────────────── 1 · la colonne ────────────────────────────
alter table comptes add column if not exists langue text not null default 'en'
  constraint comptes_langue_connue check (langue in ('fr', 'en'));

-- Les comptes déjà ouverts : la langue donnée à l'inscription si elle est
-- connue, sinon l'anglais (le défaut de la colonne, déjà posé).
update comptes c set langue = u.raw_user_meta_data ->> 'langue'
  from auth.users u
 where u.id = c.id and u.raw_user_meta_data ->> 'langue' in ('fr', 'en')
   and c.langue is distinct from u.raw_user_meta_data ->> 'langue';

-- La langue d'une personne d'Auth, telle que signUp l'a rangée — ou null si
-- elle n'en a pas donné, ou une qu'on ne sait pas écrire.
create or replace function _langue_d_auth(p_utilisateur uuid) returns text
language sql stable security definer set search_path = public as $$
  select case when u.raw_user_meta_data ->> 'langue' in ('fr', 'en') then u.raw_user_meta_data ->> 'langue' end
    from auth.users u where u.id = p_utilisateur
$$;

-- ──────────────────────────── 2 · choisir sa langue ────────────────────────
-- La session forte, comme tout ce qui touche au compte. Le compte n'est pas
-- exigé : la personne qui n'a pas encore fini son inscription reçoit, elle
-- aussi, des e-mails d'Auth. Les deux écritures vont ensemble : le compte
-- (lu par la boîte d'envoi) et les métadonnées (lues par les gabarits d'Auth).
create or replace function choisir_ma_langue(p_langue text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_langue text := p_langue;
begin
  perform _exiger_aal2();
  if v_uid is null then raise exception 'non connecté'; end if;
  -- à la lettre : « FR » ou « fr  » sont refusés plutôt que devinés
  if v_langue is null or v_langue not in ('fr', 'en') then raise exception 'langue inconnue' using detail = 'fr ou en'; end if;
  update comptes set langue = v_langue where id = v_uid;
  update auth.users set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object('langue', v_langue)
   where id = v_uid;
  return jsonb_build_object('ok', true, 'langue', v_langue);
end $$;

-- ─────────────────────── 3 · le compte montre sa langue ────────────────────
-- Même forme que 0036, une clé de plus : « langue ».
create or replace function _compte_json(c comptes) returns jsonb
language sql stable set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', c.id, 'telephone', c.telephone, 'nom', c.nom, 'entreprise', c.entreprise, 'palier', c.palier,
                            'email', c.email, 'prenom', c.prenom, 'nom_de_famille', c.nom_de_famille,
                            'date_naissance', c.date_naissance, 'ville', c.ville, 'pays', c.pays,
                            'langue', c.langue,
                            'verification_en_cours', c.verification_en_cours,
                            'conditions_version', c.conditions_version, 'conditions_acceptees_le', c.conditions_acceptees_le,
                            'conditions_a_jour', c.maison or c.conditions_version is not distinct from (parametre('conditions') ->> 'version'),
                            'ferme_le', c.ferme_le, 'desactive', c.desactive_le is not null,
                            -- ce qui est déjà entré aujourd'hui : l'écran montre ce qui RESTE du plafond, pas le plafond
                            'entre_du_jour', (select coalesce(sum(montant), 0) from depot_declarations
                                               where compte_id = c.id and etat = 'credite' and credite_le >= debut_du_jour()))
$$;

-- ─────────────────── 4 · ouvrir son compte, dans sa langue ─────────────────
-- 0035 à l'identique, sauf la langue : celle que l'écran d'inscription a
-- passée à signUp, sinon l'anglais.
create or replace function ouvrir_mon_compte(p_prenom text, p_nom text, p_naissance date, p_telephone text, p_ville text, p_pays text, p_conditions text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email  text := _email_prouve();
  v_prenom text := _nom_propre(p_prenom);
  v_nom    text := _nom_propre(p_nom);
  v_ville  text := _nom_propre(p_ville);
  v_pays   text := upper(trim(coalesce(p_pays, '')));
  v_tel    text := regexp_replace(coalesce(p_telephone, ''), '[^0-9+]', '', 'g');
  v_age    int;
  v_c      comptes;
  v_contrainte text;
begin
  perform _exiger_aal2();
  if auth.uid() is null then raise exception 'non connecté'; end if;
  if v_email is null then raise exception 'adresse e-mail non vérifiée' using detail = 'entrez le code reçu par e-mail'; end if;
  if not _mot_de_passe_pose(auth.uid()) then raise exception 'mot de passe à choisir' using detail = 'il protège chaque sortie d''argent'; end if;
  if not exists (select 1 from lots_de_secours where utilisateur_id = auth.uid() and confirme_le is not null) then
    raise exception 'codes de secours à noter' using detail = 'ils vous rendent l''accès si vous perdez votre téléphone';
  end if;
  if exists (select 1 from comptes where id = auth.uid()) then raise exception 'compte déjà ouvert'; end if;

  if v_prenom is null then raise exception 'prénom invalide' using detail = 'des lettres, de 2 à 60'; end if;
  if v_nom is null then raise exception 'nom invalide' using detail = 'des lettres, de 2 à 60'; end if;

  if p_naissance is null then raise exception 'date de naissance manquante'; end if;
  v_age := extract(year from age((now() at time zone 'Africa/Douala')::date, p_naissance))::int;
  if p_naissance > (now() at time zone 'Africa/Douala')::date or v_age > 120 then raise exception 'date de naissance invalide'; end if;
  if v_age < 18 then raise exception 'il faut avoir 18 ans' using detail = 'Glisil est un service financier'; end if;

  if v_tel !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'numéro de téléphone invalide' using detail = 'au format international, avec l''indicatif'; end if;
  if v_tel like '+237%' and v_tel !~ '^\+237[62][0-9]{8}$' then
    raise exception 'numéro de téléphone invalide' using detail = 'au Cameroun : neuf chiffres, commençant par 6 ou 2';
  end if;
  if exists (select 1 from comptes where telephone = v_tel and ferme_le is null) then
    raise exception 'ce numéro est déjà utilisé' using detail = 'il appartient à un autre compte';
  end if;

  if v_ville is null then raise exception 'ville invalide' using detail = 'des lettres, de 2 à 60'; end if;
  if v_pays !~ '^[A-Z]{2}$' then raise exception 'pays invalide'; end if;

  if p_conditions is distinct from (parametre('conditions') ->> 'version') then
    raise exception 'conditions non acceptées' using detail = 'lisez et acceptez les conditions en vigueur';
  end if;

  insert into comptes (id, telephone, email, prenom, nom_de_famille, nom, date_naissance, ville, pays, conditions_version, conditions_acceptees_le, langue)
  values (auth.uid(), v_tel, v_email, v_prenom, v_nom, v_prenom || ' ' || v_nom, p_naissance, v_ville, v_pays, p_conditions, now(),
          coalesce(_langue_d_auth(auth.uid()), 'en'))
  returning * into v_c;
  return _compte_json(v_c);
exception when unique_violation then
  -- deux inscriptions au même instant : la vérification plus haut ne voit pas l'autre, l'index, si
  get stacked diagnostics v_contrainte = constraint_name;
  if v_contrainte = 'comptes_telephone_ouvert' then raise exception 'ce numéro est déjà utilisé' using detail = 'il appartient à un autre compte';
  elsif v_contrainte = 'comptes_email_unique' then raise exception 'cette adresse est déjà utilisée';
  elsif v_contrainte = 'comptes_pkey' then raise exception 'compte déjà ouvert';
  else raise; end if;
end $function$;

-- ───────────────── 5 · la boîte d'envoi dit dans quelle langue ─────────────
-- 0036 à l'identique, une clé de plus : « langue ». Celle du compte, lue AU
-- MOMENT d'envoyer (un client qui vient de changer d'avis est entendu même
-- pour un e-mail déjà en file) ; pour une adresse hors des clients (l'équipe),
-- celle que le moteur a posée dans les données, sinon l'anglais.
create or replace function courriel_prendre(p_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c courriels_a_envoyer; v_email text; v_v verifications; v_langue text;
begin
  select * into c from courriels_a_envoyer where id = p_id for update skip locked;
  if c.id is null then return null; end if;
  if c.etat not in ('en_attente', 'en_cours') or c.essais >= 5 or (c.etat = 'en_cours' and c.pris_le >= now() - interval '2 minutes') then
    return null;
  end if;
  if c.expire_le is not null and c.expire_le <= now() then
    update courriels_a_envoyer set etat = 'abandonne', donnees = donnees - 'code' where id = c.id;
    return null;
  end if;
  if c.gabarit = 'verification' then
    select * into v_v from verifications where id = (c.donnees ->> 'verification_id')::uuid;
    if v_v.id is null or v_v.consommee_le is not null or v_v.remplacee_le is not null or v_v.expire_le <= now() then
      update courriels_a_envoyer set etat = 'abandonne', donnees = donnees - 'code' where id = c.id;
      return null;
    end if;
  end if;
  v_email := coalesce(c.destinataire, (select email from auth.users where id = c.compte_id), (select email from comptes where id = c.compte_id));
  if coalesce(v_email, '') = '' then
    update courriels_a_envoyer set etat = 'echoue', erreur = 'pas d''adresse', donnees = donnees - 'code' where id = c.id;
    return null;
  end if;
  if c.compte_id is not null then
    v_langue := coalesce((select langue from comptes where id = c.compte_id), _langue_d_auth(c.compte_id), 'en');
  else
    v_langue := case when c.donnees ->> 'langue' in ('fr', 'en') then c.donnees ->> 'langue' else 'en' end;
  end if;
  update courriels_a_envoyer set etat = 'en_cours', pris_le = now(), essais = essais + 1 where id = c.id;
  return jsonb_build_object('id', c.id, 'gabarit', c.gabarit, 'donnees', c.donnees, 'email', v_email, 'langue', v_langue,
                            'idempotence', 'glisil-courriel-' || c.id);
end $$;

-- ─────────────────────────────── 6 · les droits ────────────────────────────
-- create or replace garde les droits de _compte_json, ouvrir_mon_compte et
-- courriel_prendre (0035, 0036) ; seules les deux fonctions neuves sont posées.
revoke all on function _langue_d_auth(uuid), choisir_ma_langue(text) from public, anon, authenticated;
grant execute on function _langue_d_auth(uuid), choisir_ma_langue(text) to service_role;
grant execute on function choisir_ma_langue(text) to authenticated;
$sql$;
    raise notice '0037_langue_des_courriels.sql : appliquée';
  end if;
end $consolide$;

-- ─── 0038_sortie_manuelle_prouvee.sql (md5 435dec60ab978c4146556d5456a4c923) ───
-- déjà en place si : rejouable telle quelle
do $consolide$
begin
  if false then
    raise notice '0038_sortie_manuelle_prouvee.sql : déjà en place, rien à faire';
  else
    execute $sql$
-- ╔════════════════════════════════════════════════════════════════════════╗
-- ║  Glisil · 0038 · le remboursement manuel, PROUVÉ par la puce            ║
-- ║                                                                        ║
-- ║  Jusqu'ici (0014), taper un transaction ID suffisait : les XAFe du     ║
-- ║  client étaient détruits aussitôt, le SMS de la puce ne servait qu'à   ║
-- ║  informer. Une faute de frappe, un ID inventé, et Glisil détruisait    ║
-- ║  de l'argent pour un paiement qui n'avait pas eu lieu.                 ║
-- ║                                                                        ║
-- ║  Maintenant, l'ID tapé met la sortie « en preuve ». Ses XAFe ne sont   ║
-- ║  détruits que lorsque TOTEM a relevé, sur une puce de Glisil, le SMS   ║
-- ║  de l'opérateur qui montre CE paiement : même ID, même montant, même   ║
-- ║  numéro, relevé après la demande, d'un terminal du même monde (vrai    ║
-- ║  ou démo), et qui ne prouve pas déjà une autre sortie. La règle vit    ║
-- ║  DANS _clore_sortie_manuelle : aucun appelant ne la contourne.         ║
-- ║                                                                        ║
-- ║  1. l'état « en_preuve », les colonnes de la preuve ;                  ║
-- ║  2. sortie_paiements : un gros remboursement se paie en plusieurs      ║
-- ║     transferts (les opérateurs plafonnent un transfert), un ID chacun ;║
-- ║  3. le réglage : mode manuel, seuil null (le propriétaire seul),       ║
-- ║     forçage fermé ;                                                    ║
-- ║  4. la preuve, la clôture (une seule fois), la tentative de clôture ;  ║
-- ║  5. l'équipe : payer, corriger un ID mal tapé, revérifier, confirmer   ║
-- ║     (au-delà du seuil), forcer (dernier recours), refuser ;            ║
-- ║  6. le SMS sortant de TOTEM clôt la sortie qui l'attendait ; l'ID tapé ║
-- ║     et le SMS qui arrive prennent le MÊME verrou (course 12.4) ;       ║
-- ║  7. le client voit « en vérification », ses ID, et reçoit un e-mail.   ║
-- ║                                                                        ║
-- ║  Les sorties de démo (0032) gardent leur chemin : payées par TOTEM     ║
-- ║  démo, closes sans SMS. Rien ne change dans la porte de TOTEM.         ║
-- ╚════════════════════════════════════════════════════════════════════════╝

-- ──────────────────────── 1 · l'état et les colonnes ───────────────────────
alter table sorties drop constraint if exists sorties_etat_check;
alter table sorties add constraint sorties_etat_check
  check (etat in ('en_attente', 'en_cours', 'en_preuve', 'envoyee', 'partielle', 'echouee', 'annulee'));
alter table sorties add column if not exists prouvee_le     timestamptz;  -- le SMS de la puce a prouvé le dernier paiement (null : forcée, ou démo)
alter table sorties add column if not exists cloture_erreur text;         -- la preuve était là, la clôture a échoué : dit à l'équipe, effacé au succès
alter table sorties add column if not exists forcee_par     uuid;
alter table sorties add column if not exists forcee_le      timestamptz;
alter table sorties add column if not exists forcee_note    text;
drop index if exists sorties_manuelles_a_traiter;
create index sorties_manuelles_a_traiter on sorties (cree_le) where mode = 'manuel' and etat in ('en_attente', 'en_cours', 'en_preuve');

-- ───────────────────── 2 · un paiement par transfert ───────────────────────
-- sorties.transaction_id garde le PREMIER ID actif : les sorties de démo, le
-- texte de la notification et l'index sorties_un_paiement le lisent toujours.
create table if not exists sortie_paiements (
  id             bigint generated always as identity primary key,
  sortie_id      uuid not null references sorties(id),
  operateur      text not null,
  transaction_id text not null,                                   -- normaliser_transaction_id()
  montant        numeric(20,2) not null check (montant > 0 and montant = trunc(montant)),
  constatee_id   bigint references sorties_constatees(id),        -- le SMS qui l'a prouvé, posé à la clôture
  saisi_par      uuid,                                            -- null : repris d'avant, ou TOTEM démo
  saisi_le       timestamptz not null default now(),
  retire_le      timestamptz, retire_par uuid, retire_note text   -- un ID ou un montant mal tapé, remplacé (admin_corriger_paiement)
);
create unique index if not exists sortie_paiements_un_id on sortie_paiements (operateur, transaction_id) where retire_le is null;
create index if not exists sortie_paiements_de_la_sortie on sortie_paiements (sortie_id) where retire_le is null;
alter table sortie_paiements enable row level security;
revoke all on table sortie_paiements from public, anon, authenticated;
grant all on table sortie_paiements to service_role;

-- reprise (bases de bêta seulement ; vide en production), une fois
insert into sortie_paiements (sortie_id, operateur, transaction_id, montant, saisi_par, saisi_le)
select s.id, s.operateur, s.transaction_id, s.montant_xaf, s.payee_par, s.payee_le from sorties s
 where s.mode = 'manuel' and s.transaction_id is not null and s.payee_le is not null
   and not exists (select 1 from sortie_paiements p where p.sortie_id = s.id);
update sorties set etat = 'en_preuve' where mode = 'manuel' and etat = 'en_cours' and payee_le is not null;
-- sorties_constatees.sortie_id veut dire maintenant « la sortie que ce SMS a PROUVÉE » : seule la
-- clôture le pose (plus à l'insertion, plus à la saisie). Les liens d'avant sont gardés.

-- ─────────────────────────────── 3 · le réglage ────────────────────────────
-- La partie droite l'emporte : une clé que l'équipe a déjà posée est gardée.
-- « ouvertes » n'est pas touché : le profil de production en décide.
update parametres set valeur = jsonb_build_object('mode', 'manuel', 'seuil_deux_personnes', null, 'forcage', false) || valeur where cle = 'sortie';
create or replace function _verifier_parametre(p_cle text, v jsonb) returns void
language plpgsql set search_path = public, extensions, pg_temp as $$
declare k text; p jsonb; ok boolean;
begin
  if jsonb_typeof(v) <> 'object' then raise exception 'paramètre invalide' using detail = 'un objet JSON est attendu'; end if;
  ok := case p_cle
    when 'frais' then _nombre_entre(v -> 'placeur', 0, 0.05) and _nombre_entre(v -> 'preneur', 0, 0.05) and _nombre_entre(v -> 'sortie', 0, 0.05)
    when 'marche' then v ->> 'paire' = 'USDT/XAFe' and _nombre_entre(v -> 'pas_prix', 0.01, 100) and _nombre_entre(v -> 'quantite_min', 0.01, 1000000)
                       and jsonb_typeof(v -> 'ouvert') = 'boolean'
                       -- les règles du marché (0017) : chacune facultative, chacune bornée
                       -- vide : sans plafond (0027)
                       and (not (v ? 'quantite_max') or jsonb_typeof(v -> 'quantite_max') = 'null' or _nombre_entre(v -> 'quantite_max', (v ->> 'quantite_min')::numeric, 1e12))
                       and (not (v ? 'marche_quantite_max') or jsonb_typeof(v -> 'marche_quantite_max') = 'null' or _nombre_entre(v -> 'marche_quantite_max', (v ->> 'quantite_min')::numeric, 1e12))
                       and (not (v ? 'montant_min') or _nombre_entre(v -> 'montant_min', 0, 1e9))
                       and (not (v ? 'ordres_ouverts_max') or _nombre_entre(v -> 'ordres_ouverts_max', 1, 10000, true))
                       and (not (v ? 'bande_execution') or _nombre_entre(v -> 'bande_execution', 0.001, 0.5))
                       and (not (v ? 'bande_achat') or (jsonb_typeof(v -> 'bande_achat') = 'array' and jsonb_array_length(v -> 'bande_achat') = 2
                            and _nombre_entre(v -> 'bande_achat' -> 0, 0.01, 1) and _nombre_entre(v -> 'bande_achat' -> 1, 1, 100)))
                       and (not (v ? 'bande_vente') or (jsonb_typeof(v -> 'bande_vente') = 'array' and jsonb_array_length(v -> 'bande_vente') = 2
                            and _nombre_entre(v -> 'bande_vente' -> 0, 0.01, 1) and _nombre_entre(v -> 'bande_vente' -> 1, 1, 100)))
                       and (not (v ? 'prix_reference') or jsonb_typeof(v -> 'prix_reference') = 'null' or _nombre_entre(v -> 'prix_reference', 0.01, 1e9))
    when 'depot' then _nombre_entre(v -> 'validite_minutes', 5, 1440, true) and _nombre_entre(v -> 'grace_minutes', 0, 10080, true)
                      and (not (v ? 'declaration_complete') or jsonb_typeof(v -> 'declaration_complete') = 'boolean')
    when 'sortie' then _nombre_entre(v -> 'reprises_max', 1, 10, true)
                       and (not (v ? 'ouvertes') or jsonb_typeof(v -> 'ouvertes') = 'boolean')
                       and (not (v ? 'mode') or v ->> 'mode' in ('totem', 'manuel'))
                       and (not (v ? 'seuil_deux_personnes') or jsonb_typeof(v -> 'seuil_deux_personnes') = 'null'
                            or _nombre_entre(v -> 'seuil_deux_personnes', 1, 1e12))
                       -- 0038 : le forçage (clore sans le SMS de la puce), fermé par défaut
                       and (not (v ? 'forcage') or jsonb_typeof(v -> 'forcage') = 'boolean')
    when 'rapide' then _nombre_entre(v -> 'marge', 0, 0.2) and _nombre_entre(v -> 'validite_secondes', 5, 120, true)
                       and jsonb_typeof(v -> 'ouvert') = 'boolean'
    when 'code_secret' then _nombre_entre(v -> 'essais', 1, 10, true) and _nombre_entre(v -> 'verrou_minutes', 1, 1440, true)
                       and _nombre_entre(v -> 'longueur_min', 4, 6, true) and _nombre_entre(v -> 'longueur_max', 4, 8, true)
                       and (v ->> 'longueur_min')::int <= (v ->> 'longueur_max')::int
    when 'crypto' then _nombre_entre(v -> 'frais' -> 'USDT', 0, 1000) and _nombre_entre(v -> 'frais' -> 'XAFe', 0, 1000000)
                       and _nombre_entre(v -> 'confirmations' -> 'bep20', 1, 1000, true) and _nombre_entre(v -> 'confirmations' -> 'trc20', 1, 1000, true)
                       and jsonb_typeof(v -> 'retraits_ouverts') = 'boolean'
                       and (not (v ? 'depots_ouverts') or jsonb_typeof(v -> 'depots_ouverts') = 'boolean')
    when 'paliers' then (select bool_and(x) from (values (v ? '0'), (v ? '1'), (v ? '2')) t(x))
    when 'conditions' then coalesce(v ->> 'version', '') ~ '^\d{4}-\d{2}-\d{2}$'
    when 'support' then coalesce(v ->> 'email', '') ~ '^[^@\s]+@[^@\s]+\.[a-z]{2,}$'
                        and (jsonb_typeof(v -> 'whatsapp') = 'null' or coalesce(v ->> 'whatsapp', '') ~ '^\+[1-9][0-9]{7,14}$')
    when 'robots' then jsonb_typeof(v -> 'actif') = 'boolean'
                       and jsonb_typeof(v -> 'teneur') = 'object' and jsonb_typeof(v -> 'traders') = 'object' and jsonb_typeof(v -> 'derive') = 'object'
                       and _nombre_entre(v -> 'teneur' -> 'ecart', 0.0005, 0.05) and _nombre_entre(v -> 'teneur' -> 'niveaux', 1, 20, true)
                       and _nombre_entre(v -> 'teneur' -> 'pas', 0, 0.02) and _nombre_entre(v -> 'teneur' -> 'taille_usdt', 10, 100000)
                       and _nombre_entre(v -> 'teneur' -> 'tolerance', 0, 0.01) and _nombre_entre(v -> 'teneur' -> 'inventaire', 0, 0.05)
                       and _nombre_entre(v -> 'traders' -> 'probabilite', 0, 1) and _nombre_entre(v -> 'traders' -> 'taille_min', 10, 100000)
                       and _nombre_entre(v -> 'traders' -> 'taille_max', 10, 100000)
                       and (v -> 'traders' ->> 'taille_min')::numeric <= (v -> 'traders' ->> 'taille_max')::numeric
                       and _nombre_entre(v -> 'traders' -> 'part_preneur', 0, 1) and _nombre_entre(v -> 'traders' -> 'duree_minutes', 1, 1440, true)
                       and _nombre_entre(v -> 'traders' -> 'ordres_max', 0, 50, true)
                       and _nombre_entre(v -> 'derive' -> 'volatilite', 0, 0.01) and _nombre_entre(v -> 'derive' -> 'rappel', 0, 1)
                       and _nombre_entre(v -> 'derive' -> 'borne', 0, 0.1) and _nombre_entre(v -> 'derive' -> 'choc_probabilite', 0, 0.1)
                       and _nombre_entre(v -> 'derive' -> 'choc_max', 0, 0.05)
    when 'cours' then jsonb_typeof(v -> 'actif') = 'boolean' and _nombre_entre(v -> 'prime', -0.2, 0.2) and _nombre_entre(v -> 'saut_max', 0.005, 0.5)
    when 'beta' then jsonb_typeof(v -> 'actif') = 'boolean' and jsonb_typeof(v -> 'depots_reels') = 'boolean'
                     and (jsonb_typeof(v -> 'message') = 'null' or length(coalesce(v ->> 'message', '')) between 1 and 300)
                     and jsonb_typeof(v -> 'dotation') = 'object'
                     and _nombre_entre(v -> 'dotation' -> 'XAFe', 0, 100000000, true) and _nombre_entre(v -> 'dotation' -> 'USDT', 0, 1000000)
    when 'numeros' then jsonb_typeof(v -> 'verification_sms') = 'boolean' and _nombre_entre(v -> 'delai_heures', 0, 168, true)
    when 'parite' then (jsonb_typeof(v -> 'alerte_numero') = 'null' or coalesce(v ->> 'alerte_numero', '') ~ '^\+?[0-9 ]{9,16}$')
                       and coalesce(v ->> 'alerte_operateur', '') in ('mtn', 'om')
                       and _nombre_entre(v -> 'fraicheur_heures', 1, 720, true) and _nombre_entre(v -> 'delai_minutes', 5, 1440, true)
                       and jsonb_typeof(v -> 'publier_floats') = 'boolean'
    else false end;
  if p_cle = 'paliers' and ok then
    foreach k in array array['0', '1', '2'] loop
      p := v -> k;
      if jsonb_typeof(p) = 'null' then continue; end if;
      if not (jsonb_typeof(p) = 'object' and _nombre_entre(p -> 'entree_jour', 0, 1e12, true) and _nombre_entre(p -> 'sortie_jour', 0, 1e12, true)) then
        ok := false;
      end if;
    end loop;
  end if;
  if not coalesce(ok, false) then
    raise exception 'paramètre invalide' using detail = format('« %s » : une clé manque, ou une valeur sort de ses bornes', p_cle);
  end if;
end $$;

-- ─────────────────────── 4 · la preuve et la clôture ───────────────────────
-- Au-delà du seuil (s'il y en a un), une seconde personne confirme.
create or replace function _seuil_atteint(s sorties) returns boolean
language sql stable set search_path = public as $$
  select nullif(parametre('sortie') ->> 'seuil_deux_personnes', '')::numeric is not null
     and s.montant_xaf >= nullif(parametre('sortie') ->> 'seuil_deux_personnes', '')::numeric
$$;

-- UN paiement jugé contre les SMS relevés qui portent son ID. Le premier motif
-- qui manque dit pourquoi, en mots ; un SMS qui concorde l'emporte sur les autres.
create or replace function _preuve_du_paiement(p_operateur text, p_transaction_id text, p_montant numeric, s sorties) returns jsonb
language sql stable set search_path = public as $$
  with c as (
    select k.id, k.montant, k.numero_beneficiaire, k.terminal, k.emis_le, k.texte,
      case
        when k.float_id is null then 'le SMS vient d''une puce qui n''est pas un float Glisil de ce terminal'
        when coalesce(t.demo, false) and not numero_de_demo(s.numero) then 'le SMS vient d''un terminal de démo'
        when not coalesce(t.demo, false) and numero_de_demo(s.numero) then 'le SMS vient d''un vrai terminal, la sortie est de démo'
        when k.sortie_id is not null and k.sortie_id <> s.id then 'ce SMS prouve déjà une autre sortie'
        when k.recu_le < s.cree_le then 'ce paiement a été relevé avant la demande du client'
        when k.montant is null then 'le SMS ne dit pas le montant'
        when k.montant <> p_montant then format('le SMS dit %s XAF, ce paiement %s XAF', to_char(k.montant, 'FM999G999G999G999'), to_char(p_montant, 'FM999G999G999G999'))
        when k.numero_beneficiaire is null then 'le SMS ne dit pas le numéro du bénéficiaire : TOTEM doit apprendre ce format'
        when k.numero_beneficiaire <> s.numero then format('le SMS dit le %s, la sortie le %s', k.numero_beneficiaire, s.numero)
      end motif
      from sorties_constatees k join terminaux t on t.id = k.terminal
     where k.operateur = p_operateur and k.transaction_id = p_transaction_id),
  m as (select * from c order by (motif is null) desc, id limit 1)
  select case when not exists (select 1 from c)
    then jsonb_build_object('transaction_id', p_transaction_id, 'montant_saisi', p_montant, 'etat', 'absent', 'motif', 'le SMS de la puce n''est pas encore arrivé')
    else (select jsonb_build_object('transaction_id', p_transaction_id, 'montant_saisi', p_montant,
                                    'etat', case when m.motif is null then 'concorde' else 'ecart' end, 'motif', m.motif,
                                    'constatee_id', m.id, 'montant', m.montant, 'numero', m.numero_beneficiaire,
                                    'terminal', m.terminal, 'emis_le', m.emis_le, 'texte', m.texte) from m)
  end
$$;

-- Toute la sortie : chaque paiement actif, et leur somme. Même signature que
-- 0014 : admin_sorties, totem_sortie_demo_payee, et les gestes de l'équipe la lisent.
create or replace function _rapprochement(s sorties) returns jsonb
language plpgsql stable set search_path = public as $$
declare
  p record; x jsonb; v_paiements jsonb := '[]'::jsonb; v_paye numeric := 0;
  v_etat text; v_motif text;
begin
  for p in select operateur, transaction_id, montant from sortie_paiements where sortie_id = s.id and retire_le is null order by id loop
    x := _preuve_du_paiement(p.operateur, p.transaction_id, p.montant, s);
    v_paiements := v_paiements || jsonb_build_array(x); v_paye := v_paye + p.montant;
  end loop;
  -- une sortie de démo, ou d'avant 0038 : son seul ID
  if jsonb_array_length(v_paiements) = 0 and s.transaction_id is not null then
    x := _preuve_du_paiement(s.operateur, s.transaction_id, s.montant_xaf, s);
    v_paiements := jsonb_build_array(x); v_paye := s.montant_xaf;
  end if;
  if jsonb_array_length(v_paiements) = 0 then return null; end if;
  if exists (select 1 from jsonb_array_elements(v_paiements) e where e ->> 'etat' = 'ecart') then
    v_etat := 'ecart';
    v_motif := (select e ->> 'motif' from jsonb_array_elements(v_paiements) e where e ->> 'etat' = 'ecart' limit 1);
  elsif exists (select 1 from jsonb_array_elements(v_paiements) e where e ->> 'etat' = 'absent') then
    v_etat := 'absent';
    v_motif := (select e ->> 'motif' from jsonb_array_elements(v_paiements) e where e ->> 'etat' = 'absent' limit 1);
  elsif v_paye <> s.montant_xaf then
    v_etat := 'partiel';
    v_motif := format('%s XAF payés sur %s : il reste %s XAF à envoyer', to_char(v_paye, 'FM999G999G999G999'),
                      to_char(s.montant_xaf, 'FM999G999G999G999'), to_char(s.montant_xaf - v_paye, 'FM999G999G999G999'));
  else
    v_etat := 'concorde';
  end if;
  return jsonb_build_object('etat', v_etat, 'motif', v_motif, 'paye', v_paye, 'reste', s.montant_xaf - v_paye, 'paiements', v_paiements)
         -- un seul paiement : ses clés à plat, comme 0014 (l'écran de l'équipe les lit)
         || case when jsonb_array_length(v_paiements) = 1 then (v_paiements -> 0) - 'etat' - 'motif' - 'transaction_id' - 'montant_saisi' else '{}'::jsonb end;
end $$;

-- LA règle. Une sortie vers un vrai numéro n'est détruite que si chaque
-- paiement est prouvé par le SMS de la puce, que leur somme fait le montant,
-- et — au-delà du seuil — qu'une seconde personne a confirmé. Une seule fois :
-- appelée deux fois, elle refuse au lieu de détruire deux fois.
create or replace function _clore_sortie_manuelle(p_id uuid) returns sorties
language plpgsql set search_path = public as $$
declare v_s sorties; v_r jsonb; v_demo boolean; v_ids text;
begin
  select * into v_s from sorties where id = p_id for update;
  if not found then raise exception 'sortie inconnue'; end if;
  if v_s.mode <> 'manuel' or v_s.etat not in ('en_cours', 'en_preuve') or v_s.payee_le is null or v_s.transaction_id is null then
    raise exception 'cette sortie ne se clôt pas' using detail = v_s.etat;
  end if;
  v_demo := coalesce(numero_de_demo(v_s.numero), false);
  if not v_demo then
    if _seuil_atteint(v_s) and v_s.confirmee_par is null then
      raise exception 'une autre personne confirme' using detail = 'au-delà du seuil, deux personnes';
    end if;
    if v_s.forcee_le is null then
      v_r := _rapprochement(v_s);
      if v_r ->> 'etat' is distinct from 'concorde' then
        raise exception 'paiement pas encore prouvé' using detail = coalesce(v_r ->> 'motif', 'le SMS de la puce manque');
      end if;
      update sorties_constatees k set sortie_id = v_s.id from jsonb_array_elements(v_r -> 'paiements') e where k.id = (e ->> 'constatee_id')::bigint;
      update sortie_paiements p set constatee_id = (e ->> 'constatee_id')::bigint from jsonb_array_elements(v_r -> 'paiements') e
       where p.sortie_id = v_s.id and p.retire_le is null and p.transaction_id = e ->> 'transaction_id';
    end if;
  end if;
  -- la destruction, comme 0014
  perform _mouvement(v_s.compte_id, 'XAFe', 0, -v_s.montant, 'sortie_envoyee', 'sorties', v_s.reference);
  if v_s.frais > 0 then perform _mouvement(compte_maison(), 'XAFe', v_s.frais, 0, 'frais_sortie', 'sorties', v_s.reference); end if;
  insert into emissions (sens, montant, source_table, source_id) values ('destruction', v_s.montant_xaf, 'sorties', v_s.reference);
  update sorties set etat = 'envoyee', montant_envoye = montant_xaf, terminee_le = now(), cloture_erreur = null,
                     prouvee_le = case when not v_demo and forcee_le is null then now() end
   where id = p_id returning * into v_s;
  v_ids := coalesce((select string_agg(transaction_id, ', ' order by id) from sortie_paiements where sortie_id = v_s.id and retire_le is null), v_s.transaction_id);
  -- le texte d'avant, au caractère près : l'application le traduit (app/src/noyau/serveur.ts)
  perform _notifier(v_s.compte_id, 'Sortie envoyée',
    format('%s XAF envoyés au %s. Transaction ID : %s.', to_char(v_s.montant_xaf, 'FM999G999G999G999'), v_s.numero, v_ids),
    '/historique/' || v_s.reference);
  if not v_demo then
    perform _envoyer_courriel(v_s.compte_id, 'sortie_payee', jsonb_build_object(
      'reference', v_s.reference, 'montant', v_s.montant, 'frais', v_s.frais, 'montant_xaf', v_s.montant_xaf,
      'operateur', v_s.operateur, 'operateur_nom', (select nom from operateurs where id = v_s.operateur),
      'numero', v_s.numero, 'nom_beneficiaire', v_s.nom_beneficiaire, 'transaction_id', v_ids,
      'paiements', (select coalesce(jsonb_agg(jsonb_build_object('transaction_id', transaction_id, 'montant', montant) order by id), '[]'::jsonb)
                      from sortie_paiements where sortie_id = v_s.id and retire_le is null),
      'payee_le', v_s.payee_le, 'envoyee_le', v_s.terminee_le, 'lien', '/historique/' || v_s.reference),
      'sortie_payee:' || v_s.reference);
  end if;
  return v_s;
end $$;

-- Tenter la clôture : ne lève JAMAIS pour « pas encore prouvé » (la sortie
-- reste en preuve et dit pourquoi) ; seules les vraies erreurs remontent.
-- Les appelants prennent le verrou de l'ID AVANT la ligne de la sortie :
-- verrou de l'ID → sortie → soldes → maison.
create or replace function _tenter_cloture(p_id uuid) returns sorties
language plpgsql set search_path = public as $$
declare v_s sorties;
begin
  select * into v_s from sorties where id = p_id for update;
  if v_s.mode <> 'manuel' or v_s.etat <> 'en_preuve' then return v_s; end if;
  if v_s.forcee_le is null and not coalesce(numero_de_demo(v_s.numero), false)
     and _rapprochement(v_s) ->> 'etat' is distinct from 'concorde' then return v_s; end if;
  if _seuil_atteint(v_s) and v_s.confirmee_par is null and not coalesce(numero_de_demo(v_s.numero), false) then return v_s; end if;
  return _clore_sortie_manuelle(p_id);
end $$;

-- « C'est ce paiement » : les SMS relevés qui pourraient prouver ce qui reste à payer.
create or replace function _candidats_de_preuve(s sorties) returns jsonb
language sql stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'transaction_id', k.transaction_id, 'montant', k.montant,
                                               'emis_le', k.emis_le, 'terminal', k.terminal) order by k.recu_le desc), '[]'::jsonb)
    from (select k.* from sorties_constatees k join terminaux t on t.id = k.terminal
           where k.operateur = s.operateur and k.numero_beneficiaire = s.numero and k.recu_le >= s.cree_le
             and k.sortie_id is null and k.float_id is not null and k.transaction_id is not null
             and coalesce(t.demo, false) = coalesce(numero_de_demo(s.numero), false)
             and k.montant <= s.montant_xaf - coalesce((select sum(montant) from sortie_paiements where sortie_id = s.id and retire_le is null), 0)
             and not exists (select 1 from sortie_paiements p where p.operateur = k.operateur and p.transaction_id = k.transaction_id and p.retire_le is null)
             and not exists (select 1 from sorties x where x.operateur = k.operateur and x.transaction_id = k.transaction_id)
           order by k.recu_le desc limit 5) k
$$;

-- Ce que le client voit d'une sortie : ses paiements (jamais le texte du SMS, ni qui dans l'équipe).
create or replace function _sortie_json(s sorties) returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object(
    'reference', s.reference, 'etat', s.etat, 'operateur', s.operateur, 'numero', s.numero,
    'montant', s.montant, 'frais', s.frais, 'montant_xaf', s.montant_xaf,
    'montant_envoye', s.montant_envoye, 'montant_rendu', s.montant_rendu,
    'transferts', (select count(*) from commandes where sortie_id = s.id),
    'cree_le', s.cree_le, 'terminee_le', s.terminee_le,
    'mode', s.mode, 'nom_beneficiaire', s.nom_beneficiaire,
    'pris_le', s.pris_le, 'transaction_id', s.transaction_id,
    'payee_le', coalesce(s.confirmee_le, s.payee_le), 'motif', s.motif,
    'prouvee_le', s.prouvee_le,
    'paiements', (select coalesce(jsonb_agg(jsonb_build_object('transaction_id', p.transaction_id, 'montant', p.montant) order by p.id), '[]'::jsonb)
                    from sortie_paiements p where p.sortie_id = s.id and p.retire_le is null))
$$;

-- ──────────────────────────── 5 · les gestes de l'équipe ───────────────────
-- « J'ai payé » : le paiement est noté, la sortie passe en preuve. Elle se clôt
-- tout de suite si le SMS de la puce est déjà là ; sinon, à son arrivée.
-- « J'ai payé » est un point de non-retour : payee_le reste posé, et la sortie
-- ne se refuse plus (règle de 0014 : payé, ça ne se refuse plus).
drop function if exists admin_payer_sortie(text, text, text);
create or replace function admin_payer_sortie(p_reference text, p_transaction_id text, p_preuve text default null, p_montant numeric default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_s sorties; v_id text := normaliser_transaction_id(p_transaction_id); v_op text; v_reste numeric; v_m numeric;
begin
  perform _exiger_droit('sorties');
  if length(v_id) < 6 then raise exception 'transaction ID invalide' using detail = 'recopiez-le du SMS de l''opérateur'; end if;
  -- l'opérateur ne change jamais : lu sans verrou, pour prendre le verrou de l'ID AVANT celui de la ligne
  select operateur into v_op from sorties where reference = p_reference;
  if not found then raise exception 'sortie inconnue'; end if;
  perform pg_advisory_xact_lock(hashtext('sortie_tx:' || v_op || ':' || v_id));
  v_s := _sortie_a_traiter(p_reference);
  if exists (select 1 from sortie_paiements where sortie_id = v_s.id and transaction_id = v_id and retire_le is null) then
    return _sortie_json(v_s) || jsonb_build_object('deja', true, 'rapprochement', _rapprochement(v_s));   -- double clic, réponse perdue
  end if;
  if v_s.etat not in ('en_attente', 'en_cours', 'en_preuve') then raise exception 'cette sortie est déjà close' using detail = v_s.etat; end if;
  if p_preuve is not null and p_preuve !~ ('^' || v_s.reference || '/[A-Za-z0-9._-]{1,80}$') then
    raise exception 'capture invalide' using detail = 'elle se dépose dans le dossier de la sortie';
  end if;
  if exists (select 1 from sortie_paiements where operateur = v_s.operateur and transaction_id = v_id and retire_le is null)
     or exists (select 1 from sorties where operateur = v_s.operateur and transaction_id = v_id and id <> v_s.id) then
    raise exception 'ce transaction ID prouve déjà une autre sortie';
  end if;
  v_reste := v_s.montant_xaf - coalesce((select sum(montant) from sortie_paiements where sortie_id = v_s.id and retire_le is null), 0);
  if v_reste <= 0 then raise exception 'cette sortie est déjà entièrement payée' using detail = 'corrigez l''ID mal tapé au lieu d''en ajouter un'; end if;
  v_m := coalesce(p_montant, v_reste);
  if v_m <= 0 or v_m <> trunc(v_m) or v_m > v_reste then
    raise exception 'montant du paiement invalide' using detail = format('entre 1 et %s XAF', to_char(v_reste, 'FM999G999G999G999'));
  end if;
  insert into sortie_paiements (sortie_id, operateur, transaction_id, montant, saisi_par) values (v_s.id, v_s.operateur, v_id, v_m, auth.uid());
  update sorties set transaction_id = coalesce(transaction_id, v_id), preuve = coalesce(p_preuve, preuve), payee_par = coalesce(payee_par, auth.uid()),
                     payee_le = coalesce(payee_le, now()), etat = 'en_preuve', pris_par = coalesce(pris_par, auth.uid()), pris_le = coalesce(pris_le, now())
   where id = v_s.id returning * into v_s;
  perform _journaliser('payer_sortie', p_reference, jsonb_build_object('transaction_id', v_id, 'montant', v_m, 'preuve', p_preuve is not null));
  v_s := _tenter_cloture(v_s.id);
  return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s),
           'a_confirmer', v_s.etat = 'en_preuve' and _seuil_atteint(v_s) and v_s.confirmee_par is null);
end $$;

-- Un ID ou un montant mal tapé, remplacé — jamais un paiement déjà prouvé.
create or replace function admin_corriger_paiement(p_reference text, p_ancien text, p_nouveau text, p_note text, p_montant numeric default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_s sorties; v_p sortie_paiements; v_op text; v_note text := trim(coalesce(p_note, ''));
  v_ancien text := normaliser_transaction_id(p_ancien); v_nouveau text := normaliser_transaction_id(p_nouveau);
  v_autres numeric; v_m numeric;
begin
  perform _exiger_droit('sorties');
  if length(v_note) < 3 then raise exception 'une note est exigée' using detail = 'dites ce qui était mal tapé'; end if;
  if length(v_nouveau) < 6 then raise exception 'transaction ID invalide' using detail = 'recopiez-le du SMS de l''opérateur'; end if;
  select operateur into v_op from sorties where reference = p_reference;
  if not found then raise exception 'sortie inconnue'; end if;
  -- les deux verrous, toujours dans le même ordre : pas d'interblocage avec totem_sms_sortant
  perform pg_advisory_xact_lock(hashtext('sortie_tx:' || v_op || ':' || least(v_ancien, v_nouveau)));
  if v_ancien <> v_nouveau then perform pg_advisory_xact_lock(hashtext('sortie_tx:' || v_op || ':' || greatest(v_ancien, v_nouveau))); end if;
  v_s := _sortie_a_traiter(p_reference);
  if v_s.etat <> 'en_preuve' then raise exception 'cette sortie n''attend pas de preuve' using detail = v_s.etat; end if;
  select * into v_p from sortie_paiements where sortie_id = v_s.id and transaction_id = v_ancien and retire_le is null for update;
  if not found then raise exception 'paiement inconnu sur cette sortie'; end if;
  if _preuve_du_paiement(v_p.operateur, v_p.transaction_id, v_p.montant, v_s) ->> 'etat' = 'concorde' then
    raise exception 'ce paiement est prouvé' using detail = 'le SMS de la puce le montre : il ne se corrige pas';
  end if;
  v_autres := coalesce((select sum(montant) from sortie_paiements where sortie_id = v_s.id and retire_le is null and id <> v_p.id), 0);
  v_m := coalesce(p_montant, v_p.montant);
  if v_m <= 0 or v_m <> trunc(v_m) or v_m > v_s.montant_xaf - v_autres then
    raise exception 'montant du paiement invalide' using detail = format('entre 1 et %s XAF', to_char(v_s.montant_xaf - v_autres, 'FM999G999G999G999'));
  end if;
  if v_nouveau <> v_ancien and (exists (select 1 from sortie_paiements where operateur = v_s.operateur and transaction_id = v_nouveau and retire_le is null)
                                or exists (select 1 from sorties where operateur = v_s.operateur and transaction_id = v_nouveau and id <> v_s.id)) then
    raise exception 'ce transaction ID prouve déjà une autre sortie';
  end if;
  update sortie_paiements set retire_le = now(), retire_par = auth.uid(), retire_note = v_note where id = v_p.id;
  insert into sortie_paiements (sortie_id, operateur, transaction_id, montant, saisi_par) values (v_s.id, v_s.operateur, v_nouveau, v_m, auth.uid());
  update sorties set transaction_id = (select transaction_id from sortie_paiements where sortie_id = v_s.id and retire_le is null order by id limit 1)
   where id = v_s.id;
  perform _journaliser('corriger_paiement', p_reference, jsonb_build_object('ancien', v_ancien, 'nouveau', v_nouveau, 'montant_avant', v_p.montant, 'montant', v_m, 'note', v_note));
  v_s := _tenter_cloture(v_s.id);
  return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s));
end $$;

-- « Revérifier » : relire la preuve, et clore si elle est là. La sortie de
-- secours après une clôture qui a échoué (cloture_erreur).
create or replace function admin_verifier_sortie(p_reference text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_s sorties;
begin
  perform _exiger_droit('sorties');
  v_s := _sortie_a_traiter(p_reference);
  if v_s.etat = 'en_preuve' then v_s := _tenter_cloture(v_s.id); end if;
  if v_s.etat = 'envoyee' then perform _journaliser('verifier_sortie', p_reference); end if;
  return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s));
end $$;

-- Au-delà du seuil : une AUTRE personne confirme. Une confirmation ne remplace
-- pas le SMS : en écart, la sortie reste en preuve.
create or replace function admin_confirmer_sortie(p_reference text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_s sorties;
begin
  perform _exiger_droit('sorties');
  v_s := _sortie_a_traiter(p_reference);
  if v_s.etat <> 'en_preuve' then raise exception 'aucun paiement à confirmer' using detail = v_s.etat; end if;
  if not _seuil_atteint(v_s) then raise exception 'cette sortie ne demande pas de seconde personne'; end if;
  if v_s.payee_par = auth.uid() or exists (select 1 from sortie_paiements where sortie_id = v_s.id and saisi_par = auth.uid()) then
    raise exception 'une autre personne confirme' using detail = 'celle qui a payé ne confirme pas son propre paiement';
  end if;
  if v_s.confirmee_par is null then
    update sorties set confirmee_par = auth.uid(), confirmee_le = now() where id = v_s.id;
    perform _journaliser('confirmer_sortie', p_reference);
  end if;
  v_s := _tenter_cloture(v_s.id);
  return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s));
end $$;

-- Le dernier recours : clore SANS le SMS de la puce (un paiement prouvé
-- autrement, par le relevé de l'opérateur). Fermé par défaut ; super admin
-- seulement ; trente minutes après le paiement ; journalisé, et une alerte.
create or replace function admin_forcer_sortie(p_reference text, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_s sorties; v_r jsonb; v_note text := trim(coalesce(p_note, '')); v_reste numeric;
begin
  perform _exiger_droit('sorties');
  perform _exiger_droit('parametres');   -- les deux : le super admin seul
  if not coalesce((parametre('sortie') ->> 'forcage')::boolean, false) then
    raise exception 'le forçage est fermé' using detail = 'Paramètres → Sorties → forcage';
  end if;
  if length(v_note) < 10 then raise exception 'une note est exigée' using detail = 'dites comment le paiement est prouvé'; end if;
  v_s := _sortie_a_traiter(p_reference);
  if v_s.etat <> 'en_preuve' then raise exception 'cette sortie n''attend pas de preuve' using detail = v_s.etat; end if;
  if v_s.payee_le > now() - interval '30 minutes' then
    raise exception 'attendez le SMS de la puce' using detail = 'le forçage s''ouvre 30 minutes après le paiement';
  end if;
  v_reste := v_s.montant_xaf - coalesce((select sum(montant) from sortie_paiements where sortie_id = v_s.id and retire_le is null), 0);
  if v_reste <> 0 then raise exception 'le paiement n''est pas complet' using detail = format('il reste %s XAF', to_char(v_reste, 'FM999G999G999G999')); end if;
  v_r := _rapprochement(v_s);
  if v_r ->> 'etat' = 'concorde' then   -- rien à forcer : la preuve est là
    v_s := _tenter_cloture(v_s.id);
    return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s));
  end if;
  update sorties set forcee_par = auth.uid(), forcee_le = now(), forcee_note = v_note where id = v_s.id;
  perform _journaliser('forcer_sortie', p_reference, jsonb_build_object('note', v_note, 'rapprochement', v_r));
  perform _parite_alerter('sortie_forcee:' || v_s.reference, 'anomalie',
    format('%s clôturée sans le SMS de la puce : %s XAF au %s (%s)', v_s.reference, to_char(v_s.montant_xaf, 'FM999G999G999G999'), v_s.numero, v_note),
    jsonb_build_object('reference', v_s.reference, 'rapprochement', v_r));
  v_s := _tenter_cloture(v_s.id);   -- le seuil vaut toujours : forcer ne remplace que le SMS
  return _sortie_json(v_s) || jsonb_build_object('rapprochement', _rapprochement(v_s));
end $$;

-- Refuser AVANT paiement seulement ; le client est prévenu, aussi par e-mail.
create or replace function admin_refuser_sortie(p_reference text, p_motif text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_s sorties; v_motif text := nullif(trim(coalesce(p_motif, '')), '');
begin
  perform _exiger_droit('sorties');
  if v_motif is null or length(v_motif) < 3 then raise exception 'un motif est exigé' using detail = 'il est montré au client'; end if;
  v_s := _sortie_a_traiter(p_reference);
  -- le paiement d'abord : une sortie en preuve répond « un paiement est enregistré », pas « déjà close »
  if v_s.payee_le is not null or exists (select 1 from sortie_paiements where sortie_id = v_s.id and retire_le is null) then
    raise exception 'un paiement est enregistré' using detail = 'l''argent est parti : la sortie ne se refuse plus';
  end if;
  if v_s.etat not in ('en_attente', 'en_cours') then raise exception 'cette sortie est déjà close' using detail = v_s.etat; end if;
  perform _mouvement(v_s.compte_id, 'XAFe', v_s.montant, -v_s.montant, 'sortie_annulee', 'sorties', v_s.reference);
  update sorties set etat = 'annulee', montant_rendu = montant, motif = v_motif, terminee_le = now()
   where id = v_s.id returning * into v_s;
  perform _notifier(v_s.compte_id, 'Sortie refusée',
    format('%s XAFe sont revenus sur votre compte. %s', to_char(v_s.montant, 'FM999G999G999G999'), v_motif), '/historique/' || v_s.reference);
  if not coalesce(numero_de_demo(v_s.numero), false) then
    perform _envoyer_courriel(v_s.compte_id, 'sortie_refusee',
      jsonb_build_object('reference', v_s.reference, 'montant', v_s.montant, 'motif', v_motif, 'lien', '/historique/' || v_s.reference),
      'sortie_refusee:' || v_s.reference);
  end if;
  perform _journaliser('refuser_sortie', p_reference, jsonb_build_object('motif', v_motif));
  return _sortie_json(v_s);
end $$;

-- La liste de l'équipe : les paiements (actifs et retirés), ce qui reste, la preuve, le forçage.
create or replace function admin_sorties(p_etat text default null, p_n int default 100) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  perform _exiger_droit('voir');
  select coalesce(jsonb_agg(_sortie_json(s) || jsonb_build_object(
           'compte', jsonb_build_object('id', c.id, 'telephone', c.telephone, 'nom', c.nom, 'palier', c.palier),
           'preuve', s.preuve,
           'pris_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = s.pris_par),
           'payee_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = s.payee_par),
           'payee_par_moi', s.payee_par = auth.uid() or exists (select 1 from sortie_paiements p where p.sortie_id = s.id and p.saisi_par = auth.uid()),
           'confirmee_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = s.confirmee_par),
           'en_preuve', s.etat = 'en_preuve',
           'a_confirmer', s.mode = 'manuel' and s.etat = 'en_preuve' and _seuil_atteint(s) and s.confirmee_par is null,
           'reste', s.montant_xaf - coalesce((select sum(p.montant) from sortie_paiements p where p.sortie_id = s.id and p.retire_le is null), 0),
           'paiements_equipe', (select coalesce(jsonb_agg(jsonb_build_object('transaction_id', p.transaction_id, 'montant', p.montant,
                                       'saisi_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = p.saisi_par), 'saisi_le', p.saisi_le,
                                       'retire_le', p.retire_le, 'retire_note', p.retire_note, 'constatee_id', p.constatee_id) order by p.id), '[]'::jsonb)
                                  from sortie_paiements p where p.sortie_id = s.id),
           'cloture_erreur', s.cloture_erreur,
           'forcee_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = s.forcee_par), 'forcee_le', s.forcee_le, 'forcee_note', s.forcee_note,
           'forcage_possible', coalesce((parametre('sortie') ->> 'forcage')::boolean, false) and s.etat = 'en_preuve'
                               and s.payee_le <= now() - interval '30 minutes'
                               and _rapprochement(s) ->> 'etat' is distinct from 'concorde'
                               and s.montant_xaf = coalesce((select sum(p.montant) from sortie_paiements p where p.sortie_id = s.id and p.retire_le is null), 0),
           'candidats', case when s.mode = 'manuel' and s.etat in ('en_attente', 'en_cours', 'en_preuve') then _candidats_de_preuve(s) else '[]'::jsonb end,
           'rapprochement', _rapprochement(s),
           'transferts', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'terminal', k.terminal, 'etat', k.etat, 'montant_xafe', k.montant_xafe,
                                                     'montant_envoye', (k.parametres ->> 'montant')::numeric, 'reprises', k.reprises, 'resultat', k.resultat,
                                                     'reference_operateur', k.reference_operateur, 'reclamee_le', k.reclamee_le) order by k.id), '[]'::jsonb)
                            from commandes k where k.sortie_id = s.id)) order by s.cree_le desc), '[]'::jsonb)
    into r
    from (select * from sorties where (p_etat is null or etat = p_etat) order by cree_le desc limit p_n) s
    join comptes c on c.id = s.compte_id;
  return r;
end $$;

-- Un SMS sortant est « expliqué » s'il porte l'ID d'une sortie OU d'un de ses paiements actifs.
create or replace function _sms_sortant_explique(k sorties_constatees) returns boolean
language sql stable set search_path = public as $$
  select exists (select 1 from sorties s where s.operateur = k.operateur and s.transaction_id = k.transaction_id)
      or exists (select 1 from sortie_paiements p where p.operateur = k.operateur and p.transaction_id = k.transaction_id and p.retire_le is null)
$$;

create or replace function admin_sorties_non_expliquees(p_n int default 100) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  perform _exiger_droit('voir');
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'terminal', k.terminal, 'operateur', k.operateur, 'float_numero', k.float_numero,
                                               'numero', k.numero_beneficiaire, 'montant', k.montant, 'transaction_id', k.transaction_id,
                                               'texte', k.texte, 'emis_le', k.emis_le) order by k.id desc), '[]'::jsonb)
    into r
    from (select * from sorties_constatees k where not _sms_sortant_explique(k) order by k.id desc limit p_n) k;
  return r;
end $$;

create or replace function admin_a_traiter() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _exiger_droit('voir');
  return jsonb_build_object(
    'sorties_manuelles', (select count(*) from sorties where mode = 'manuel' and etat in ('en_attente', 'en_cours')),
    'sorties_en_preuve', (select count(*) from sorties where mode = 'manuel' and etat = 'en_preuve'),
    'sorties_a_confirmer', (select count(*) from sorties s where s.mode = 'manuel' and s.etat = 'en_preuve' and _seuil_atteint(s) and s.confirmee_par is null),
    'sorties_en_ecart', (select count(*) from sorties s where s.mode = 'manuel' and s.etat = 'en_preuve' and _rapprochement(s) ->> 'etat' = 'ecart'),
    'montant_a_payer', (select coalesce(sum(s.montant_xaf - coalesce((select sum(p.montant) from sortie_paiements p where p.sortie_id = s.id and p.retire_le is null), 0)), 0)
                          from sorties s where s.mode = 'manuel' and s.etat in ('en_attente', 'en_cours', 'en_preuve')),
    'sorties_non_expliquees', (select count(*) from sorties_constatees k where not _sms_sortant_explique(k)),
    'parite', (select jsonb_build_object('statut', p.statut, 'ecart', p.ecart, 'couverture', p.couverture, 'fait_le', p.fait_le,
                                         'alertes', (select count(*) from parite_alertes where close_le is null and gravite <> 'attention'))
                 from parite_releves p order by p.fait_le desc limit 1));
end $$;

-- Une sortie en preuve tient encore l'argent du client : le compte ne se ferme pas.
create or replace function _exiger_fermeture_possible(p_compte uuid) returns void
language plpgsql set search_path = public as $$
declare v_reste text;
begin
  select string_agg(format('%s %s', to_char(disponible + bloque, 'FM999G999G999G990D00'), actif), ', ')
    into v_reste from soldes where compte_id = p_compte and disponible + bloque > 0;
  if v_reste is not null then
    raise exception 'il reste de l''argent sur le compte' using detail = format('sortez d''abord : %s', v_reste);
  end if;
  if exists (select 1 from ordres where compte_id = p_compte and etat in ('ouvert', 'partiel'))
     or exists (select 1 from depots where compte_id = p_compte and etat = 'en_attente')
     or exists (select 1 from depot_declarations where compte_id = p_compte and etat = 'attendu')
     or exists (select 1 from sorties where compte_id = p_compte and etat in ('en_attente', 'en_cours', 'en_preuve'))
     or exists (select 1 from retraits_crypto where compte_id = p_compte and etat in ('en_attente', 'en_cours')) then
    raise exception 'une opération est en cours' using detail = 'attendez qu''elle se termine, ou annulez-la';
  end if;
  if exists (select 1 from entrees_retenues r join depots d on d.id = r.depot_id
              where d.compte_id = p_compte and r.etat = 'retenue') then
    raise exception 'un remboursement vous est dû' using detail = 'l''équipe doit d''abord vous rembourser';
  end if;
end $$;

-- ──────────────────────── 6 · le SMS sortant de TOTEM ──────────────────────
-- Même signature : la porte et TOTEM ne changent pas. Le SMS prend le MÊME
-- verrou que l'ID tapé (ils ne se ratent pas : course 12.4) ; il clôt la sortie
-- qui l'attendait. Un lecteur corrigé qui relit l'historique peut COMPLÉTER un
-- numéro manquant, jamais en changer un. Jamais _journaliser ici : pas d'admin.
create or replace function totem_sms_sortant(p_terminal text, p_source_id bigint, p_operateur text, p_float_numero text,
                                             p_numero text, p_montant numeric, p_reference text, p_texte text,
                                             p_emis_le timestamptz)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_k     sorties_constatees;
  v_float floats;
  v_s     sorties;
  v_id    text := nullif(normaliser_transaction_id(p_reference), '');
  v_emp   text := _empreinte_sms(p_texte, p_reference, p_montant);
  v_num   text := nullif(normaliser_numero(p_numero), '');
  v_deja  boolean := false;
begin
  if v_id is not null then perform pg_advisory_xact_lock(hashtext('sortie_tx:' || p_operateur || ':' || v_id)); end if;
  select * into v_k from sorties_constatees where terminal = p_terminal and source_id = p_source_id and empreinte = v_emp;
  if found then
    v_deja := true;
    if v_k.numero_beneficiaire is null and v_num is not null then
      update sorties_constatees set numero_beneficiaire = v_num where id = v_k.id returning * into v_k;
    end if;
  else
    update terminaux set vu_le = now() where id = p_terminal;
    select * into v_float from floats where operateur = p_operateur and numero = normaliser_numero(p_float_numero) and terminal = p_terminal;
    insert into sorties_constatees (terminal, source_id, empreinte, float_id, operateur, float_numero, numero_beneficiaire, montant,
                                    reference_operateur, transaction_id, texte, emis_le, sortie_id)
    values (p_terminal, p_source_id, v_emp, v_float.id, p_operateur, p_float_numero, v_num, p_montant,
            p_reference, v_id, p_texte, p_emis_le, null)
    on conflict (terminal, source_id, empreinte) do nothing
    returning * into v_k;
  end if;
  select s.* into v_s from sorties s
   where v_id is not null and s.operateur = p_operateur
     and (exists (select 1 from sortie_paiements p where p.sortie_id = s.id and p.operateur = p_operateur and p.transaction_id = v_id and p.retire_le is null)
          or s.transaction_id = v_id)
   limit 1;
  if v_s.id is not null and v_s.mode = 'manuel' and v_s.etat = 'en_preuve' then
    begin
      v_s := _tenter_cloture(v_s.id);
    exception when others then   -- le SMS reste noté ; la sortie reste en preuve, et dit pourquoi
      update sorties set cloture_erreur = left(sqlerrm, 300) where id = v_s.id;
      perform _parite_alerter('cloture:' || v_s.reference, 'anomalie',
        format('%s : le SMS de la puce est arrivé mais la clôture a échoué (%s)', v_s.reference, sqlerrm), jsonb_build_object('reference', v_s.reference));
    end;
    select * into v_s from sorties where id = v_s.id;
  end if;
  return jsonb_strip_nulls(jsonb_build_object('resultat', 'constatee', 'id', v_k.id, 'deja', case when v_deja then true end,
    'sortie', v_s.reference, 'rapprochement', case when v_s.id is not null then _rapprochement(v_s) ->> 'etat' end,
    'cloture', case when v_s.etat = 'envoyee' then true end));
end $$;

-- ─────────────────────────────── 7 · les droits ────────────────────────────
revoke all on function _seuil_atteint(sorties), _preuve_du_paiement(text, text, numeric, sorties), _rapprochement(sorties),
  _clore_sortie_manuelle(uuid), _tenter_cloture(uuid), _candidats_de_preuve(sorties), _sortie_json(sorties), _sms_sortant_explique(sorties_constatees),
  _exiger_fermeture_possible(uuid), _verifier_parametre(text, jsonb),
  admin_payer_sortie(text, text, text, numeric), admin_corriger_paiement(text, text, text, text, numeric), admin_verifier_sortie(text),
  admin_forcer_sortie(text, text), admin_confirmer_sortie(text), admin_refuser_sortie(text, text), admin_sorties(text, int),
  admin_a_traiter(), admin_sorties_non_expliquees(int),
  totem_sms_sortant(text, bigint, text, text, text, numeric, text, text, timestamptz) from public, anon, authenticated;
grant execute on function admin_payer_sortie(text, text, text, numeric), admin_corriger_paiement(text, text, text, text, numeric),
  admin_verifier_sortie(text), admin_forcer_sortie(text, text), admin_confirmer_sortie(text), admin_refuser_sortie(text, text),
  admin_sorties(text, int), admin_a_traiter(), admin_sorties_non_expliquees(int) to authenticated;   -- les gardes sont dedans (_exiger_droit)
grant execute on function totem_sms_sortant(text, bigint, text, text, text, numeric, text, text, timestamptz) to service_role;
$sql$;
    raise notice '0038_sortie_manuelle_prouvee.sql : appliquée';
  end if;
end $consolide$;

-- ─── 0039_continuite_des_soldes.sql (md5 94ea82016e75a9f02b9215ee993e1291) ───
-- déjà en place si : rejouable telle quelle
do $consolide$
begin
  if false then
    raise notice '0039_continuite_des_soldes.sql : déjà en place, rien à faire';
  else
    execute $sql$
-- ╔════════════════════════════════════════════════════════════════════════╗
-- ║  Glisil · 0039 · la continuité des soldes : la garde des faux SMS       ║
-- ║                                                                        ║
-- ║  N'importe qui peut écrire à une puce. Un faux « Vous avez reçu        ║
-- ║  7 500 000 XAF … ID … », envoyé sous le nom de l'opérateur et suivi    ║
-- ║  de la même déclaration chez Glisil, était crédité comme un vrai       ║
-- ║  paiement. Le SMS de l'opérateur porte pourtant de quoi le démasquer : ║
-- ║  le NOUVEAU SOLDE du float. Un vrai encaissement le fait monter de son ║
-- ║  montant, au franc près ; un faussaire ne connaît pas le solde.        ║
-- ║                                                                        ║
-- ║  LA GARDE. Avant de créditer : dernier solde SÛR du float + montant   ║
-- ║  (+ commission, − frais, quand TOTEM les annonce) = nouveau solde      ║
-- ║  annoncé. Sinon — incohérent, absent, ou aucun solde sûr encore — le   ║
-- ║  SMS est RETENU, bloqué : ni crédité, ni rapproché, ni remboursé tant  ║
-- ║  que l'équipe ne l'a pas libéré (ou qu'un solde sûr ne l'explique).    ║
-- ║                                                                        ║
-- ║  UN SOLDE SÛR : une consultation USSD étiquetée par le boîtier, un     ║
-- ║  relevé déposé par l'équipe, ou un SMS déjà vérifié par la chaîne (ou  ║
-- ║  libéré par une personne qui a confirmé son solde). Un solde lu dans   ║
-- ║  un SMS seul ne sert JAMAIS d'appui : un premier faux SMS n'empoisonne ║
-- ║  pas la chaîne.                                                        ║
-- ║                                                                        ║
-- ║  Le désordre se répare seul : à chaque nouveau solde sûr, les lignes   ║
-- ║  qui suivent sont réexaminées dans l'ordre des heures. Les sorties     ║
-- ║  prolongent la chaîne, sans jamais rien bloquer. La démo est exemptée  ║
-- ║  par réglage (continuite.demo = eteinte).                              ║
-- ║                                                                        ║
-- ║  ORDRE DES VERROUS : 'sms:' (terminal, ligne) → 'float:' → 'tx:'       ║
-- ║  (opérateur, ID) → lignes. declarer_transaction ne prend jamais        ║
-- ║  'float:' : il ne touche que des retenues non bloquées, et une retenue ║
-- ║  pour son solde est bloquée.                                           ║
-- ║                                                                        ║
-- ║  La page publique arrondit les floats au million inférieur : la garde ║
-- ║  ne vaut que tant que le solde exact reste secret.                     ║
-- ╚════════════════════════════════════════════════════════════════════════╝

-- ─────────────────────────────── 0 · le réglage ────────────────────────────
insert into parametres (cle, valeur) values ('continuite', '{"mode": "exiger", "demo": "eteinte"}') on conflict (cle) do nothing;
create or replace function _verifier_parametre(p_cle text, v jsonb) returns void
language plpgsql set search_path = public, extensions, pg_temp as $$
declare k text; p jsonb; ok boolean;
begin
  if jsonb_typeof(v) <> 'object' then raise exception 'paramètre invalide' using detail = 'un objet JSON est attendu'; end if;
  ok := case p_cle
    when 'frais' then _nombre_entre(v -> 'placeur', 0, 0.05) and _nombre_entre(v -> 'preneur', 0, 0.05) and _nombre_entre(v -> 'sortie', 0, 0.05)
    when 'marche' then v ->> 'paire' = 'USDT/XAFe' and _nombre_entre(v -> 'pas_prix', 0.01, 100) and _nombre_entre(v -> 'quantite_min', 0.01, 1000000)
                       and jsonb_typeof(v -> 'ouvert') = 'boolean'
                       -- les règles du marché (0017) : chacune facultative, chacune bornée
                       -- vide : sans plafond (0027)
                       and (not (v ? 'quantite_max') or jsonb_typeof(v -> 'quantite_max') = 'null' or _nombre_entre(v -> 'quantite_max', (v ->> 'quantite_min')::numeric, 1e12))
                       and (not (v ? 'marche_quantite_max') or jsonb_typeof(v -> 'marche_quantite_max') = 'null' or _nombre_entre(v -> 'marche_quantite_max', (v ->> 'quantite_min')::numeric, 1e12))
                       and (not (v ? 'montant_min') or _nombre_entre(v -> 'montant_min', 0, 1e9))
                       and (not (v ? 'ordres_ouverts_max') or _nombre_entre(v -> 'ordres_ouverts_max', 1, 10000, true))
                       and (not (v ? 'bande_execution') or _nombre_entre(v -> 'bande_execution', 0.001, 0.5))
                       and (not (v ? 'bande_achat') or (jsonb_typeof(v -> 'bande_achat') = 'array' and jsonb_array_length(v -> 'bande_achat') = 2
                            and _nombre_entre(v -> 'bande_achat' -> 0, 0.01, 1) and _nombre_entre(v -> 'bande_achat' -> 1, 1, 100)))
                       and (not (v ? 'bande_vente') or (jsonb_typeof(v -> 'bande_vente') = 'array' and jsonb_array_length(v -> 'bande_vente') = 2
                            and _nombre_entre(v -> 'bande_vente' -> 0, 0.01, 1) and _nombre_entre(v -> 'bande_vente' -> 1, 1, 100)))
                       and (not (v ? 'prix_reference') or jsonb_typeof(v -> 'prix_reference') = 'null' or _nombre_entre(v -> 'prix_reference', 0.01, 1e9))
    when 'depot' then _nombre_entre(v -> 'validite_minutes', 5, 1440, true) and _nombre_entre(v -> 'grace_minutes', 0, 10080, true)
                      and (not (v ? 'declaration_complete') or jsonb_typeof(v -> 'declaration_complete') = 'boolean')
    when 'sortie' then _nombre_entre(v -> 'reprises_max', 1, 10, true)
                       and (not (v ? 'ouvertes') or jsonb_typeof(v -> 'ouvertes') = 'boolean')
                       and (not (v ? 'mode') or v ->> 'mode' in ('totem', 'manuel'))
                       and (not (v ? 'seuil_deux_personnes') or jsonb_typeof(v -> 'seuil_deux_personnes') = 'null'
                            or _nombre_entre(v -> 'seuil_deux_personnes', 1, 1e12))
                       -- 0038 : le forçage (clore sans le SMS de la puce), fermé par défaut
                       and (not (v ? 'forcage') or jsonb_typeof(v -> 'forcage') = 'boolean')
    when 'rapide' then _nombre_entre(v -> 'marge', 0, 0.2) and _nombre_entre(v -> 'validite_secondes', 5, 120, true)
                       and jsonb_typeof(v -> 'ouvert') = 'boolean'
    when 'code_secret' then _nombre_entre(v -> 'essais', 1, 10, true) and _nombre_entre(v -> 'verrou_minutes', 1, 1440, true)
                       and _nombre_entre(v -> 'longueur_min', 4, 6, true) and _nombre_entre(v -> 'longueur_max', 4, 8, true)
                       and (v ->> 'longueur_min')::int <= (v ->> 'longueur_max')::int
    when 'crypto' then _nombre_entre(v -> 'frais' -> 'USDT', 0, 1000) and _nombre_entre(v -> 'frais' -> 'XAFe', 0, 1000000)
                       and _nombre_entre(v -> 'confirmations' -> 'bep20', 1, 1000, true) and _nombre_entre(v -> 'confirmations' -> 'trc20', 1, 1000, true)
                       and jsonb_typeof(v -> 'retraits_ouverts') = 'boolean'
                       and (not (v ? 'depots_ouverts') or jsonb_typeof(v -> 'depots_ouverts') = 'boolean')
    when 'paliers' then (select bool_and(x) from (values (v ? '0'), (v ? '1'), (v ? '2')) t(x))
    when 'conditions' then coalesce(v ->> 'version', '') ~ '^\d{4}-\d{2}-\d{2}$'
    when 'support' then coalesce(v ->> 'email', '') ~ '^[^@\s]+@[^@\s]+\.[a-z]{2,}$'
                        and (jsonb_typeof(v -> 'whatsapp') = 'null' or coalesce(v ->> 'whatsapp', '') ~ '^\+[1-9][0-9]{7,14}$')
    when 'robots' then jsonb_typeof(v -> 'actif') = 'boolean'
                       and jsonb_typeof(v -> 'teneur') = 'object' and jsonb_typeof(v -> 'traders') = 'object' and jsonb_typeof(v -> 'derive') = 'object'
                       and _nombre_entre(v -> 'teneur' -> 'ecart', 0.0005, 0.05) and _nombre_entre(v -> 'teneur' -> 'niveaux', 1, 20, true)
                       and _nombre_entre(v -> 'teneur' -> 'pas', 0, 0.02) and _nombre_entre(v -> 'teneur' -> 'taille_usdt', 10, 100000)
                       and _nombre_entre(v -> 'teneur' -> 'tolerance', 0, 0.01) and _nombre_entre(v -> 'teneur' -> 'inventaire', 0, 0.05)
                       and _nombre_entre(v -> 'traders' -> 'probabilite', 0, 1) and _nombre_entre(v -> 'traders' -> 'taille_min', 10, 100000)
                       and _nombre_entre(v -> 'traders' -> 'taille_max', 10, 100000)
                       and (v -> 'traders' ->> 'taille_min')::numeric <= (v -> 'traders' ->> 'taille_max')::numeric
                       and _nombre_entre(v -> 'traders' -> 'part_preneur', 0, 1) and _nombre_entre(v -> 'traders' -> 'duree_minutes', 1, 1440, true)
                       and _nombre_entre(v -> 'traders' -> 'ordres_max', 0, 50, true)
                       and _nombre_entre(v -> 'derive' -> 'volatilite', 0, 0.01) and _nombre_entre(v -> 'derive' -> 'rappel', 0, 1)
                       and _nombre_entre(v -> 'derive' -> 'borne', 0, 0.1) and _nombre_entre(v -> 'derive' -> 'choc_probabilite', 0, 0.1)
                       and _nombre_entre(v -> 'derive' -> 'choc_max', 0, 0.05)
    when 'cours' then jsonb_typeof(v -> 'actif') = 'boolean' and _nombre_entre(v -> 'prime', -0.2, 0.2) and _nombre_entre(v -> 'saut_max', 0.005, 0.5)
    when 'beta' then jsonb_typeof(v -> 'actif') = 'boolean' and jsonb_typeof(v -> 'depots_reels') = 'boolean'
                     and (jsonb_typeof(v -> 'message') = 'null' or length(coalesce(v ->> 'message', '')) between 1 and 300)
                     and jsonb_typeof(v -> 'dotation') = 'object'
                     and _nombre_entre(v -> 'dotation' -> 'XAFe', 0, 100000000, true) and _nombre_entre(v -> 'dotation' -> 'USDT', 0, 1000000)
    when 'numeros' then jsonb_typeof(v -> 'verification_sms') = 'boolean' and _nombre_entre(v -> 'delai_heures', 0, 168, true)
    when 'parite' then (jsonb_typeof(v -> 'alerte_numero') = 'null' or coalesce(v ->> 'alerte_numero', '') ~ '^\+?[0-9 ]{9,16}$')
                       and coalesce(v ->> 'alerte_operateur', '') in ('mtn', 'om')
                       and _nombre_entre(v -> 'fraicheur_heures', 1, 720, true) and _nombre_entre(v -> 'delai_minutes', 5, 1440, true)
                       and jsonb_typeof(v -> 'publier_floats') = 'boolean'
    -- 0039 : la garde des faux SMS, par la continuité des soldes
    when 'continuite' then coalesce(v ->> 'mode', '') in ('exiger', 'surveiller', 'eteinte') and coalesce(v ->> 'demo', '') in ('exiger', 'surveiller', 'eteinte')
    else false end;
  if p_cle = 'paliers' and ok then
    foreach k in array array['0', '1', '2'] loop
      p := v -> k;
      if jsonb_typeof(p) = 'null' then continue; end if;
      if not (jsonb_typeof(p) = 'object' and _nombre_entre(p -> 'entree_jour', 0, 1e12, true) and _nombre_entre(p -> 'sortie_jour', 0, 1e12, true)) then
        ok := false;
      end if;
    end loop;
  end if;
  if not coalesce(ok, false) then
    raise exception 'paramètre invalide' using detail = format('« %s » : une clé manque, ou une valeur sort de ses bornes', p_cle);
  end if;
end $$;

-- ──────────────────────────────── 1 · les tables ───────────────────────────
alter table soldes_floats add column if not exists empreinte  text not null default '';   -- _empreinte_sms : un source_id réutilisé après réinstallation ne se confond pas
alter table soldes_floats add column if not exists fiable     boolean not null default false;  -- vrai : sert d'appui (SMS vérifié par la chaîne, ou libéré par une personne)
alter table soldes_floats add column if not exists mouvement  numeric(20,2);   -- + montant (entrée), − montant (sortie) ; null pour un solde seul
alter table soldes_floats add column if not exists frais      numeric(20,2);
alter table soldes_floats add column if not exists commission numeric(20,2);
alter table soldes_floats add column if not exists continuite text;
alter table soldes_floats add column if not exists retenue_id bigint references entrees_retenues(id);
alter table soldes_floats add column if not exists constatee_id bigint references sorties_constatees(id);
alter table soldes_floats drop constraint if exists soldes_floats_continuite_check;
alter table soldes_floats add constraint soldes_floats_continuite_check
  check (continuite in ('verifiee', 'incoherente', 'absente', 'sans_ancre', 'ignoree', 'liberee', 'rejetee'));
drop index if exists soldes_floats_un_sms;
create unique index soldes_floats_un_sms on soldes_floats (terminal, source_id, empreinte) where source = 'sms' and source_id is not null;
create index if not exists soldes_floats_a_reexaminer on soldes_floats (float_id, annonce_le, id) where source = 'sms' and not fiable and mouvement is not null;
create index if not exists soldes_floats_de_la_retenue on soldes_floats (retenue_id) where retenue_id is not null;

alter table entrees_retenues add column if not exists solde_apres   numeric(20,2);
alter table entrees_retenues add column if not exists solde_attendu numeric(20,2);
alter table entrees_retenues add column if not exists continuite    text;
alter table entrees_retenues add column if not exists ancre_id      bigint references soldes_floats(id);
alter table entrees_retenues add column if not exists liberee_par   uuid;
alter table entrees_retenues add column if not exists liberee_le    timestamptz;
alter table entrees_retenues add column if not exists note_equipe   text;
alter table entrees_retenues drop constraint if exists entrees_retenues_continuite_check;
alter table entrees_retenues add constraint entrees_retenues_continuite_check
  check (continuite in ('verifiee', 'incoherente', 'absente', 'sans_ancre', 'ignoree', 'liberee', 'rejetee'));
alter table entrees_retenues drop constraint if exists entrees_retenues_etat_check;
alter table entrees_retenues add constraint entrees_retenues_etat_check check (etat in ('retenue', 'rapprochee', 'remboursee', 'rejetee'));

alter table sorties_constatees add column if not exists solde_apres numeric(20,2);
alter table sorties_constatees add column if not exists continuite  text;

-- ───────────────────────────── 2 · la règle ────────────────────────────────
create or replace function _mode_continuite(p_terminal text) returns text
language sql stable set search_path = public as $$
  select case when coalesce((select demo from terminaux where id = p_terminal), false)
              then coalesce(parametre('continuite') ->> 'demo', 'eteinte')
              else coalesce(parametre('continuite') ->> 'mode', 'exiger') end
$$;

create or replace function _motif_continuite(p_etat text) returns text
language sql immutable set search_path = public as $$
  select case p_etat when 'incoherente' then 'solde incohérent : à vérifier'
                     when 'absente' then 'solde non annoncé : à vérifier'
                     when 'sans_ancre' then 'premier solde du float inconnu : à vérifier' end
$$;

-- Retenue POUR SON SOLDE (et non pour une autre raison, sur laquelle la continuité
-- n'est qu'un renseignement, en « surveiller ») : bloquée, avec le motif de la garde.
create or replace function _retenue_pour_le_solde(r entrees_retenues) returns boolean
language sql immutable set search_path = public as $$
  select r.etat = 'retenue' and r.bloquee and r.continuite in ('incoherente', 'absente', 'sans_ancre')
     and r.motif is not distinct from _motif_continuite(r.continuite)
$$;

-- LE JUGEMENT d'un mouvement : le solde annoncé suit-il le dernier solde sûr ?
-- VOLATILE : pendant le réexamen, elle doit voir ce que la transaction vient d'écrire.
create or replace function _continuite(p_float floats, p_sens int, p_montant numeric, p_solde numeric, p_frais numeric,
                                       p_commission numeric, p_quand timestamptz, p_exclure bigint default null) returns jsonb
language plpgsql volatile set search_path = public as $$
declare
  v_mode text := _mode_continuite(p_float.terminal);
  a1 soldes_floats; a2 soldes_floats; a soldes_floats; d numeric; i int;
  v_ecarts numeric[];
begin
  if v_mode = 'eteinte' then return jsonb_build_object('etat', 'ignoree', 'mode', v_mode); end if;
  if p_solde is null or p_solde < 0 or p_montant is null or p_montant <= 0 then
    return jsonb_build_object('etat', 'absente', 'mode', v_mode);
  end if;
  -- deux appuis : strictement avant, et jusqu'à cette heure incluse (deux SMS à la même seconde)
  select * into a1 from soldes_floats
   where float_id = p_float.id and (source in ('ussd', 'releve') or fiable) and annonce_le < p_quand and id <> coalesce(p_exclure, 0)
   order by annonce_le desc, id desc limit 1;
  select * into a2 from soldes_floats
   where float_id = p_float.id and (source in ('ussd', 'releve') or fiable) and annonce_le <= p_quand and id <> coalesce(p_exclure, 0)
   order by annonce_le desc, id desc limit 1;
  if a1.id is null and a2.id is null then return jsonb_build_object('etat', 'sans_ancre', 'mode', v_mode); end if;
  -- les écarts qu'un VRAI mouvement explique ; pas de tolérance au centime (numeric(20,2) compare exactement)
  v_ecarts := array[p_sens * p_montant];
  if p_sens = 1 and coalesce(p_commission, 0) > 0 then v_ecarts := v_ecarts || (p_montant + p_commission); end if;
  if p_sens = -1 and coalesce(p_commission, 0) > 0 then v_ecarts := v_ecarts || (-p_montant + p_commission); end if;   -- un dépôt d'agent MTN : « Commission ajoutée »
  if coalesce(p_frais, 0) > 0 then v_ecarts := v_ecarts || (p_sens * p_montant - p_frais); end if;
  for i in 1 .. 2 loop
    if i = 1 then a := a2; else a := a1; end if;
    continue when a.id is null;
    foreach d in array v_ecarts loop
      if round(a.solde + d, 2) = round(p_solde, 2) then
        return jsonb_build_object('etat', 'verifiee', 'mode', v_mode, 'ancre_id', a.id, 'ancre_solde', a.solde, 'ancre_le', a.annonce_le,
                                  'attendu', a.solde + p_sens * p_montant);
      end if;
    end loop;
  end loop;
  if a1.id is not null then a := a1; else a := a2; end if;
  return jsonb_build_object('etat', 'incoherente', 'mode', v_mode, 'ancre_id', a.id, 'ancre_solde', a.solde, 'ancre_le', a.annonce_le,
                            'attendu', a.solde + p_sens * p_montant);
end $$;

-- Le crédit d'une retenue qui vient d'être vérifiée ou libérée, dans l'ordre de
-- declarer_transaction : le verrou de l'ID d'abord, la ligne ensuite.
create or replace function _reprendre_retenue(p_id bigint, p_continuite text) returns jsonb
language plpgsql set search_path = public as $$
declare v_r entrees_retenues; v_a jsonb; v_x depot_declarations; v_op text; v_tx text;
begin
  select operateur, transaction_id into v_op, v_tx from entrees_retenues where id = p_id;
  if length(coalesce(v_tx, '')) >= 6 then perform pg_advisory_xact_lock(hashtext('tx:' || v_op || ':' || v_tx)); end if;
  select * into v_r from entrees_retenues where id = p_id for update;
  if not found then return jsonb_build_object('etat', 'inconnue'); end if;
  if v_r.etat <> 'retenue' then return jsonb_build_object('etat', v_r.etat); end if;
  update entrees_retenues set continuite = p_continuite, bloquee = false, motif = null where id = p_id returning * into v_r;
  if coalesce(v_r.montant, 0) > 0 and length(coalesce(v_r.transaction_id, '')) >= 6
     and not exists (select 1 from depot_paiements where terminal = v_r.terminal and source_id = v_r.source_id and empreinte = v_r.empreinte) then
    v_a := _apparier(v_r.operateur, v_r.transaction_id, v_r.numero_payeur, v_r.emis_le, v_r.montant,
                     coalesce((select demo from terminaux where id = v_r.terminal), false));
    if v_a ? 'id' then
      v_x := _crediter_declaration((v_a ->> 'id')::uuid, v_r.terminal, v_r.source_id, v_r.montant, v_r.numero_payeur,
                                   v_r.reference_operateur, v_r.texte, v_r.emis_le, v_r.id);
      return jsonb_build_object('credite', v_x.etat = 'credite', 'reference', (select reference from depots where id = v_x.depot_id));
    end if;
    -- sans déclaration, la retenue n'est plus bloquée : la déclaration du client la reprendra
    update entrees_retenues set motif = v_a ->> 'motif', bloquee = coalesce((v_a ->> 'bloquee')::boolean, false),
                                depot_id = coalesce((v_a ->> 'depot_id')::uuid, depot_id)
     where id = p_id;
  end if;
  return jsonb_build_object('credite', false);
end $$;

-- Le réexamen : un nouveau solde sûr peut expliquer les lignes qui suivent.
-- On ne s'arrête pas à la première qui ne passe pas : une plus tardive peut
-- s'appuyer sur un autre point d'appui. Une ligne rejetée ne revient jamais.
create or replace function _reexaminer_continuite(p_float int, p_depuis timestamptz) returns int
language plpgsql set search_path = public as $$
declare v_id bigint; v_s soldes_floats; v_f floats; v_c jsonb; n int := 0;
begin
  select * into v_f from floats where id = p_float;
  for v_id in select s.id from soldes_floats s
               where s.float_id = p_float and s.source = 'sms' and not s.fiable and s.mouvement is not null
                 and s.continuite in ('incoherente', 'sans_ancre') and s.annonce_le >= p_depuis
                 and (s.retenue_id is null or exists (select 1 from entrees_retenues r where r.id = s.retenue_id and r.etat = 'retenue'))
               order by s.annonce_le, s.id limit 500 loop
    select * into v_s from soldes_floats where id = v_id for update;
    continue when v_s.fiable;
    v_c := _continuite(v_f, sign(v_s.mouvement)::int, abs(v_s.mouvement), v_s.solde, v_s.frais, v_s.commission, v_s.annonce_le, v_s.id);
    continue when v_c ->> 'etat' <> 'verifiee';
    update soldes_floats set fiable = true, continuite = 'verifiee' where id = v_id;
    if v_s.retenue_id is not null then
      update entrees_retenues set continuite = 'verifiee', solde_attendu = (v_c ->> 'attendu')::numeric, ancre_id = (v_c ->> 'ancre_id')::bigint
       where id = v_s.retenue_id;
      perform _reprendre_retenue(v_s.retenue_id, 'verifiee');
    end if;
    if v_s.constatee_id is not null then update sorties_constatees set continuite = 'verifiee' where id = v_s.constatee_id; end if;
    n := n + 1;
  end loop;
  return n;
end $$;

-- Le dernier solde SÛR du float : un faux SMS ne déplace plus la colonne « floats » de la parité.
create or replace function _solde_float(p_float int) returns soldes_floats
language sql stable set search_path = public as $$
  select * from soldes_floats where float_id = p_float and (source in ('ussd', 'releve') or fiable)
   order by annonce_le desc, id desc limit 1
$$;

-- ─────────────────────── 3 · le SMS d'argent reçu ──────────────────────────
-- Le solde décide maintenant de l'argent : il ne se note plus APRÈS lui.
drop function if exists totem_sms_recu(text, bigint, text, text, text, numeric, text, text, timestamptz);
create or replace function totem_sms_recu(p_terminal text, p_source_id bigint, p_operateur text, p_float_numero text, p_numero_payeur text,
                               p_montant numeric, p_reference text, p_texte text, p_emis_le timestamptz,
                               p_solde_apres numeric default null, p_frais numeric default null, p_commission numeric default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_float floats;
  v_d     depots;
  v_p     depot_paiements;
  v_r     entrees_retenues;
  v_x     depot_declarations;
  v_a     jsonb := '{}'::jsonb;
  v_c     jsonb;
  v_etat  text;
  v_num   text := nullif(normaliser_numero(p_numero_payeur), '');
  v_id    text := normaliser_transaction_id(p_reference);
  v_emp   text := _empreinte_sms(p_texte, p_reference, p_montant);
  v_reutilise boolean;
  v_quand timestamptz := least(coalesce(p_emis_le, now()), now());
  v_solde numeric := case when p_solde_apres >= 0 and p_solde_apres < 1e13 then round(p_solde_apres, 2) end;
  v_sid   bigint;
  v_rep   jsonb;
begin
  perform pg_advisory_xact_lock(hashtext('sms:' || p_terminal || ':' || p_source_id::text));
  select * into v_p from depot_paiements where terminal = p_terminal and source_id = p_source_id and empreinte = v_emp;
  if found then
    select * into v_d from depots where id = v_p.depot_id;
    return jsonb_build_object('resultat', 'credite', 'reference', v_d.reference, 'etat', v_d.etat, 'deja', true);
  end if;
  select * into v_r from entrees_retenues where terminal = p_terminal and source_id = p_source_id and empreinte = v_emp;
  if found then return jsonb_strip_nulls(jsonb_build_object('resultat', 'retenue', 'id', v_r.id, 'deja', true, 'continuite', v_r.continuite)); end if;
  v_reutilise := exists (select 1 from depot_paiements where terminal = p_terminal and source_id = p_source_id)
              or exists (select 1 from entrees_retenues where terminal = p_terminal and source_id = p_source_id);

  update terminaux set vu_le = now() where id = p_terminal;
  select * into v_float from floats
   where operateur = p_operateur and numero = normaliser_numero(p_float_numero) and terminal = p_terminal;
  if not found then
    insert into entrees_retenues (terminal, source_id, operateur, float_numero, numero_payeur, montant,
                                  reference_operateur, transaction_id, texte, emis_le, motif, bloquee, empreinte, solde_apres)
    values (p_terminal, p_source_id, p_operateur, p_float_numero, v_num, p_montant, p_reference, v_id, p_texte, p_emis_le,
            'ce numéro n''est pas un float de ce terminal : l''équipe vérifie', true, v_emp, v_solde)
    returning * into v_r;
    return jsonb_build_object('resultat', 'retenue', 'id', v_r.id, 'motif', v_r.motif);
  end if;

  -- LA GARDE : le solde annoncé suit-il le dernier solde sûr ?
  perform pg_advisory_xact_lock(hashtext('float:' || v_float.id));
  v_c := _continuite(v_float, 1, p_montant, v_solde, nullif(p_frais, 0), nullif(p_commission, 0), v_quand);
  v_etat := v_c ->> 'etat';
  if v_solde is not null then
    insert into soldes_floats (float_id, solde, annonce_le, source, terminal, source_id, empreinte, fiable, mouvement, frais, commission, continuite)
    values (v_float.id, v_solde, v_quand, 'sms', p_terminal, p_source_id, v_emp, v_etat in ('verifiee', 'ignoree'),
            p_montant, p_frais, p_commission, v_etat)
    on conflict (terminal, source_id, empreinte) where source = 'sms' and source_id is not null do nothing
    returning id into v_sid;
  end if;

  if v_c ->> 'mode' = 'exiger' and v_etat in ('incoherente', 'absente', 'sans_ancre') then
    -- retenu, BLOQUÉ : l'appariement ne tourne pas, aucune déclaration n'est touchée ni refusée
    insert into entrees_retenues (terminal, source_id, float_id, operateur, float_numero, numero_payeur, montant,
                                  reference_operateur, transaction_id, texte, emis_le, motif, bloquee, empreinte,
                                  solde_apres, solde_attendu, continuite, ancre_id)
    values (p_terminal, p_source_id, v_float.id, p_operateur, p_float_numero, v_num, p_montant, p_reference, v_id, p_texte, p_emis_le,
            _motif_continuite(v_etat), true, v_emp, v_solde, (v_c ->> 'attendu')::numeric, v_etat, (v_c ->> 'ancre_id')::bigint)
    returning * into v_r;
    if v_sid is not null then update soldes_floats set retenue_id = v_r.id where id = v_sid; end if;
    -- le client qui attend ce paiement sait qu'il est arrivé, et qu'il est vérifié
    if length(v_id) >= 6 and coalesce(p_montant, 0) > 0 then
      perform _notifier(x.compte_id, 'Paiement en vérification',
                        format('Votre paiement de %s XAF est arrivé : l''équipe le vérifie avant de créditer vos XAFe.', to_char(p_montant, 'FM999G999G999G999')),
                        '/historique/' || d.reference)
         from depot_declarations x join depots d on d.id = x.depot_id join floats f on f.id = d.float_id join terminaux t on t.id = f.terminal
        where x.operateur = p_operateur and x.transaction_id = v_id and x.etat = 'attendu'
          and coalesce(t.demo, false) = coalesce((select demo from terminaux where id = p_terminal), false);
    end if;
    return jsonb_strip_nulls(jsonb_build_object('resultat', 'retenue', 'id', v_r.id, 'motif', v_r.motif, 'continuite', v_etat,
                                                'source_id_reutilise', case when v_reutilise then true end));
  end if;

  -- vérifié, ignoré (démo), ou surveillé : l'argent suit son chemin d'avant
  if coalesce(p_montant, 0) > 0 and length(v_id) >= 6 then
    perform pg_advisory_xact_lock(hashtext('tx:' || p_operateur || ':' || v_id));
    v_a := _apparier(p_operateur, v_id, v_num, p_emis_le, p_montant,
                     coalesce((select demo from terminaux where id = p_terminal), false));
    if v_a ? 'id' then
      v_x := _crediter_declaration((v_a ->> 'id')::uuid, p_terminal, p_source_id, p_montant, v_num, p_reference, p_texte, p_emis_le, null);
      select * into v_d from depots where id = v_x.depot_id;
      if v_x.etat = 'credite' then
        v_rep := jsonb_strip_nulls(jsonb_build_object('resultat', 'credite', 'reference', v_d.reference, 'etat', v_d.etat,
                                                      'montant_recu', v_d.montant_recu, 'continuite', v_etat,
                                                      'source_id_reutilise', case when v_reutilise then true end));
      else
        v_a := jsonb_build_object('motif', v_x.motif, 'bloquee', true, 'depot_id', v_d.id);
      end if;
    end if;
  end if;

  if v_rep is null then
    insert into entrees_retenues (terminal, source_id, float_id, operateur, float_numero, numero_payeur, montant,
                                  reference_operateur, transaction_id, texte, emis_le, depot_id, motif, bloquee, empreinte,
                                  solde_apres, solde_attendu, continuite, ancre_id)
    values (p_terminal, p_source_id, v_float.id, p_operateur, p_float_numero, v_num, p_montant, p_reference, v_id, p_texte, p_emis_le,
            (v_a ->> 'depot_id')::uuid, v_a ->> 'motif', coalesce((v_a ->> 'bloquee')::boolean, false), v_emp,
            v_solde, (v_c ->> 'attendu')::numeric, v_etat, (v_c ->> 'ancre_id')::bigint)
    returning * into v_r;
    if v_sid is not null then update soldes_floats set retenue_id = v_r.id where id = v_sid; end if;
    v_rep := jsonb_strip_nulls(jsonb_build_object('resultat', 'retenue', 'id', v_r.id, 'motif', v_r.motif, 'continuite', v_etat,
                                                  'source_id_reutilise', case when v_reutilise then true end));
  end if;

  if v_etat = 'verifiee' and v_sid is not null then
    -- le message complet ferme sa moitié tronquée (même ligne du journal de TOTEM, retenue sans solde)
    if v_reutilise then
      update entrees_retenues set etat = 'rejetee', continuite = 'rejetee', motif = 'remplacé par le message complet'
       where terminal = p_terminal and source_id = p_source_id and etat = 'retenue' and continuite = 'absente'
         and empreinte <> v_emp and length(coalesce(texte, '')) >= 20 and position(texte in coalesce(p_texte, '')) > 0;
    end if;
    perform _reexaminer_continuite(v_float.id, v_quand);
  end if;
  return v_rep;
end $$;

-- ─────────────────────── 4 · le SMS sortant ────────────────────────────────
-- Il prolonge la chaîne, il ne bloque jamais rien.
drop function if exists totem_sms_sortant(text, bigint, text, text, text, numeric, text, text, timestamptz);
create or replace function totem_sms_sortant(p_terminal text, p_source_id bigint, p_operateur text, p_float_numero text,
                                  p_numero text, p_montant numeric, p_reference text, p_texte text,
                                  p_emis_le timestamptz, p_solde_apres numeric default null, p_frais numeric default null,
                                  p_commission numeric default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_k     sorties_constatees;
  v_float floats;
  v_s     sorties;
  v_id    text := nullif(normaliser_transaction_id(p_reference), '');
  v_emp   text := _empreinte_sms(p_texte, p_reference, p_montant);
  v_num   text := nullif(normaliser_numero(p_numero), '');
  v_deja  boolean := false;
  v_quand timestamptz := least(coalesce(p_emis_le, now()), now());
  v_solde numeric := case when p_solde_apres >= 0 and p_solde_apres < 1e13 then round(p_solde_apres, 2) end;
  v_c     jsonb;
  v_sid   bigint;
begin
  if v_id is not null then perform pg_advisory_xact_lock(hashtext('sortie_tx:' || p_operateur || ':' || v_id)); end if;
  select * into v_k from sorties_constatees where terminal = p_terminal and source_id = p_source_id and empreinte = v_emp;
  if found then
    v_deja := true;
    if v_k.numero_beneficiaire is null and v_num is not null then
      update sorties_constatees set numero_beneficiaire = v_num where id = v_k.id returning * into v_k;
    end if;
  else
    update terminaux set vu_le = now() where id = p_terminal;
    select * into v_float from floats where operateur = p_operateur and numero = normaliser_numero(p_float_numero) and terminal = p_terminal;
    -- 0039 : la sortie prolonge la chaîne des soldes (elle ne bloque jamais rien)
    if v_float.id is not null then
      perform pg_advisory_xact_lock(hashtext('float:' || v_float.id));
      v_c := _continuite(v_float, -1, p_montant, v_solde, nullif(p_frais, 0), nullif(p_commission, 0), v_quand);
    end if;
    insert into sorties_constatees (terminal, source_id, empreinte, float_id, operateur, float_numero, numero_beneficiaire, montant,
                                    reference_operateur, transaction_id, texte, emis_le, sortie_id, solde_apres, continuite)
    values (p_terminal, p_source_id, v_emp, v_float.id, p_operateur, p_float_numero, v_num, p_montant,
            p_reference, v_id, p_texte, p_emis_le, null, v_solde, v_c ->> 'etat')
    on conflict (terminal, source_id, empreinte) do nothing
    returning * into v_k;
    if v_float.id is not null and v_solde is not null and v_k.id is not null then
      insert into soldes_floats (float_id, solde, annonce_le, source, terminal, source_id, empreinte, fiable, mouvement, frais, commission, continuite, constatee_id)
      values (v_float.id, v_solde, v_quand, 'sms', p_terminal, p_source_id, v_emp, (v_c ->> 'etat') in ('verifiee', 'ignoree'),
              -p_montant, p_frais, p_commission, v_c ->> 'etat', v_k.id)
      on conflict (terminal, source_id, empreinte) where source = 'sms' and source_id is not null do nothing
      returning id into v_sid;
      if v_c ->> 'etat' = 'verifiee' and v_sid is not null then perform _reexaminer_continuite(v_float.id, v_quand); end if;
    end if;
  end if;
  select s.* into v_s from sorties s
   where v_id is not null and s.operateur = p_operateur
     and (exists (select 1 from sortie_paiements p where p.sortie_id = s.id and p.operateur = p_operateur and p.transaction_id = v_id and p.retire_le is null)
          or s.transaction_id = v_id)
   limit 1;
  if v_s.id is not null and v_s.mode = 'manuel' and v_s.etat = 'en_preuve' then
    begin
      v_s := _tenter_cloture(v_s.id);
    exception when others then   -- le SMS reste noté ; la sortie reste en preuve, et dit pourquoi
      update sorties set cloture_erreur = left(sqlerrm, 300) where id = v_s.id;
      perform _parite_alerter('cloture:' || v_s.reference, 'anomalie',
        format('%s : le SMS de la puce est arrivé mais la clôture a échoué (%s)', v_s.reference, sqlerrm), jsonb_build_object('reference', v_s.reference));
    end;
    select * into v_s from sorties where id = v_s.id;
  end if;
  return jsonb_strip_nulls(jsonb_build_object('resultat', 'constatee', 'id', v_k.id, 'deja', case when v_deja then true end,
    'sortie', v_s.reference, 'rapprochement', case when v_s.id is not null then _rapprochement(v_s) ->> 'etat' end,
    'cloture', case when v_s.etat = 'envoyee' then true end, 'continuite', v_k.continuite));
end $$;

-- ───────────────── 5 · les soldes seuls, et le relevé de l'équipe ──────────
create or replace function totem_solde_float(p_terminal text, p_operateur text, p_float_numero text, p_solde numeric,
                                             p_annonce_le timestamptz, p_source text, p_source_id bigint default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_float floats; v_id bigint; v_n int;
begin
  if p_source not in ('sms', 'ussd') then raise exception 'source inconnue'; end if;
  if p_solde is null or p_solde < 0 then return jsonb_build_object('resultat', 'refuse', 'motif', 'solde illisible'); end if;
  select * into v_float from floats
   where operateur = p_operateur and numero = normaliser_numero(p_float_numero) and terminal = p_terminal;
  if not found then return jsonb_build_object('resultat', 'refuse', 'motif', 'ce float n''est pas sur ce terminal'); end if;
  perform pg_advisory_xact_lock(hashtext('float:' || v_float.id));
  -- une heure dans le futur (horloge du modem déréglée) ne doit pas figer ce solde devant tous les suivants.
  -- fiable reste faux : une consultation USSD est sûre par sa SOURCE ; un solde lu dans un SMS seul ne l'est jamais.
  insert into soldes_floats (float_id, solde, annonce_le, source, terminal, source_id)
  values (v_float.id, round(p_solde, 2), least(coalesce(p_annonce_le, now()), now()), p_source, p_terminal, p_source_id)
  on conflict (terminal, source_id, empreinte) where source = 'sms' and source_id is not null do nothing
  returning id into v_id;
  if p_source = 'ussd' and v_id is not null then
    v_n := _reexaminer_continuite(v_float.id, least(coalesce(p_annonce_le, now()), now()));
  end if;
  return jsonb_strip_nulls(jsonb_build_object('resultat', case when v_id is null then 'deja' else 'note' end, 'float', v_float.id, 'reexaminees', v_n));
end $$;

create or replace function admin_saisir_releve(p_float int, p_solde numeric, p_annonce_le timestamptz, p_preuve text, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id bigint; v_n int;
begin
  perform _exiger_droit('rapprocher');
  if p_solde is null or p_solde < 0 or not (p_solde = round(p_solde, 2)) then raise exception 'solde invalide'; end if;
  if p_annonce_le is null or p_annonce_le > now() + interval '5 minutes' then raise exception 'la date du relevé est dans le futur'; end if;
  if coalesce(p_preuve, '') = '' then raise exception 'le relevé de l''opérateur est exigé : déposez le fichier'; end if;
  if not exists (select 1 from floats where id = p_float) then raise exception 'float inconnu'; end if;
  perform pg_advisory_xact_lock(hashtext('float:' || p_float));
  insert into soldes_floats (float_id, solde, annonce_le, source, preuve, note, saisi_par)
  values (p_float, p_solde, p_annonce_le, 'releve', p_preuve, left(p_note, 500), auth.uid())
  returning id into v_id;
  v_n := _reexaminer_continuite(p_float, p_annonce_le);
  perform _journaliser('saisir_releve', p_float::text, jsonb_build_object('solde', p_solde, 'annonce_le', p_annonce_le, 'reexaminees', v_n));
  return jsonb_build_object('ok', true, 'id', v_id, 'reexaminees', v_n);
end $$;

-- ────────────────────────── 6 · les gestes de l'équipe ─────────────────────
-- Libérer un SMS au solde à vérifier : l'équipe l'a vu dans l'historique de
-- l'opérateur. « Ancrer » : son solde est bien celui de l'opérateur, il devient
-- un appui, et les SMS suivants se vérifient d'eux-mêmes.
create or replace function admin_liberer_retenue(p_id bigint, p_ancrer boolean, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_r entrees_retenues; v_f int; v_op text; v_tx text; v jsonb; v_n int; v_note text := trim(coalesce(p_note, ''));
begin
  perform _exiger_droit('rapprocher');
  select float_id, operateur, transaction_id into v_f, v_op, v_tx from entrees_retenues where id = p_id;
  if not found then raise exception 'entrée inconnue'; end if;
  if v_f is not null then perform pg_advisory_xact_lock(hashtext('float:' || v_f)); end if;
  if length(coalesce(v_tx, '')) >= 6 then perform pg_advisory_xact_lock(hashtext('tx:' || v_op || ':' || v_tx)); end if;
  select * into v_r from entrees_retenues where id = p_id for update;
  if not coalesce(_retenue_pour_le_solde(v_r), false) then
    raise exception 'ce SMS n''attend pas de vérification de solde';
  end if;
  if length(v_note) < 10 then
    raise exception 'dites comment le paiement a été vérifié' using detail = 'par exemple : vu dans l''historique MoMo *126#';
  end if;
  if exists (select 1 from depot_paiements where terminal = v_r.terminal and source_id = v_r.source_id) then
    raise exception 'le message complet de ce SMS a déjà crédité un dépôt';
  end if;
  if length(coalesce(v_r.transaction_id, '')) >= 6
     and exists (select 1 from depot_declarations where operateur = v_r.operateur and transaction_id = v_r.transaction_id and etat = 'credite') then
    raise exception 'transaction ID déjà utilisé';
  end if;
  if coalesce(p_ancrer, false) then
    if v_r.solde_apres is null then raise exception 'ce SMS n''annonce pas de solde'; end if;
    update soldes_floats set fiable = true, continuite = 'liberee' where retenue_id = p_id;
  end if;
  update entrees_retenues set liberee_par = auth.uid(), liberee_le = now(), note_equipe = left(v_note, 500) where id = p_id;
  v := _reprendre_retenue(p_id, 'liberee');
  if coalesce(p_ancrer, false) and v_f is not null then
    v_n := _reexaminer_continuite(v_f, least(coalesce(v_r.emis_le, now()), now()));
  end if;
  -- le journal se garde longtemps et se lit à plusieurs : jamais le numéro du payeur
  perform _journaliser('liberer_retenue', p_id::text, jsonb_build_object('montant', v_r.montant, 'ancre', coalesce(p_ancrer, false), 'note', left(v_note, 500)));
  return jsonb_strip_nulls(jsonb_build_object('ok', true, 'credite', coalesce((v ->> 'credite')::boolean, false), 'reference', v ->> 'reference',
                                              'reexaminees', v_n));
end $$;

-- Rejeter : un faux SMS. Rien n'est crédité, rien n'est remboursé, et le
-- réexamen ne le reprend jamais.
create or replace function admin_rejeter_retenue(p_id bigint, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_r entrees_retenues; v_note text := trim(coalesce(p_note, ''));
begin
  perform _exiger_droit('rapprocher');
  select * into v_r from entrees_retenues where id = p_id for update;
  if not found then raise exception 'entrée inconnue'; end if;
  if v_r.etat <> 'retenue' then raise exception 'cette entrée n''est plus retenue' using detail = v_r.etat; end if;
  if length(v_note) < 3 then raise exception 'une note est exigée' using detail = 'pourquoi ce SMS est faux'; end if;
  update entrees_retenues set etat = 'rejetee', continuite = 'rejetee', note_equipe = left(v_note, 500), liberee_par = auth.uid(), liberee_le = now()
   where id = p_id;
  update soldes_floats set continuite = 'rejetee' where retenue_id = p_id;
  perform _journaliser('rejeter_retenue', p_id::text, jsonb_build_object('montant', v_r.montant, 'note', left(v_note, 500)));
  return jsonb_build_object('ok', true);
end $$;

-- Rapprocher et rembourser : jamais un SMS dont le solde est à vérifier. Le
-- rembourser est l'essentiel — sans ce garde, un faux SMS retenu se faisait
-- REMBOURSER, et l'argent réel partait chez le faussaire.
create or replace function admin_rapprocher_retenue(p_id bigint, p_reference text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_r entrees_retenues; v_d depots; v_x depot_declarations; v_tx text;
begin
  perform _exiger_droit('rapprocher');
  select * into v_r from entrees_retenues where id = p_id;
  if not found then raise exception 'entrée inconnue'; end if;
  if v_r.operateur is null or coalesce(v_r.montant, 0) <= 0 then
    raise exception 'opérateur ou montant inconnu' using detail = 'ce SMS ne se crédite pas : remboursement manuel';
  end if;
  -- un SMS dont la référence n'a pas été lue reçoit un identifiant à lui, pour qu'un second ne lui soit pas confondu
  v_tx := case when length(coalesce(v_r.transaction_id, '')) >= 6 then v_r.transaction_id
               else 'SMSRETENU' || v_r.id::text end;
  perform pg_advisory_xact_lock(hashtext('tx:' || v_r.operateur || ':' || v_tx));
  select * into v_r from entrees_retenues where id = p_id for update;
  if coalesce(_retenue_pour_le_solde(v_r), false) then
    raise exception 'solde à vérifier : libérez ou rejetez d''abord ce SMS';
  end if;
  if v_r.etat <> 'retenue' then raise exception 'cette entrée n''est plus retenue' using detail = v_r.etat; end if;
  if exists (select 1 from depot_paiements where terminal = v_r.terminal and source_id = v_r.source_id and empreinte = v_r.empreinte) then
    raise exception 'ce SMS a déjà crédité un dépôt';
  end if;
  select * into v_d from depots where reference = p_reference for update;
  if not found then raise exception 'dépôt inconnu'; end if;
  if v_d.etat = 'annule' then raise exception 'ce dépôt est annulé'; end if;
  if v_d.operateur <> v_r.operateur then raise exception 'l''opérateur du SMS n''est pas celui du dossier'; end if;
  if exists (select 1 from depot_declarations where operateur = v_r.operateur and transaction_id = v_tx and etat = 'credite') then
    raise exception 'transaction ID déjà utilisé';
  end if;
  -- la déclaration de CE compte pour cet ID est reprise sur ce dossier ; sinon on l'écrit
  select * into v_x from depot_declarations where compte_id = v_d.compte_id and operateur = v_r.operateur and transaction_id = v_tx for update;
  if found then
    update depot_declarations set depot_id = v_d.id, etat = 'attendu', motif = 'rapproché par l''administration'
     where id = v_x.id returning * into v_x;
  else
    insert into depot_declarations (depot_id, compte_id, operateur, transaction_id, motif)
    values (v_d.id, v_d.compte_id, v_r.operateur, v_tx, 'rapproché par l''administration')
    returning * into v_x;
  end if;
  v_x := _crediter_declaration(v_x.id, v_r.terminal, v_r.source_id, v_r.montant, v_r.numero_payeur, v_r.reference_operateur, v_r.texte, v_r.emis_le, v_r.id);
  if v_x.etat = 'credite' then
    -- les autres comptes qui attendaient ce même ID savent qu'il est pris
    update depot_declarations set etat = 'refuse', motif = 'rattaché à un autre dossier par l''équipe'
     where operateur = v_r.operateur and transaction_id = v_tx and etat = 'attendu';
  end if;
  perform _journaliser('rapprocher_retenue', p_id::text, jsonb_build_object('reference', p_reference, 'resultat', v_x.etat));
  return _declaration_json(v_x);
end $$;

create or replace function admin_rembourser_retenue(p_id bigint, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_r entrees_retenues; v_float floats; v_n int;
begin
  perform _exiger_droit('rembourser');
  select * into v_r from entrees_retenues where id = p_id for update;
  if not found then raise exception 'entrée inconnue'; end if;
  if coalesce(_retenue_pour_le_solde(v_r), false) then
    raise exception 'solde à vérifier : libérez ou rejetez d''abord ce SMS';
  end if;
  if v_r.etat <> 'retenue' then raise exception 'cette entrée n''est plus retenue' using detail = v_r.etat; end if;
  if v_r.numero_payeur is null or coalesce(v_r.montant, 0) <= 0 then raise exception 'payeur ou montant inconnu : remboursement manuel'; end if;
  if exists (select 1 from depot_paiements where terminal = v_r.terminal and source_id = v_r.source_id and empreinte = v_r.empreinte)
     or (length(coalesce(v_r.transaction_id, '')) >= 6
         and exists (select 1 from depot_declarations where operateur = v_r.operateur and transaction_id = v_r.transaction_id and etat = 'credite')) then
    raise exception 'ce paiement a déjà été crédité' using detail = 'le rembourser le paierait deux fois';
  end if;
  select * into v_float from floats where id = v_r.float_id;
  if not found or v_float.terminal is null then
    raise exception 'float inconnu : remboursement manuel' using detail = 'aucun boîtier ne porte la carte qui a reçu cet argent';
  end if;
  if exists (select 1 from remboursements where retenue_id = p_id and etat in ('en_attente', 'en_cours')) then
    raise exception 'un remboursement est déjà en route';
  end if;
  select count(*) + 1 into v_n from remboursements where retenue_id = p_id;
  insert into remboursements (retenue_id, terminal, float_id, operateur, numero, montant, note, cle)
  values (p_id, v_float.terminal, v_float.id, v_r.operateur, v_r.numero_payeur, v_r.montant, p_note, 'rbt-' || p_id::text || '-' || v_n::text);
  update entrees_retenues set etat = 'remboursee' where id = p_id;
  -- le journal se garde longtemps et se lit à plusieurs : la référence de l'entrée, jamais le numéro du payeur
  perform _journaliser('rembourser_retenue', p_id::text, jsonb_build_object('montant', v_r.montant, 'note', p_note, 'essai', v_n));
  return jsonb_build_object('ok', true, 'montant', v_r.montant, 'numero', v_r.numero_payeur);
end $$;

create or replace function admin_retenues(p_etat text default 'retenue', p_n int default 200) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  perform _exiger_droit('voir');
  select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'terminal', e.terminal, 'operateur', e.operateur, 'float_numero', e.float_numero,
                            'numero_payeur', e.numero_payeur, 'montant', e.montant, 'reference_operateur', e.reference_operateur,
                            'transaction_id', e.transaction_id, 'texte', e.texte, 'emis_le', e.emis_le, 'etat', e.etat,
                            'motif', e.motif, 'bloquee', e.bloquee,
                            'depot_reference', (select reference from depots where id = e.depot_id), 'cree_le', e.cree_le,
                            'compte_suggere', (select jsonb_build_object('id', c.id, 'nom', c.nom, 'telephone', c.telephone)
                                                 from comptes c where c.id = _proprietaire_du_numero(e.numero_payeur)),
                            -- 0039 : la continuité du solde
                            'solde_apres', e.solde_apres, 'solde_attendu', e.solde_attendu, 'continuite', e.continuite,
                            'solde_a_verifier', e.etat = 'retenue' and e.bloquee and coalesce(e.continuite in ('incoherente', 'absente', 'sans_ancre'), false)
                                                and e.motif is not distinct from _motif_continuite(e.continuite),
                            'ancre', (select jsonb_build_object('solde', s.solde, 'annonce_le', s.annonce_le, 'source', s.source) from soldes_floats s where s.id = e.ancre_id),
                            'liberee_le', e.liberee_le, 'note_equipe', e.note_equipe,
                            'liberee_par', (select coalesce(a.nom, a.email) from administrateurs a where a.id = e.liberee_par)) order by e.cree_le desc), '[]'::jsonb)
    into r
    from (select * from entrees_retenues where etat = p_etat order by cree_le desc limit p_n) e;
  return r;
end $$;

create or replace function admin_a_traiter() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _exiger_droit('voir');
  return jsonb_build_object(
    'sorties_manuelles', (select count(*) from sorties where mode = 'manuel' and etat in ('en_attente', 'en_cours')),
    'sorties_en_preuve', (select count(*) from sorties where mode = 'manuel' and etat = 'en_preuve'),
    'sorties_a_confirmer', (select count(*) from sorties s where s.mode = 'manuel' and s.etat = 'en_preuve' and _seuil_atteint(s) and s.confirmee_par is null),
    'sorties_en_ecart', (select count(*) from sorties s where s.mode = 'manuel' and s.etat = 'en_preuve' and _rapprochement(s) ->> 'etat' = 'ecart'),
    'montant_a_payer', (select coalesce(sum(s.montant_xaf - coalesce((select sum(p.montant) from sortie_paiements p where p.sortie_id = s.id and p.retire_le is null), 0)), 0)
                          from sorties s where s.mode = 'manuel' and s.etat in ('en_attente', 'en_cours', 'en_preuve')),
    -- 0039 : les SMS dont le solde ne suit pas, retenus pour l'équipe
    'retenues_solde', (select count(*) from entrees_retenues r where r.etat = 'retenue' and r.bloquee and coalesce(_retenue_pour_le_solde(r), false)),
    'sorties_non_expliquees', (select count(*) from sorties_constatees k where not _sms_sortant_explique(k)),
    'parite', (select jsonb_build_object('statut', p.statut, 'ecart', p.ecart, 'couverture', p.couverture, 'fait_le', p.fait_le,
                                         'alertes', (select count(*) from parite_alertes where close_le is null and gravite <> 'attention'))
                 from parite_releves p order by p.fait_le desc limit 1));
end $$;

-- ─────────────────────── 7 · la page publique, arrondie ────────────────────
-- Le solde exact d'un float est précisément ce qu'un faussaire doit connaître :
-- la page publique l'arrondit au million inférieur (la couverture aussi, sinon
-- registre + couverture le redonnerait). L'équipe garde l'exact.
create or replace function _arrondi_public(x numeric) returns numeric
language sql immutable set search_path = public as $$
  select case when x is null then null when x >= 0 then floor(x / 1e6) * 1e6 else -ceil(-x / 1e6) * 1e6 end
$$;

create or replace function _parite_json(p_detail boolean) returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object(
    'releve', (select case when p_detail then to_jsonb(p) - 'detail'
                           else to_jsonb(p) - 'detail' - 'floats' - 'couverture'
                                || jsonb_build_object('floats', _arrondi_public(p.floats), 'couverture', _arrondi_public(p.couverture), 'floats_arrondi', 1000000) end
                 || jsonb_build_object('reseaux', p.detail -> 'reseaux',
                 'floats_detail', case when p_detail then p.detail -> 'floats'
                                when coalesce((parametre('parite') ->> 'publier_floats')::boolean, true)
                                then (select coalesce(jsonb_agg(jsonb_build_object('operateur', o, 'solde', _arrondi_public(s), 'annonce_le', d, 'connu', c)), '[]'::jsonb)
                                        from (select x ->> 'operateur' o, sum((x ->> 'solde')::numeric) s, min((x ->> 'annonce_le')::timestamptz) d, bool_and((x ->> 'connu')::boolean) c
                                                from jsonb_array_elements(p.detail -> 'floats') x group by 1) g) end)
                 from parite_releves p order by p.fait_le desc limit 1),
    'historique', (select coalesce(jsonb_agg(jsonb_build_object('fait_le', fait_le, 'statut', statut, 'registre', registre, 'chaine', chaine, 'ecart', ecart,
                                                                'floats', case when p_detail then floats else _arrondi_public(floats) end) order by fait_le), '[]'::jsonb)
                     from (select * from parite_releves where fait_le > now() - interval '7 days' and (extract(minute from fait_le)::int % 60) < 5 order by fait_le) h),
    -- chaque réseau où le contrat XAFe est posé : c'est leur SOMME qui se compare au registre
    'contrats', (select coalesce(jsonb_agg(jsonb_build_object('reseau', r.id, 'nom', r.nom, 'contrat', parametre('chaine') -> r.id ->> 'xafe', 'explorateur', _explorateur(r.id),
                                                       'maison', r.id = _reseau_de_la_reserve(),
                                                       'reserve', (select etat ->> 'chaud' from chaine_etats e where e.reseau = r.id)) order by r.ordre), '[]'::jsonb)
                   from reseaux r where _reseau_configure(r.id)),
    'essai', coalesce((parametre('chaine') ->> 'essai')::boolean, false),
    -- la bêta : la part du registre qui est de l'argent de test (sans XAF derrière)
    'xafe_de_test', _xafe_de_test(),
    'lignes', (select coalesce(jsonb_agg(to_jsonb(l) - case when p_detail then '{}'::text[] else array['etat_registre', 'tx_attendu', 'adresse_vue'] end order by l.depuis desc), '[]'::jsonb)
                 from (select * from _parite_lignes() order by depuis desc limit case when p_detail then 500 else 100 end) l),
    'alertes', case when p_detail then (select coalesce(jsonb_agg(to_jsonb(a) order by a.ouverte_le desc), '[]'::jsonb)
                                          from parite_alertes a where a.close_le is null or a.close_le > now() - interval '7 days')
                    else (select count(*) from parite_alertes where close_le is null and gravite <> 'attention')::text::jsonb end)
$$;

-- ─────────────────────────────── 8 · les droits ────────────────────────────
revoke all on function _mode_continuite(text), _motif_continuite(text),
  _continuite(floats, int, numeric, numeric, numeric, numeric, timestamptz, bigint), _reprendre_retenue(bigint, text),
  _reexaminer_continuite(int, timestamptz), _retenue_pour_le_solde(entrees_retenues), _solde_float(int), _arrondi_public(numeric), _verifier_parametre(text, jsonb),
  totem_sms_recu(text, bigint, text, text, text, numeric, text, text, timestamptz, numeric, numeric, numeric),
  totem_sms_sortant(text, bigint, text, text, text, numeric, text, text, timestamptz, numeric, numeric, numeric),
  totem_solde_float(text, text, text, numeric, timestamptz, text, bigint),
  admin_saisir_releve(int, numeric, timestamptz, text, text), admin_liberer_retenue(bigint, boolean, text), admin_rejeter_retenue(bigint, text),
  admin_rapprocher_retenue(bigint, text), admin_rembourser_retenue(bigint, text), admin_retenues(text, int), admin_a_traiter()
  from public, anon, authenticated;
grant execute on function totem_sms_recu(text, bigint, text, text, text, numeric, text, text, timestamptz, numeric, numeric, numeric),
  totem_sms_sortant(text, bigint, text, text, text, numeric, text, text, timestamptz, numeric, numeric, numeric),
  totem_solde_float(text, text, text, numeric, timestamptz, text, bigint) to service_role;
grant execute on function admin_saisir_releve(int, numeric, timestamptz, text, text), admin_liberer_retenue(bigint, boolean, text),
  admin_rejeter_retenue(bigint, text), admin_rapprocher_retenue(bigint, text), admin_rembourser_retenue(bigint, text),
  admin_retenues(text, int), admin_a_traiter() to authenticated;   -- les gardes sont dedans (_exiger_droit)
$sql$;
    raise notice '0039_continuite_des_soldes.sql : appliquée';
  end if;
end $consolide$;

-- ─── 0040_reserve_dans_le_contrat.sql (md5 da853ba1ac69af297bd1c6a0ac82506e) ───
-- déjà en place si : rejouable telle quelle
